__mod["app.controller"] = function(...)
-- App controller: wires the model to fb (core polling, run state and events, UI slots, actions).
-- Everything the UI shows comes from view.view(); everything the user changes goes through
-- detect.set_place / model.corrections and the run (state and events), never into the view directly.
local util = require("model.util")
local rules = require("model.rules")
local state = require("model.state")
local detect = require("model.detect")
local snapshot = require("model.snapshot")
local events = require("model.events")
local corrections = require("model.corrections")
local view_mod = require("model.view")
local gym = require("model.gym")
local oras = require("data.oras")
local common = require("ui.common")
local corr_ui = require("ui.corrections")
local panel = require("ui.panel")
local hud = require("ui.hud")
local screen = require("ui.screen")
local tile = require("ui.tile")
local board = require("ui.board")
local sync = require("app.sync")
local icons_mod = require("app.icons")
local maps_mod = require("app.maps")

local A = {}
A.__index = A

A.POLL_MS = 500      -- team, place, battle, badges
A.BOX_MS = 5000      -- boxes
A.RENDER_MS = 250    -- at most 4 UI refreshes per second
A.BOARD_MS = 5000    -- run board
A.HUD_MS = 3000      -- HUD stays expanded after a linked death
A.NOTICE_TRIES = 40  -- renders to wait for the state that shows a death
A.MAX_ZONES = 120    -- learned zone mappings kept in the own state
A.CAL_STEPS = { [2] = true, [10] = true, [40] = true }
A.NAME_BUDGET = 16   -- core name() lookups per poll
A.CORE = "pokemon.core"

function A.new(fb)
  local self = setmetatable({}, A)
  self.fb = fb
  self.tr = function(key, vars) return fb.i18n.t(key, vars) end
  self.ui = {}
  self.events, self.seen = {}, {}
  self.queue = {}          -- death events waiting for the view
  self.tiles, self.tile_slots = {}, {}
  self.sync = sync.new(fb)
  self.last_poll, self.last_box, self.last_render, self.last_board = -1e9, -1e9, -1e9, -1e9
  self.dirty = true
  self.errors = {}
  self.unsupported = {} -- parts of pokemon.core that answered "unsupported"
  self.gnames = { species = {}, location = {} } -- names read from the game (core name())
  self.types = {}          -- "species:form" -> primary type id
  self.name_budget = A.NAME_BUDGET
  return self
end

local function warn_once(self, key, ...)
  if not self.errors[key] then
    self.errors[key] = true
    self.fb.log.warn(...)
  end
end

-- ---------------------------------------------------------------- names and areas from the core

local function int(v)
  if math.type(v) == "float" then v = math.tointeger(v) end
  if math.type(v) == "integer" then return v end
  return nil
end

--- Display name read from the game (`name(kind, id)`), cached; a few lookups per poll.
--- kind = "species" | "location". nil while the game text is not ready or unsupported.
function A:game_name(kind, id)
  id = int(id)
  if id == nil then return nil end
  local cached = self.gnames[kind][id]
  if cached then return cached end
  if kind == "location" and self.areas_info and self.areas_info.names[id] then return self.areas_info.names[id] end
  if self.name_unsupported or self.name_budget <= 0 or self.viewing then return nil end
  self.name_budget = self.name_budget - 1
  local ok, v, why = pcall(self.fb.call, A.CORE, "name", kind, id)
  if not ok or why == "unsupported" then self.name_unsupported = true; return nil end
  if type(v) == "string" and v ~= "" then
    self.gnames[kind][id] = v
    -- remembered in the run state: other players and the server show the name without a running game
    if self.st then state.note_name(self.st, kind == "species" and "sp" or "loc", id, v) end
    return v
  end
  return nil
end

--- Areas info from the encounter areas (`areas()` list) and the places (`locations()` list), either may be nil:
--- { set = encounter areas, order = encounter areas in game order, names = { [id] = name },
---   places = every place in game order }. Deduplicated by location id; a place without encounter slots
--- (town ...) is a place option but no route key.
local function build_info(areas, locs)
  local info = { set = {}, order = {}, names = {}, places = {} }
  local area_ids = {}
  for _, a in ipairs(areas or {}) do
    local id = type(a) == "table" and int(a.id) or nil
    if id and not info.set[id] then
      info.set[id] = true
      area_ids[#area_ids + 1] = id
      if type(a.name) == "string" and a.name ~= "" then info.names[id] = a.name end
    end
  end
  local seen = {}
  for _, l in ipairs(locs or {}) do
    local id = type(l) == "table" and int(l.id) or nil
    if id and not seen[id] then
      seen[id] = true
      info.places[#info.places + 1] = id
      if info.names[id] == nil and type(l.name) == "string" and l.name ~= "" then info.names[id] = l.name end
      if l.has_encounters == true and not info.set[id] then
        info.set[id] = true
        area_ids[#area_ids + 1] = id
      end
    end
  end
  for _, id in ipairs(area_ids) do
    if not seen[id] then seen[id] = true; info.places[#info.places + 1] = id end
  end
  if locs then
    for _, id in ipairs(info.places) do if info.set[id] then info.order[#info.order + 1] = id end end
  else
    info.order = area_ids
  end
  return info
end

A.REASK_MS = 5000      -- areas()/locations() asked again while not ready, failed, empty or unnamed
A.REFRESH_MS = 30000   -- a complete list is refreshed this often

--- A list is final when it has entries and all of them have a name.
local function final_list(list)
  if type(list) ~= "table" or #list == 0 then return false end
  for _, e in ipairs(list) do
    if type(e) ~= "table" or type(e.name) ~= "string" or e.name == "" then return false end
  end
  return true
end

--- Ask one list function of the core. Returns the list when it changed, nil otherwise; sets the next ask time.
--- "unsupported" is permanent; nil + "not_ready"/"failed", an empty list or entries without names are asked
--- again every REASK_MS, a complete list every REFRESH_MS.
function A:ask_list(fn, field, now)
  local ok, list, why = pcall(self.fb.call, A.CORE, fn)
  if not ok or why == "unsupported" then self[fn .. "_unsupported"] = true; return nil end
  if type(list) ~= "table" then self[fn .. "_next"] = now + (self[field] and A.REASK_MS or 2000); return nil end
  self[fn .. "_next"] = now + (final_list(list) and A.REFRESH_MS or A.REASK_MS)
  if util.encode(list) == util.encode(self[field] or false) then return nil end
  self[field] = list
  return list
end

--- Encounter areas (`areas()`) and places (`locations()`, optional, pokemon-core >= 0.3.1):
--- self.areas_info = { set, order, names, places }. nil while nothing is known. Both lists are asked again
--- until they are complete (see ask_list) and refreshed from time to time. A core without locations() works
--- with the areas alone.
function A:refresh_areas()
  if self.viewing then return end
  local now = self.fb.clock()
  local changed = false
  if not self.areas_unsupported and not (self.areas_next and now < self.areas_next) then
    if self:ask_list("areas", "area_list", now) then changed = true end
  end
  if not self.locations_unsupported and not (self.locations_next and now < self.locations_next) then
    if self:ask_list("locations", "loc_list", now) then changed = true end
  end
  if (self.area_list or self.areas_unsupported) and (changed or (not self.areas_info and self.loc_list)) then
    self.areas_info = build_info(self.area_list, self.loc_list)
    self.dirty = true
  end
end

--- Game data diagnostics of pokemon-core >= 0.3.2 (`diagnostics()`, a flat table of numbers and strings), only
--- asked once to learn whether the core has them, then every 5 s while the place list is empty or the "Game data" block is open (it is closed until the player opens it). A core
--- without it (unsupported) leaves self.diag nil and the block is omitted.
function A:refresh_diag()
  if self.viewing or self.diag_unsupported then return end
  local empty = not (self.areas_info and #self.areas_info.places > 0)
  if not (empty or common.diag_open(self.ui) or self.diag == nil) then return end
  local now = self.fb.clock()
  if self.diag_next and now < self.diag_next then return end
  self.diag_next = now + 5000
  local ok, v, why = pcall(self.fb.call, A.CORE, "diagnostics")
  if not ok or why == "unsupported" then self.diag_unsupported, self.diag = true, nil; return end
  if type(v) ~= "table" then return end
  local d = {}
  for k, x in pairs(v) do
    if type(k) == "string" and (type(x) == "number" or type(x) == "string" or type(x) == "boolean") then d[k] = x end
  end
  if util.encode(d) ~= util.encode(self.diag or {}) then self.diag, self.dirty = d, true end
end

--- Icon check (pokemon-core >= 0.3.4 `icon_variants(species, form?)`): while the "Game data" block is open, asked
--- once per opening for the first team creature: up to 4 `{ label, desc, png }` variants, written to the cache as
--- `diag/icon-<label>.png` and shown side by side in the block. `nil, "not_ready"` is retried every 5 s;
--- `unsupported` (older core) switches it off for good and the section stays hidden.
function A:refresh_icon_check()
  if self.viewing or self.variants_unsupported then return end
  if not common.diag_open(self.ui) then
    if self.icheck ~= nil or self.icheck_done then self.icheck, self.icheck_done, self.icheck_next = nil, false, nil; self.dirty = true end
    return
  end
  if self.icheck_done then return end
  local now = self.fb.clock()
  if self.icheck_next and now < self.icheck_next then return end
  local first = self.first_team -- first creature of the team as the core reports it
  local species = first and int(first.species)
  if not species then return end
  local form = int(first.form) or 0
  local ok, list, why = pcall(self.fb.call, A.CORE, "icon_variants", species, form)
  if not ok or why == "unsupported" then self.variants_unsupported, self.icheck = true, nil; return end
  if list == nil and why == "not_ready" then self.icheck_next = now + 5000; return end
  self.icheck_done = true -- asked once per opening
  if type(list) ~= "table" then return end
  local items = {}
  for _, v in ipairs(list) do
    if #items >= 4 then break end
    if type(v) == "table" and type(v.label) == "string" and v.label:match("^%u$") and type(v.png) == "string" and #v.png > 0 then
      local name = "diag/icon-" .. v.label .. ".png"
      if pcall(self.fb.cache.write, name, v.png) then
        items[#items + 1] = { label = v.label, desc = util.clean_text(v.desc, 60) or "", src = "cache:" .. name }
      end
    end
  end
  if #items > 0 then self.icheck, self.dirty = { species = species, form = form, items = items }, true end
end

--- Primary type of a species (`species_info`), cached; nil when unknown.
function A:primary_type(species, form)
  species = int(species)
  if species == nil or self.types_unsupported then return nil end
  local key = species .. ":" .. tostring(int(form) or 0)
  if self.types[key] ~= nil then return self.types[key] or nil end
  local ok, v, why = pcall(self.fb.call, A.CORE, "species_info", species, int(form) or 0)
  if not ok or why == "unsupported" then self.types_unsupported = true; return nil end
  local t = type(v) == "table" and type(v.types) == "table" and int(v.types[1]) or nil
  if t ~= nil then self.types[key] = t end
  return t
end

--- Primary types of the partners' counted creatures on a route.
function A:partner_types(route)
  local out = {}
  for uid, st in pairs(self:states()) do
    local e = uid ~= self.me and type(st) == "table" and type(st.routes) == "table" and st.routes[route]
    local m = e and e.status == "caught" and e.mon and type(st.mons) == "table" and st.mons[e.mon]
    if m and m.ty ~= nil then out[m.ty] = true end
  end
  return out
end

--- Species name for texts: the record's own text, the game, or the names stored in the run.
function A:species_text(id, hint)
  if type(hint) == "string" and hint ~= "" then return hint end
  local live = self:game_name("species", id)
  if live then return live end
  local nm = self.view and self.view.names and self.view.names.sp[tostring(id)]
  if nm then return nm end
  local own = self.st and self.st.names and self.st.names.sp[tostring(id)]
  return own
end

function A:area_name(id)
  id = int(id)
  return id and ((self.areas_info and self.areas_info.names[id]) or self.gnames.location[id]) or nil
end

-- ---------------------------------------------------------------- start

function A:start()
  local fb, tr = self.fb, self.tr
  fb.ui.on_action(function(action, value, slot) self:on_action(action, value, slot) end)
  if not fb.run then
    self.sync:push("panel", panel.empty(tr))
    self.sync:push("hud", hud.empty(tr))
    self.sync:push("screen", screen.empty(tr))
    return
  end
  self.run = fb.run.current()
  self.me = self.run.me
  self.viewing = self.run.view == true -- run view of the Runs screen: shell context, read only
  -- run view: no game, so no core calls, no tracking, no notices; only the `run` slot shows the run
  if self.viewing then self.sync:push("screen", screen.empty(tr)) end
  self.icons = icons_mod.new(fb)
  self.maps = maps_mod.new(fb, not self.viewing)
  self.st = state.ensure(util.copy(fb.run.state()))
  self.last_enc = (not self.viewing and fb.run.state()) and util.encode(self.st) or nil
  self:load_events()
  self.live = not self.viewing
  fb.run.on("event", function(ev) self:on_event(ev) end)
  fb.run.on("state", function() self.dirty = true end)
  fb.run.on("participants", function() self.dirty = true end)
  fb.run.on("status", function() self.dirty = true end)
  if not self.viewing then
    fb.events.on("fb", "tiles", function(list) self.tiles = type(list) == "table" and list or {}; self.dirty = true end)
    if self.maps.api then
      fb.events.on("fb", "video.captured", function(e) if self.maps:on_captured(e) then self.dirty = true end end)
    end
  end
  fb.on_tick(function() self:tick() end)
  self:poll(true)
  self:render()
end

function A:load_events()
  local after = 0
  while true do
    local page = self.fb.run.events(after, 500)
    for _, ev in ipairs(page) do
      if not self.seen[ev.seq] then
        self.seen[ev.seq] = true
        self.events[#self.events + 1] = ev
      end
      after = math.max(after, ev.seq)
    end
    if #page < 500 then break end
  end
end

function A:writable() return common.writable(self.run) end

-- ---------------------------------------------------------------- ticking

function A:tick()
  local now = self.fb.clock()
  if self.writable_cached ~= self:writable() then
    self.writable_cached = self:writable()
    self.dirty = true
  end
  if now - self.last_poll >= A.POLL_MS then
    local full = now - self.last_box >= A.BOX_MS
    self.last_poll = now
    if full then self.last_box = now end
    local ok, err = pcall(self.poll, self, full)
    if not ok then warn_once(self, "poll", "poll failed: " .. tostring(err)) end
  end
  if not self.viewing and self.icons and self.icons:pump(now) then self.dirty = true end
  if not self.viewing and self.maps and self.maps:files_step(now) then self.dirty = true end
  if self.hud_until and now >= self.hud_until then
    self.hud_until, self.hud_text = nil, nil
    self.dirty = true
  end
  if self.board_due and now - self.last_board >= A.BOARD_MS then self.dirty = true end
  if self.dirty and now - self.last_render >= A.RENDER_MS then
    local ok, err = pcall(self.render, self)
    if not ok then warn_once(self, "render", "render failed: " .. tostring(err)) end
  end
end

-- ---------------------------------------------------------------- polling and state

function A:poll(full)
  if not self:writable() then return end
  local cfg = rules.parse(self.run)
  local snap = snapshot.from_core(self.fb, { skip_boxes = (not full) and self.boxes ~= nil, boxes = self.boxes,
    unsupported = self.unsupported })
  if snap.boxes then self.boxes = snap.boxes end
  local t1 = type(snap.team) == "table" and snap.team[1] or nil
  if type(t1) == "table" and int(t1.species) then self.first_team = { species = t1.species, form = t1.form } end
  local game = self.fb.game or {}
  local loc = type(snap.location) == "table" and snap.location or {}
  self.cur_zone, self.cur_loc = int(loc.zone), int(loc.location)
  if self.cur_zone ~= nil or self.cur_loc ~= nil then self.location_ok = true end
  if snap.badges ~= nil then self.badges_seen = true end
  self.name_budget = A.NAME_BUDGET
  self:refresh_areas()
  self:refresh_diag()
  self:refresh_icon_check()
  -- corrections about this player's routes (doesn't count, missed, added by hand) shape detection too
  local overrides, excluded = corrections.route_overrides(corrections.effective(self.events), self.me, self.st)
  local st, facts = detect.diff(self.st, snap, cfg, { now = self.fb.clock(), overrides = overrides, excluded = excluded, game = { id = game.code, language = game.language },
    zones = view_mod.merge_zones(self.run, self:states()),
    areas = self.areas_info, areas_unsupported = self.areas_unsupported,
    names = { species = function(id) return self:game_name("species", id) end },
    types = function(species, form) return self:primary_type(species, form) end,
    partner_types = function(route) return self:partner_types(route) end })
  self:commit(st, facts)
  self:gym_snapshot(snap)
end

--- Save snapshot "before Gym N" once when a gym leader battle starts (model.gym decides). Needs the app's
--- fb.save (Uzume 0.20+); on an older app fb.save is nil and nothing happens. The app limits snapshots to one
--- per minute, so a refusal is retried on the next polls of the same battle (gym.MAX_ATTEMPTS).
function A:gym_snapshot(snap)
  if self.viewing or self.save_missing then return end
  local save = self.fb.save
  if type(save) ~= "table" or type(save.snapshot) ~= "function" then
    self.save_missing = true
    return
  end
  local n = gym.gym_number(snap.battle, self.st and self.st.badges, oras.level_cap)
  if not n then
    self.gym_tries = nil
    return
  end
  self.gym_done = self.gym_done or {}
  if self.gym_done[n] then return end
  self.gym_tries = self.gym_tries or {}
  if (self.gym_tries[n] or 0) >= gym.MAX_ATTEMPTS then return end
  self.gym_tries[n] = (self.gym_tries[n] or 0) + 1
  local ok, res, why = pcall(save.snapshot, self.tr("snapshot_gym", { n = n }))
  if ok and res == true then
    self.gym_done[n] = true
    self.fb.log.info("save snapshot before gym " .. n)
  else
    warn_once(self, "snapshot", "save snapshot refused: " .. tostring(ok and why or res))
  end
end

--- Adopt a new own state, publish it when it changed and post the facts as automatic events.
function A:commit(st, facts)
  state.guard(st)
  self.st = st
  local enc = util.encode(st)
  if enc ~= self.last_enc then
    if self:writable() then
      local ok, why = self.fb.run.setState(st)
      if ok then self.last_enc = enc else warn_once(self, "setState", "setState refused: " .. tostring(why)) end
    end
    self.dirty = true
  end
  for _, f in ipairs(facts or {}) do self:post_fact(f) end
  if facts and #facts > 0 then self.dirty = true end
end

function A:player_name(id)
  for _, p in ipairs(self.run.participants or {}) do
    if p.user_id == id then return p.name or p.user_name or id end
  end
  return tostring(id)
end

--- Context for labels outside a render (names from the view or the own state, live area names).
function A:label_ctx()
  local view = self.view or { names = (self.st and self.st.names) or { sp = {}, loc = {} } }
  return { tr = self.tr, view = view, area_name = function(id) return self:area_name(id) end }
end

function A:place_text(route)
  return route and common.route_label(self:label_ctx(), route) or self.tr("place_none")
end

function A:fact_text(f, user)
  local tr = self.tr
  local player = self:player_name(user or self.me)
  local sname = f.species and self:species_text(f.species, f.species_name) or nil
  local mon = common.mon_name({ nickname = f.nickname, species = f.species, species_name = sname })
  local text
  if f.kind == "catch" then
    text = f.route and tr("ev_catch", { player = player, mon = mon, place = self:place_text(f.route) })
      or tr("ev_catch_noplace", { player = player, mon = mon })
  elseif f.kind == "death" then
    text = tr("ev_death", { player = player, mon = mon })
  elseif f.kind == "encounter" then
    local m = common.species_label({ species = f.species, species_name = sname })
    text = f.route and tr("ev_encounter", { player = player, mon = m, place = self:place_text(f.route) })
      or tr("ev_encounter_noplace", { player = player, mon = m })
  elseif f.kind == "missed" then
    text = f.route and tr("ev_missed", { player = player, place = self:place_text(f.route) })
      or tr("ev_missed_noplace", { player = player })
  elseif f.kind == "badge" then
    text = tr("ev_badge", { player = player, n = f.index })
  elseif f.kind == "place" then
    text = tr("ev_place", { player = player, place = f.key and self:place_text(f.key) or (f.name or tr("place_none")) })
  end
  if text and f.why then text = text .. " " .. tr("ev_why_" .. f.why) end
  return text and util.clean_text(text, 280) or nil
end

--- Text of an automatic event worded again from its payload (ids), with the names known now.
function A:event_text(ev)
  if ev.source ~= "automatic" or type(ev.payload) ~= "table" then return nil end
  local p, ty = ev.payload, ev.type
  local f
  if ty == events.TYPES.catch then
    f = { kind = "catch", route = p.route, species = p.species, species_name = p.species_name,
          nickname = p.nickname, why = p.why }
  elseif ty == events.TYPES.death then
    f = { kind = "death", species = p.species, species_name = p.species_name, nickname = p.nickname }
  elseif ty == events.TYPES.encounter then
    f = { kind = p.outcome == "missed" and "missed" or "encounter", route = p.route, species = p.species,
          species_name = p.species_name, why = p.outcome ~= "missed" and p.why or nil }
  elseif ty == events.TYPES.place then
    f = { kind = "place", key = p.route, name = p.name }
  elseif ty == events.TYPES.badge then
    f = { kind = "badge", index = p.index }
  end
  return f and self:fact_text(f, ev.user_id) or nil
end

--- True when the own participant already has a badge event for this badge number (restart, lost state).
function A:badge_posted(index)
  for _, ev in ipairs(self.events) do
    if ev.type == events.TYPES.badge and ev.user_id == self.me and type(ev.payload) == "table"
        and ev.payload.index == index then
      return true
    end
  end
  return false
end

function A:post_fact(f)
  local spec = events.from_fact(f, self.me)
  if not spec or not self:writable() then return end
  if f.kind == "badge" and self:badge_posted(f.index) then return end
  spec.text = self:fact_text(f)
  local ok, err = pcall(self.fb.run.event, spec)
  if not ok then warn_once(self, "event", "event refused: " .. tostring(err)) end
  if f.kind == "place" and f.key and not f.manual then self:note_place(f.key) end
end

-- ---------------------------------------------------------------- events and notices

function A:on_event(ev)
  if type(ev) ~= "table" or self.seen[ev.seq] then return end
  self.seen[ev.seq] = true
  local n = #self.events
  self.events[n + 1] = ev
  if n > 0 and self.events[n].seq > ev.seq then
    table.sort(self.events, function(a, b) return a.seq < b.seq end)
  end
  self.dirty = true
  if not self.live then return end
  local p = type(ev.payload) == "table" and ev.payload or {}
  if ev.type == events.TYPES.death then
    self.queue[#self.queue + 1] = { ev = ev, tries = 0 }
  elseif ev.type == events.TYPES.catch and ev.user_id ~= self.me and p.counts then
    local who = { player = self:player_name(ev.user_id), mon = common.mon_name({ nickname = p.nickname, species = p.species,
      species_name = self:species_text(p.species, p.species_name) }) }
    if p.route then who.place = self:place_text(p.route) end
    self:notify({ tone = "info", text = self.tr(p.route and "note_catch" or "note_catch_noplace", who) })
  end
end

function A:notify(n)
  n.title = n.title or self.tr("note_title")
  local ok, id = pcall(self.fb.ui.notify, n)
  if not ok then warn_once(self, "notify", "notify failed: " .. tostring(id)) end
  return ok and id or nil
end

function A:note_place(route)
  local row = self.view and common.row_of(self.view, route)
  local cell = row and row.cells[self.me]
  if cell and cell.state ~= "open" then return end
  self:notify({ tone = "info", text = self.tr("note_new_place", { place = self:place_text(route) }) })
end

-- Deaths in the own link groups: toast (important) and HUD expansion.
function A:process_queue(view)
  local keep = {}
  local groups = common.groups(view)
  for _, q in ipairs(self.queue) do
    local ev, p = q.ev, q.ev.payload or {}
    local owner = common.player(view, ev.user_id)
    local mon = owner and owner.mons[p.mon]
    local g = mon and mon.group and groups[mon.group]
    local handled = false
    if g and g.state == "dead" then
      local mine
      for _, m in ipairs(g.members) do if m.owner == self.me then mine = m end end
      if mine then
        local partners = math.max(g.count - 1, 0)
        local text
        if ev.user_id == self.me then
          text = self.tr("note_death_own", { mon = common.mon_name(mon), n = partners })
        else
          text = self.tr("note_death_linked", { player = owner.name, mon = common.mon_name(mon), mine = common.mon_name(mine) })
        end
        self:notify({ tone = "important", text = text, actions = {
          { label = self.tr("open_run"), action = "open_run" },
          { label = self.tr("undo_death"), action = "undo_open", value = g.route },
        } })
        self.hud_until = self.fb.clock() + A.HUD_MS
        self.hud_text = self.tr("hud_death", { n = g.number or 0, mon = common.mon_name(mon), count = partners })
      end
      handled = true
    elseif q.tries >= A.NOTICE_TRIES or (mon and not mon.group) then
      handled = true
    end
    if not handled then
      q.tries = q.tries + 1
      keep[#keep + 1] = q
      self.dirty = true
    end
  end
  self.queue = keep
end

-- ---------------------------------------------------------------- rendering

function A:states()
  local states = self.fb.run.states()
  if not self.viewing and self.me and states[self.me] == nil and self.st then states[self.me] = self.st end
  return states
end

--- True when pokemon.core serves demo data (info().demo); asked until the core answers, then remembered.
function A:core_demo()
  if self.demo_known then return self.demo_flag end
  local ok, info = pcall(self.fb.call, "pokemon.core", "info")
  if ok and type(info) == "table" then
    self.demo_known, self.demo_flag = true, info.demo == true
    return self.demo_flag
  end
  return false
end

function A:ctx(view)
  return { demo = self:core_demo(), view = view, run = self.run, me = self.me, ui = self.ui, tr = self.tr, readonly = not self:writable(),
           events = self.events, hud_death = self.hud_until and self.hud_text or nil,
           map = self.maps and self.maps:view() or nil, diag = self.diag, icheck = self.icheck,
           can_open = type(self.fb.ui.open) == "function", location_ok = self.location_ok == true,
           badges_manual = not self.badges_seen,
           area_name = function(id) return self:area_name(id) end,
           event_text = function(ev) return self:event_text(ev) end,
           icon = self.icons and function(species, form) return self.icons:src(species, form) end or nil }
end

function A:render()
  local fb = self.fb
  self.dirty = false
  local now = fb.clock()
  self.last_render = now
  self.run = fb.run.current()
  local cfg = rules.parse(self.run)
  local view = view_mod.view(self.run, self:states(), self.events, cfg)
  self.view = view
  self:process_queue(view)
  local ctx = self:ctx(view)
  if self.viewing then
    -- read-only run section of the Runs screen: the run screen without correction forms or actions
    self.sync:push("run", screen.build(ctx))
    return
  end
  self.sync:push("panel", panel.build(ctx))
  self.sync:push("hud", hud.build(ctx))
  self.sync:push("screen", screen.build(ctx))

  local matched = tile.match(self.tiles, view)
  local live = {}
  for id, p in pairs(matched) do
    local slot = "tile:" .. id
    live[slot] = true
    self.sync:push(slot, tile.build(self.tr, p, view))
  end
  for slot in pairs(self.tile_slots) do
    if not live[slot] then self.sync:clear(slot) end
  end
  self.tile_slots = live

  if self:writable() then
    local tree = board.build(ctx)
    local enc = util.encode(tree)
    if enc == self.last_board_enc then
      self.board_due = false
    elseif now - self.last_board >= A.BOARD_MS then
      self.board_due = false
      self.last_board = now
      if fb.run.setBoard(tree) then self.last_board_enc = enc end
    else
      self.board_due = true
    end
  end
end

-- ---------------------------------------------------------------- corrections

function A:correction_text(spec)
  local p, tr = spec.payload, self.tr
  local mon
  local owner = self.view and p.user and common.player(self.view, p.user)
  if owner and p.mon and owner.mons[p.mon] then mon = common.mon_name(owner.mons[p.mon]) end
  if p.kind == "add" then mon = common.mon_name({ nickname = p.nickname, species = p.species }) end
  return util.clean_text(tr("ev_c_" .. p.kind, {
    player = self:player_name(self.me), target = p.user and self:player_name(p.user) or "",
    route = p.route and self:place_text(p.route) or (p.group and p.group ~= "none" and self:place_text(p.group)) or "",
    mon = mon or "?", seq = p.target or "", reason = p.reason or "",
  }), 280)
end

--- Post a manual correction event. Returns true when it was accepted.
function A:post_correction(spec)
  if not self:writable() then return false end
  local ok_valid = corrections.validate_spec(spec)
  if not ok_valid then return false end
  spec.text = self:correction_text(spec)
  local ok, id = pcall(self.fb.run.event, spec)
  if not ok or id == nil then return false end
  self.dirty = true
  return true
end

local function my_player(self) return self.view and common.player(self.view, self.me) end

function A:open_corr(corr)
  corr.user = corr.user or self.me
  self.ui.corr = corr
  self.dirty = true
end

local function field_value(field, value)
  if field == "species" or field == "level" then
    local n = tonumber(value)
    return n and math.tointeger(n) or nil
  elseif field == "gift" then
    return value == true
  end
  if type(value) == "string" then return util.clean_text(value, 280) or "" end
  return value
end

--- May the own state record a mapping for `zone`? Not when the static table has it or another
--- player's mapping is in use; the own mapping can be changed; the number is limited.
function A:can_learn(zone)
  if oras.ZONES[zone] ~= nil then return false end
  local own = self.st.zones and self.st.zones[tostring(zone)]
  if own ~= nil then return true end
  if view_mod.merge_zones(self.run, self:states())[zone] ~= nil then return false end
  local n = 0
  for _ in pairs(self.st.zones or {}) do n = n + 1 end
  return n < A.MAX_ZONES
end

function A:learn_zone(st, zone, value)
  if zone and self:can_learn(zone) then
    st.zones = st.zones or {}
    st.zones[tostring(zone)] = value
  end
end

function A:set_place(input)
  if not self:writable() then return end
  local st, fact = detect.set_place(self.st, input, nil, self.cur_zone, self.cur_loc)
  local key = st.place.key
  local id = key and oras.area_id(key)
  if id then state.note_name(st, "loc", id, self:game_name("location", id)) end
  -- fallback without a location id: the answer for a reported zone is remembered and shared
  if key and key ~= oras.STARTER and not (self.cur_loc and self.areas_info) then
    self:learn_zone(st, self.cur_zone, key)
  end
  self:commit(st, { fact })
end

-- ---------------------------------------------------------------- map setup and calibration

function A:calib_route(route)
  local c = self.ui.calib
  if not c or not oras.is_route(route) then return end
  local m = self.maps
  c.route, c.msg = route, nil
  local at = m:merged()[route]
  c.x, c.y = at and at.x or (m.w or 0) // 2, at and at.y or (m.h or 0) // 2
end

function A:map_action(action, value)
  local m, c = self.maps, self.ui.calib
  if not m then return end
  if action == "map_capture" then
    m:capture()
  elseif action == "map_remove" then
    m:remove()
    self.ui.calib = nil
  elseif action == "crop_toggle" then
    self.ui.crop_open = not self.ui.crop_open
    if self.ui.crop_open and not m.pending then m:preset(m.crop and "applied" or "none") end
  elseif action == "map_src:screen" or action == "map_src:files" then
    self.ui.map_src = action:sub(9) -- chips carry the value in the action name
  elseif action == "map_prev" or action == "map_next" then
    m:files_nav(action == "map_next" and 1 or -1, self.fb.clock())
  elseif action == "map_use" then
    if m:files_use() then
      self.ui.calib = nil
      self.ui.map_src = nil
    end
  elseif action == "crop_adj" then
    local side, d = tostring(value):match("^([tblr]):(-?%d+)$")
    if side then m:adjust(side, math.tointeger(tonumber(d))) end
  elseif action == "crop_preset" then
    m:preset(value)
  elseif action == "calib_toggle" then
    self.ui.calib = (not c and m.state == "ready") and { step = 10 } or nil
    m.order = self.view and self.view.order or nil
    if self.ui.calib then
      -- preselect the current place of this player (when it can carry a position)
      local me = self.view and self.me and common.player(self.view, self.me)
      local key = me and common.place_value(me.place)
      if key and oras.is_route(key) then self:calib_route(key) end
    end
  elseif c and action == "calib_route" then
    self:calib_route(value)
  elseif c and action == "calib_group" then
    local groups = common.place_groups(self:ctx(self.view), c.route)
    local g = math.type(value) == "integer" and groups[value]
    if g then
      c.group = value
      if g.opts[1] then self:calib_route(g.opts[1].value) end
    end
  elseif c and action == "calib_step" then
    if A.CAL_STEPS[value] then c.step = value end
  elseif c and action == "calib_move" and c.x then
    local d, n = ({ l = { -1, 0 }, r = { 1, 0 }, u = { 0, -1 }, d = { 0, 1 } })[value], c.step or 10
    if d then
      c.x = math.max(0, math.min(m.w, c.x + d[1] * n))
      c.y = math.max(0, math.min(m.h, c.y + d[2] * n))
      c.msg = nil
    end
  elseif c and action == "calib_set" and c.route and c.x then
    c.msg = m:set_coord(c.route, c.x, c.y) and "saved" or "failed"
  elseif c and action == "calib_export" then
    m.order = self.view and self.view.order or nil
    c.msg = m:export_line() and "exported" or "none"
  end
  self.dirty = true
end

-- ---------------------------------------------------------------- actions

--- Open the run screen (screen slot) over the game: fb.ui.open("screen"), only when the platform has it.
--- Without it the panel says so (ctx.can_open).
function A:open_screen()
  if self.viewing or type(self.fb.ui.open) ~= "function" then return false end
  local ok, err = pcall(self.fb.ui.open, "screen")
  if not ok then warn_once(self, "open", "ui.open failed: " .. tostring(err)) end
  return ok
end

function A:on_action(action, value, slot)
  if slot == "hotkey" then
    if action == "toggle-hud" then return end -- the host shows or hides the widget
    if action == "open-run" then action = "open_run"
    elseif action == "doesnt-count" then action, value = "dc_open", nil
    else return end
  end
  if not self.run then return end
  local me = my_player(self)
  local writable = self:writable()

  if action == "open_run" then
    self.ui.screen_tab_id = nil -- the screen opens on its first tab
    self.dirty = true
    self:open_screen()
  elseif action == "place_toggle" then self.ui.place_open = not self.ui.place_open; self.dirty = true
  elseif action == "diag_toggle" then self.ui.diag_open = not common.diag_open(self.ui); self.diag_next = nil; self.dirty = true
  elseif action == "rules_toggle" then self.ui.rules_open = not self.ui.rules_open; self.dirty = true
  elseif action == "grave_toggle" then self.ui.grave_open = not self.ui.grave_open; self.dirty = true
  elseif action == "hud_toggle" then self.ui.hud_expanded = not self.ui.hud_expanded; self.dirty = true
  elseif action == "tab" then
    if math.type(value) == "integer" and self.view then
      local ids = screen.tab_ids(self:ctx(self.view))
      self.ui.screen_tab_id = ids[value]
      self.dirty = true
    end
  elseif action:sub(1, 3) == "rf:" then self.ui.routes_filter = action:sub(4); self.dirty = true
  elseif action:sub(1, 3) == "lf:" then self.ui.log_filter = action:sub(4); self.dirty = true
  elseif action == "log_person" then
    self.ui.log_person = (type(value) == "string" and value ~= "all") and value or nil
    self.dirty = true
  elseif action == "route_select" then self.ui.selected_route = value; self.dirty = true
  elseif action == "map_select" then
    if type(value) == "table" then
      if value.kind == "route" then
        self.ui.selected_route = value.id
        if self.ui.calib and oras.is_route(value.id) then self:calib_route(value.id) end
      elseif value.kind == "filter" then self.ui.map_filter = value.value end
      self.dirty = true
    end
  elseif action:sub(1, 6) == "calib_" or action:sub(1, 4) == "map_" or action:sub(1, 5) == "crop_" then
    self:map_action(action, value)
  elseif not writable then
    return
  elseif action == "zone_none" then
    if self.cur_zone then
      local st = util.copy(self.st)
      self:learn_zone(st, self.cur_zone, false)
      self:commit(st, {})
    end
  elseif action == "place_select" then
    if type(value) == "string" then self:set_place(value) end
  elseif action == "place_text" then
    self:set_place(type(value) == "string" and value or "")
  elseif action == "badges_select" then
    if math.type(value) == "integer" and value >= 0 and value <= 8 then
      local st = util.copy(self.st)
      st.badges = value
      self:commit(st, {})
    end
  elseif action == "mark_dead" then
    if type(value) == "string" then
      self:post_correction(corrections.mark_dead({ user = self.me, mon = value }))
    end
  elseif action == "dc_open" then
    local route = value or (me and me.place.key)
    if route then
      local corr = { kind = "doesnt_count", route = route, reason = "wrong" }
      local row = common.row_of(self.view, route)
      local cell = row and row.cells[self.me]
      if cell and cell.mon then corr.mon = cell.mon end
      self:open_corr(corr)
    end
  elseif action == "missed_open" then
    if type(value) == "string" then self:open_corr({ kind = "mark_missed", route = value }) end
  elseif action == "undo_open" then
    local g = type(value) == "string" and common.groups(self.view)[value]
    if g then
      self:open_corr({ kind = "undo_death", group = g.route, number = g.number, members = g.members,
        undone = corrections.undo_entries(g) })
    end
  elseif action == "group_open" then
    local m = me and me.mons[value]
    if m then self:open_corr({ kind = "set_group", mon = m.id, group = m.group or "none" }) end
  elseif action == "gift_open" then
    if me and me.mons[value] then self:open_corr({ kind = "set_gift", mon = value, gift = true }) end
  elseif action == "dead_open" then
    if me and me.mons[value] then self:open_corr({ kind = "mark_dead", mon = value }) end
  elseif action == "add_open" then
    self:open_corr({ kind = "add", route = me and me.place.key and oras.is_key(me.place.key) and me.place.key or oras.STARTER,
      state = "box" })
  elseif action == "revert_open" then
    if math.type(value) == "integer" then self:open_corr({ kind = "revert", target = value }) end
  elseif action:sub(1, 3) == "cf:" then
    local corr = self.ui.corr
    if corr then
      local field = action:sub(4)
      corr[field] = field_value(field, value)
      corr.error = nil
      self.dirty = true
    end
  elseif action == "corr_cancel" then
    self.ui.corr = nil; self.dirty = true
  elseif action == "corr_submit" then
    local corr = self.ui.corr
    if corr then
      local spec, err = corr_ui.to_spec(corr)
      if not spec then
        corr.error = err
      elseif self:post_correction(spec) then
        self.ui.corr = nil
      else
        corr.error = "c_err_post"
      end
      self.dirty = true
    end
  end
end

return A

end
__mod["app.icons"] = function(...)
-- Creature icons from pokemon-core `icon(species, form)` (PNG string, or nil + "not_ready" /
-- "unsupported"), fetched lazily and cached in the own cache as `icons/<rev>/<species>-<form>.png`, with
-- `<rev>` = info().icon_rev of the core (a fixed icon decoder gets a new folder); a core without a valid
-- icon_rev keeps `icons/<species>-<form>.png`. The revision is read once, retried while info() fails.
-- The UI asks for `src(species, form)` while rendering: nil until the file is in the cache, so the
-- builders fall back to no icon. Failures are remembered, `not_ready` is retried later with a growing delay.
local I = {}
I.__index = I

I.CORE = "pokemon.core"
I.PER_TICK = 3        -- core calls per tick
I.RETRY_MS = 5000     -- first retry of "not_ready"; grows by this much per try
I.RETRY_MAX_MS = 30000
I.INFO_MS = 10000     -- re-check of info().features.icons while it is false
I.MAX_BAD = 5         -- consecutive failures without any success before icons are switched off

function I.new(fb)
  return setmetatable({ fb = fb, entries = {}, queue = {}, bad = 0, ok_once = false, disabled = false,
                        feature_ok = false, next_info = 0, errors = {},
                        now = 0, rev = nil, rev_done = false, next_rev = 0 }, I)
end

local function valid_rev(r)
  return type(r) == "string" and #r > 0 and #r <= 32 and not r:find("[^%w%-_.]")
end

--- info() of the core; remembers icon_rev on the first answer. Returns the info table or nil.
function I:info()
  local ok, info = pcall(self.fb.call, I.CORE, "info")
  if ok and type(info) == "table" then
    if not self.rev_done then
      self.rev_done = true
      if valid_rev(info.icon_rev) then self.rev = info.icon_rev end
    end
    return info
  end
  if not self.rev_done then self.next_rev = self.now + I.INFO_MS end
  return nil
end

local function norm(species, form)
  if math.type(species) ~= "integer" or species < 1 or species > 100000 then return nil end
  if math.type(form) ~= "integer" or form < 0 or form > 1000 then form = 0 end
  return species, form
end

function I.name(species, form, rev)
  return "icons/" .. (rev and (rev .. "/") or "") .. species .. "-" .. form .. ".png"
end

--- `cache:` src of the icon when it is in the cache, else nil (and the icon is queued once).
function I:src(species, form)
  if self.disabled then return nil end
  local sp, fm = norm(species, form)
  if not sp then return nil end
  if not self.rev_done and self.now >= self.next_rev then self:info() end
  local k = sp .. "-" .. fm
  local e = self.entries[k]
  if not e then
    local name = I.name(sp, fm, self.rev)
    local okc, have = pcall(self.fb.cache.exists, name)
    if okc and have then
      e = { st = "have", name = name }
    else
      e = { st = "queued", name = name, sp = sp, fm = fm, tries = 0 }
      self.queue[#self.queue + 1] = k
    end
    self.entries[k] = e
  end
  if e.st == "have" then return "cache:" .. e.name end
  return nil
end

function I:fail(e, why)
  e.st = "failed"
  self.bad = self.bad + 1
  if self.bad >= I.MAX_BAD and not self.ok_once then
    self.disabled = true
    self.fb.log.info("icons: pokemon-core provides none (" .. tostring(why) .. "), not asked again")
  end
end

--- Fetch a few queued icons. Returns true when at least one became available.
function I:pump(now)
  self.now = now
  if self.disabled then return false end
  for k, e in pairs(self.entries) do
    if e.st == "retry" and now >= e.at then e.st = "queued"; self.queue[#self.queue + 1] = k end
  end
  if #self.queue == 0 then return false end
  if not self.feature_ok then
    if now < self.next_info then return false end
    local info = self:info()
    if info and type(info.features) == "table" and info.features.icons ~= true then
      self.next_info = now + I.INFO_MS
      return false
    end
    self.feature_ok = true -- supported, or info() unknown: just try
  end
  local changed = false
  for _ = 1, I.PER_TICK do
    local k = table.remove(self.queue, 1)
    if not k then break end
    local e = self.entries[k]
    if e and e.st == "queued" then
      local ok, png, why = pcall(self.fb.call, I.CORE, "icon", e.sp, e.fm)
      if not ok then
        self:fail(e, "error")
      elseif type(png) == "string" and #png > 0 then
        local wok = pcall(self.fb.cache.write, e.name, png)
        if wok then
          e.st, changed, self.ok_once, self.bad = "have", true, true, 0
        else
          self:fail(e, "cache")
        end
      elseif why == "not_ready" then
        e.tries = e.tries + 1
        e.st, e.at = "retry", now + math.min(I.RETRY_MS * e.tries, I.RETRY_MAX_MS)
        break -- the core is busy: do not ask for the rest now
      else
        self:fail(e, why)
      end
    end
  end
  return changed
end

return I

end
__mod["app.maps"] = function(...)
-- Region map, two sources. (1) From the game picture: the player opens the map in the game on the 3DS
-- bottom screen and "Take map from screen" captures it with fb.video.capture (permission video.capture,
-- Uzume 0.11+ with the game picture API). (2) From the game files: pokemon-core `map_candidates()` lists
-- large images found in the player's own RomFS (nil, "not_ready" while it still scans), `map_image(id)` returns
-- one as PNG, `map_selected()` is the core's own pick; the player browses them and confirms one. The PNG stays
-- in the own cache of this player (never in the run state):
--   map/<game id>.png   the map in use (empty file = removed)
--   map/current.txt     game id of the last map (the run view in the shell has no game id)
--   map/cand-<n>.png    preview of file candidate n of the list (overwritten when the list changes)
--   map/coords.json     { map = game id, crop = { t, b, l, r }, routes = { [route key] = { x, y } },
--                         source = "files", file = candidate id (only for a map from the game files) };
--                       crop = percent of the captured screen cut off at top/bottom/left/right when the stored PNG was
--                       taken (the capture rect lies inside the bottom screen, so the PNG is already cropped);
--                       0 for a map from the game files
-- Route positions are image pixels of the stored map. Taking the map again with another crop, or switching the
-- source, RESCALES the recorded positions (screen fraction kept) instead of clearing them; without a known old
-- image nothing changes. The default crop is the full screen.
-- Route positions on the image are our own recorded facts (data.oras.COORDS[game id]) merged under the
-- recorded ones. Retaking or removing the map keeps the positions. Without fb.video (older app) the
-- Map tab says so; nothing else depends on it.
local util = require("model.util")
local oras = require("data.oras")

local M = {}
M.__index = M

M.COORDS_FILE, M.CURRENT = "map/coords.json", "map/current.txt"
M.NO_GAME = "game"
M.SIDES = { "t", "b", "l", "r" }
M.CORE = "pokemon.core"
M.SCAN_MS, M.RETRY_MS, M.MAX_CANDIDATES = 3000, 2000, 40
M.MAX_CROP = 45 -- percent per side; opposite sides together stay below 90

--- Clamp a crop table { t, b, l, r } (percent) to whole numbers 0..MAX_CROP with opposite sides <= 90 together.
function M.clean_crop(c)
  local out = {}
  for _, k in ipairs(M.SIDES) do
    local v = type(c) == "table" and tonumber(c[k]) or 0
    out[k] = math.max(0, math.min(M.MAX_CROP, math.floor((v or 0) + 0.5)))
  end
  return out
end

--- Width and height from a PNG header, or nil.
function M.png_size(s)
  if type(s) ~= "string" or #s < 24 or s:sub(1, 8) ~= "\137PNG\r\n\26\n" or s:sub(13, 16) ~= "IHDR" then return nil end
  local w, h = string.unpack(">I4I4", s, 17)
  if w < 1 or h < 1 or w > 16384 or h > 16384 then return nil end
  return w, h
end

local function safe(id) return (tostring(id):gsub("[^%w_%-]", "_"):sub(1, 60)) end

--- `live` = false in the shell run view (no game: nothing to capture). Game id = fb.game.code.
function M.new(fb, live)
  local code = type(fb.game) == "table" and fb.game.code or nil
  local self = setmetatable({ fb = fb, state = "none", coords = {}, live = live ~= false,
                              api = type(fb.video) == "table" and type(fb.video.capture) == "function" }, M)
  self.game = (type(code) == "string" and code ~= "") and code or nil
  self:restore()
  self.edit = self.crop and M.clean_crop(self.crop) or M.clean_crop({})
  -- map from the game files: only in a live run and when fb.call exists; the core decides on the first call
  self.files = { state = (self.live and type(fb.call) == "function") and "idle" or "unsupported", list = {}, idx = 1,
                 previews = {}, failed = {}, retry = {}, next_at = 0 }
  return self
end

function M:read(name)
  local ok, v = pcall(self.fb.cache.read, name)
  return ok and v or nil
end

function M:write(name, data)
  return (pcall(self.fb.cache.write, name, data))
end

function M:file() return "map/" .. safe(self.id or M.NO_GAME) .. ".png" end

--- Restore the image and the recorded positions from the cache.
function M:restore()
  self.id = self.game
  if not self.id then
    local cur = self:read(M.CURRENT)
    self.id = (type(cur) == "string" and cur:match("^%s*(.-)%s*$") ~= "") and cur:match("^%s*(.-)%s*$") or nil
  end
  local png = self.id and self:read(self:file()) or nil
  local w, h = M.png_size(png)
  if w then self.w, self.h, self.state = w, h, "ready" end
  self:load_coords()
end

function M:load_coords()
  self.coords, self.crop, self.source, self.file_id = {}, nil, nil, nil
  local s = self:read(M.COORDS_FILE)
  if type(s) ~= "string" or not self.id then return end
  local id = s:match('"map"%s*:%s*"(.-)"')
  if id ~= self.id then return end
  if s:match('"source"%s*:%s*"files"') then
    self.source, self.file_id = "files", s:match('"file"%s*:%s*"(.-)"')
    if self.file_id == "" then self.file_id = nil end
  end
  local cs = s:match('"crop"%s*:%s*(%b{})')
  if cs then
    local c = {}
    for _, k in ipairs(M.SIDES) do c[k] = tonumber(cs:match('"' .. k .. '"%s*:%s*(%d+)')) end
    self.crop = M.clean_crop(c)
  end
  local routes = s:match('"routes"%s*:%s*(%b{})') or ""
  for key, x, y in routes:gmatch('"([^"]+)"%s*:%s*{%s*"x"%s*:%s*(-?%d+)%s*,%s*"y"%s*:%s*(-?%d+)%s*}') do
    if oras.is_route(key) then self.coords[key] = { x = tonumber(x), y = tonumber(y) } end
  end
end

function M:save_coords()
  local routes = {}
  for key, c in pairs(self.coords) do routes[key] = { x = c.x, y = c.y } end
  local files = self.source == "files" and self.file_id
  self:write(M.COORDS_FILE, util.encode({ map = self.id, crop = self.crop, routes = routes,
    source = files and "files" or nil, file = files or nil }))
end

--- Route positions: data.oras.COORDS[map id] with the recorded ones on top.
function M:merged()
  local out = {}
  for key, c in pairs(self.id and oras.COORDS[self.id] or {}) do out[key] = c end
  for key, c in pairs(self.coords) do
    local base = out[key]
    out[key] = { x = c.x, y = c.y, area = base and base.area or nil }
  end
  return out
end

--- Record the position of a route (image pixels, clamped to the image).
function M:set_coord(route, x, y)
  if self.state ~= "ready" or not oras.is_route(route) then return false end
  x = math.max(0, math.min(self.w, math.floor(x + 0.5)))
  y = math.max(0, math.min(self.h, math.floor(y + 0.5)))
  self.coords[route] = { x = x, y = y }
  self:save_coords()
  return true
end

--- One Lua table line with all positions (data.oras.COORDS entry), written to the log. nil without positions.
function M:export_line()
  local all = self:merged()
  local keys = {}
  for key in pairs(all) do keys[#keys + 1] = key end
  if #keys == 0 or not self.id then return nil end
  table.sort(keys, function(a, b) return oras.compare(a, b, self.order) end)
  local parts = {}
  for _, key in ipairs(keys) do
    local c = all[key]
    parts[#parts + 1] = string.format("[%q] = { x = %d, y = %d%s }", key, c.x, c.y,
      c.area and string.format(", area = %q", c.area) or "")
  end
  local line = string.format("COORDS[%q] = { %s }", self.id, table.concat(parts, ", "))
  self.fb.log.info("soullink positions: " .. line)
  return line
end

--- Screen to capture: the entry "bottom", else "main" of fb.video.screens() ({ name, x, y, w, h }), else nil.
function M:target()
  local ok, list = pcall(self.fb.video.screens)
  if not ok or type(list) ~= "table" then return nil end
  local by = {}
  for _, sc in ipairs(list) do
    if type(sc) == "table" and math.type(sc.x) == "integer" and math.type(sc.y) == "integer"
        and math.type(sc.w) == "integer" and math.type(sc.h) == "integer" and sc.w > 0 and sc.h > 0 then
      by[sc.name] = sc
    end
  end
  return by.bottom or by.main or nil
end

--- Capture rectangle inside screen `sc` for `crop` (percent): { x, y, w, h } in the screen coordinates.
function M.crop_rect(sc, crop)
  local c = M.clean_crop(crop)
  local l, r = sc.w * c.l // 100, sc.w * c.r // 100
  local tp, bt = sc.h * c.t // 100, sc.h * c.b // 100
  return { x = sc.x + l, y = sc.y + tp, w = math.max(1, sc.w - l - r), h = math.max(1, sc.h - tp - bt) }
end

--- Change one side of the crop being edited by `delta` percent ("t", "b", "l", "r"), within the limits.
function M:adjust(side, delta)
  if not (self.edit and self.edit[side] ~= nil) or math.type(delta) ~= "integer" then return false end
  local opp = ({ t = "b", b = "t", l = "r", r = "l" })[side]
  local v = math.max(0, math.min(M.MAX_CROP, self.edit[side] + delta))
  v = math.min(v, 90 - self.edit[opp])
  self.edit[side] = math.max(0, v)
  return true
end

--- Set the crop being edited: "none" (full screen) or "applied" (of the stored map).
function M:preset(name)
  if name == "none" then self.edit = M.clean_crop({})
  elseif name == "applied" then self.edit = self.crop and M.clean_crop(self.crop) or M.clean_crop({})
  else return false end
  return true
end

--- Start a capture of the game picture. Returns true when a request is pending.
function M:capture()
  self.error = nil
  if not self.api then return false end
  if not self.live or not self.game then self.error = "unsupported"; return false end
  if self.pending then self.error = "busy"; return false end
  local target = self:target()
  if not target then self.error = "no_frame"; return false end
  local rect = M.crop_rect(target, self.edit)
  local ok, id = pcall(self.fb.video.capture, rect)
  if not ok then
    self.fb.log.warn("soullink map capture: " .. tostring(id))
    self.error = "failed"
    return false
  end
  self.pending, self.pending_crop = id, M.clean_crop(self.edit)
  return true
end

--- Host event video.captured { id, ok, png, w, h, error }. Returns true when the view changed.
function M:on_captured(e)
  if type(e) ~= "table" or not self.pending or e.id ~= self.pending then return false end
  self.pending = nil
  if e.ok ~= true then
    self.error = type(e.error) == "string" and e.error or "failed"
    return true
  end
  local w, h = M.png_size(e.png)
  if not w then self.error = "failed"; return true end
  self.id = self.game
  local old_w, old_h, old_crop = self.w, self.h, self.crop or M.clean_crop({})
  if not (self:write(self:file(), e.png) and self:write(M.CURRENT, self.id)) then
    self.error = "failed"
    return true
  end
  self.w, self.h, self.state, self.error = w, h, "ready", nil
  self:load_coords()
  self:rescale(old_w, old_h, old_crop, self.pending_crop, w, h)
  self.crop = self.pending_crop
  self.source, self.file_id = "screen", nil
  self:save_coords()
  self.edit = M.clean_crop(self.crop)
  return true
end

-- ---------------------------------------------------------------- map from the game files

local function png_ok(png) return type(png) == "string" and M.png_size(png) ~= nil end

--- Ask the core for the candidates (until it is done scanning) and fetch the preview of the shown one.
--- Called from every tick; returns true when the view changed. A core without the functions (or without
--- fb.call) turns the option off for good.
function M:files_step(now)
  local f = self.files
  if f.state == "unsupported" then return false end
  local changed = false
  if f.state ~= "done" then
    if now < f.next_at then return false end
    f.next_at = now + M.SCAN_MS
    local ok, list, why = pcall(self.fb.call, M.CORE, "map_candidates")
    if not ok or why == "unsupported" then f.state = "unsupported"; return true end
    if type(list) ~= "table" then
      if f.state ~= "scanning" then f.state, changed = "scanning", true end
      return changed
    end
    f.list = {}
    for _, c in ipairs(list) do
      if #f.list >= M.MAX_CANDIDATES then break end
      if type(c) == "table" and type(c.id) == "string" and c.id ~= "" then
        f.list[#f.list + 1] = { id = c.id, w = math.tointeger(c.w), h = math.tointeger(c.h) }
      end
    end
    f.state, f.idx, f.previews, f.failed, f.retry = "done", 1, {}, {}, {}
    local oks, sel = pcall(self.fb.call, M.CORE, "map_selected")
    f.selected = (oks and type(sel) == "string" and sel ~= "") and sel or nil
    changed = true
  end
  local c = f.list[f.idx]
  if c and not f.previews[c.id] and not f.failed[c.id] and now >= (f.retry[c.id] or 0) then
    local ok, png, why = pcall(self.fb.call, M.CORE, "map_image", c.id)
    local name = "map/cand-" .. f.idx .. ".png"
    if ok and png_ok(png) and self:write(name, png) then
      f.previews[c.id], changed = name, true
    elseif ok and why == "not_ready" then
      f.retry[c.id] = now + M.RETRY_MS
    else
      f.failed[c.id], changed = true, true
    end
  end
  return changed
end

--- Show the previous (-1) or next (1) candidate, wrapping around.
function M:files_nav(delta, now)
  local f = self.files
  local n = #f.list
  if n == 0 or (delta ~= 1 and delta ~= -1) then return false end
  f.idx = (f.idx - 1 + delta) % n + 1
  f.error = nil
  self:files_step(now or 0)
  return true
end

--- Use the shown candidate as the map: the positions move to the new image like a crop change. Returns true on success.
function M:files_use()
  local f = self.files
  local c = f.list[f.idx]
  f.error = nil
  if not c then return false end
  if not self.live or not self.game then f.error = "unsupported"; return false end
  local png = f.previews[c.id] and self:read(f.previews[c.id]) or nil
  if not png_ok(png) then
    local ok, p = pcall(self.fb.call, M.CORE, "map_image", c.id)
    png = ok and p or nil
  end
  local w, h = M.png_size(png)
  if not w then f.error = "failed"; return false end
  self.id = self.game
  local old_w, old_h, old_crop = self.w, self.h, self.crop or M.clean_crop({})
  if not (self:write(self:file(), png) and self:write(M.CURRENT, self.id)) then f.error = "failed"; return false end
  self.w, self.h, self.state, self.error = w, h, "ready", nil
  self:load_coords()
  self:rescale(old_w, old_h, old_crop, M.clean_crop({}), w, h)
  self.crop, self.source, self.file_id = M.clean_crop({}), "files", c.id
  self:save_coords()
  self.edit = M.clean_crop(self.crop)
  return true
end

--- Positions recorded on an image of old_w x old_h cropped by `old` (percent) move to the new image
--- (new_w x new_h, crop `new`): the point on the screen stays the same. Needs an old image; otherwise nothing changes.
function M:rescale(old_w, old_h, old, new, new_w, new_h)
  if not old_w or not old_h or next(self.coords) == nil then return end
  local function frac(c) return c.l / 100, c.t / 100, 1 - (c.l + c.r) / 100, 1 - (c.t + c.b) / 100 end
  local ol, ot, ow, oh = frac(old)
  local nl, nt, nw, nh = frac(new)
  for _, c in pairs(self.coords) do
    local fx, fy = ol + c.x / old_w * ow, ot + c.y / old_h * oh
    c.x = math.max(0, math.min(new_w, math.floor((fx - nl) / nw * new_w + 0.5)))
    c.y = math.max(0, math.min(new_h, math.floor((fy - nt) / nh * new_h + 0.5)))
  end
end

--- Remove the map image; the recorded positions stay.
function M:remove()
  if self.state == "ready" then self:write(self:file(), "") end
  self.w, self.h, self.state, self.error = nil, nil, "none", nil
  if self.source == "files" then
    self.source, self.file_id = nil, nil
    self:save_coords()
  end
end

--- The candidates for the UI: { avail, state = idle|scanning|done, n, idx, cand = { id, w, h, src?, failed?,
--- suggested?, current? }, error? }.
function M:files_view()
  local f = self.files
  local out = { avail = f.state ~= "unsupported", state = f.state, n = #f.list, idx = f.idx, error = f.error }
  local c = f.list[f.idx]
  if c then
    local pv = f.previews[c.id]
    out.cand = { id = c.id, w = c.w, h = c.h, src = pv and ("cache:" .. pv) or nil, failed = f.failed[c.id] or nil,
      suggested = (f.selected ~= nil and f.selected == c.id) or nil,
      current = (self.state == "ready" and self.source == "files" and self.file_id == c.id) or nil }
  end
  return out
end

--- What the UI needs: { state = none|ready, api, live, pending, error?, src?, w?, h?, id?, source?, files, coords }.
function M:view()
  return { state = self.state, id = self.id, w = self.w, h = self.h, api = self.api, live = self.live,
           pending = self.pending ~= nil, error = self.error, crop = self.crop, edit = self.edit,
           source = self.source, files = self:files_view(),
           src = self.state == "ready" and ("cache:" .. self:file()) or nil, coords = self:merged() }
end

return M

end
__mod["app.sync"] = function(...)
-- Keeps fb.ui slots up to date: nothing when the tree is unchanged, fb.ui.patch when only props of
-- blocks with an id changed (same structure), fb.ui.set otherwise.
local util = require("model.util")

local S = {}
S.__index = S

S.MAX_PATCHES = 12

function S.new(fb) return setmetatable({ fb = fb, last = {}, sets = 0, patches = 0 }, S) end

local function diff(old, new, patches)
  if old.type ~= new.type or old.id ~= new.id then return false end
  local oc, nc = old.children or {}, new.children or {}
  if #oc ~= #nc then return false end
  local changed
  for k, v in pairs(new) do
    if k ~= "type" and k ~= "id" and k ~= "children" and util.encode(v) ~= util.encode(old[k]) then
      changed = changed or {}
      changed[k] = v
    end
  end
  for k in pairs(old) do
    if k ~= "type" and k ~= "id" and k ~= "children" and new[k] == nil then return false end -- patch cannot remove
  end
  if changed then
    if not new.id then return false end
    patches[#patches + 1] = { id = new.id, props = changed }
  end
  for i = 1, #nc do
    if not diff(oc[i], nc[i], patches) then return false end
  end
  return true
end

--- Show `tree` in `slot`. Returns "same", "patch" or "set".
function S:push(slot, tree)
  local old = self.last[slot]
  if old then
    if util.encode(old) == util.encode(tree) then return "same" end
    local patches = {}
    if diff(old, tree, patches) and #patches <= S.MAX_PATCHES then
      for _, p in ipairs(patches) do self.fb.ui.patch(slot, p.id, p.props) end
      self.last[slot] = util.copy(tree)
      self.patches = self.patches + #patches
      return "patch"
    end
  end
  self.fb.ui.set(slot, tree)
  self.last[slot] = util.copy(tree)
  self.sets = self.sets + 1
  return "set"
end

function S:clear(slot)
  if self.last[slot] then
    self.fb.ui.clear(slot)
    self.last[slot] = nil
  end
end

return S

end
__mod["data.oras"] = function(...)
-- Route keys and small data tables for Omega Ruby / Alpha Sapphire.
-- Keyed by internal route keys only; names (routes, species, places) are never shipped here.
local util = require("model.util")

local M = {}

M.STARTER = "starter"
-- Legacy keys "route-101" .. "route-134" of runs started before 0.4.0: still read (label "Route N"),
-- never offered again. Places come from the game now: "loc:<location name id>" (see areas()).
M.FIRST_ROUTE = 101
M.LAST_ROUTE = 134

--- zone id (pokemon-core `location().zone`) -> route key (string) or false (known zone that is not a
--- route, e.g. a town). EMPTY on purpose: the table is unknown until recorded with the real game.
--- Meanwhile zones are learned at runtime: the answer of a player is kept in the own run state
--- (`zones`) and merged across all players (model.view.merge_zones).
M.ZONES = {}
M.ZONE_TO_ROUTE = M.ZONES -- old name
--- Route positions on the region map image, keyed by the game id (`fb.game.code`):
--- COORDS[game id][route key] = { x, y, area? } in image
--- pixels. Our own recorded facts, EMPTY for now: positions are recorded in the Map tab
--- ("Place routes") and exported with "Export positions".
M.COORDS = {}

--- Level cap hint by number of badges owned: LEVEL_CAPS[badges] = cap of the next gym.
--- VERIFY LOCALLY against the real game before relying on it; hints only, never blocking.
M.LEVEL_CAPS = { [0] = 15, 19, 24, 29, 31, 33, 42, 43 }

--- Number of gym badges of the game (the level cap table has one entry per badge).
M.BADGES = 8

--- Level cap hint for `badges` badges, or nil when unknown (for example all eight badges).
function M.level_cap(badges)
  if math.type(badges) ~= "integer" then return nil end
  return M.LEVEL_CAPS[badges]
end

--- Legacy route number of a key "route-NNN", or nil.
function M.route_number(key)
  local n = type(key) == "string" and key:match("^route%-(%d+)$")
  n = n and tonumber(n)
  if n and n >= M.FIRST_ROUTE and n <= M.LAST_ROUTE then return n end
  return nil
end

--- Key of an encounter area ("loc:<location name id>"), or nil for a non-integer id.
function M.area_key(id)
  if math.type(id) == "float" then id = math.tointeger(id) end
  if math.type(id) ~= "integer" or id < 0 or id > 999999 then return nil end
  return "loc:" .. id
end

--- Location name id of an area key, or nil.
function M.area_id(key)
  local n = type(key) == "string" and key:match("^loc:(%d+)$")
  n = n and #n <= 6 and tonumber(n)
  return n and math.tointeger(n) or nil
end

--- Area key or legacy route key (a place that can carry a map position).
function M.is_route(key) return M.area_id(key) ~= nil or M.route_number(key) ~= nil end

--- True for "starter", an area key, a legacy route key or a free "place:<text>" key.
function M.is_key(key)
  if type(key) ~= "string" then return false end
  if key == M.STARTER or M.is_route(key) then return true end
  local text = key:match("^place:(.+)$")
  return text ~= nil and util.clean_text(text, 48) == text
end

--- Free place key for text typed by the user ("place:<text>", text kept as typed apart from
--- whitespace cleanup, at most 48 characters). nil for empty text.
function M.custom_key(text)
  local t = util.clean_text(text, 48)
  return t and ("place:" .. t) or nil
end

--- Sort index. `order` (optional) maps an area key to its position in the game's order
--- (view.order). Starter first, legacy routes in numeric order, areas in game order (unknown
--- areas by id after the known ones), free places last.
function M.order_index(key, order)
  if key == M.STARTER then return 0 end
  local n = M.route_number(key)
  if n then return n - M.FIRST_ROUTE + 1 end
  local id = M.area_id(key)
  if id then return 100 + ((order and order[key]) or (50000 + id)) end
  return 1000000
end

--- Comparison function for route keys (optional game order map, see order_index).
function M.compare(a, b, order)
  local ia, ib = M.order_index(a, order), M.order_index(b, order)
  if ia ~= ib then return ia < ib end
  return tostring(a) < tostring(b)
end

--- Display text. `tr` is fb.i18n.t (key, vars); `names` (optional) is { loc = { ["<id>"] = name } }
--- from the game (view.names). Free places keep the text as typed; an area without a known
--- name shows "Area <id>".
function M.label(key, tr, names)
  if key == M.STARTER then return tr("route_starter") end
  local n = M.route_number(key)
  if n then return tr("route", { n = n }) end
  local id = M.area_id(key)
  if id then
    local nm = names and names.loc and names.loc[tostring(id)]
    if type(nm) == "string" and nm ~= "" then return nm end
    return tr("area", { n = id })
  end
  local text = type(key) == "string" and key:match("^place:(.+)$")
  return text or tostring(key)
end

return M

end
__mod["main"] = function(...)
-- Entry module of the SoulLink & Nuzlocke plugin: wires the run model to the app.
local controller = require("app.controller")

fb.log.info(fb.i18n.t("loaded", { version = (fb.plugin and fb.plugin.version) or "?" }))
local app = controller.new(fb)
app:start()

end
__mod["model.corrections"] = function(...)
-- Manual corrections: run events of type "soullink.correction" with source "manual".
-- Corrections are applied by model/view.lua in seq order on top of the own states; they never
-- rewrite the own state. Builders return a spec { type, source = "manual", payload }; the caller
-- adds `text` and posts it with fb.run.event.
--
-- payload.user is the player the correction is about (the author is the event's user_id).
local util = require("model.util")
local oras = require("data.oras")

local C = {}

C.TYPE = "soullink.correction"
C.MAX_PAYLOAD = 4096
C.KINDS = {
  "doesnt_count", "undo_death", "set_group", "add", "mark_missed", "mark_dead", "set_gift", "revert",
}
C.REASONS = { dupe = true, shiny = true, wrong = true }
C.ADD_STATES = { team = true, box = true, dead = true }

local function spec(payload)
  return { type = C.TYPE, source = "manual", payload = payload }
end

--- "This encounter/catch doesn't count". `route` and/or `mon`; `reason` = dupe|shiny|wrong.
--- Without `mon`: reopens an encounter/missed route (or excludes the route's counted mon).
--- With `mon`: that mon stops counting and its route reopens.
function C.doesnt_count(a)
  return spec({ kind = "doesnt_count", user = a.user, route = a.route, mon = a.mon, reason = a.reason })
end

--- Undo the death of a whole link group. `group` = route key; `undone` = list of
--- { owner = user id, mon = mon id, deaths = death count that is undone } (use C.undo_entries).
function C.undo_death(a)
  return spec({ kind = "undo_death", group = a.group, reason = a.reason, undone = a.undone })
end

--- Build the `undone` list from a view group (member list as produced by view.view).
function C.undo_entries(group)
  local out = {}
  for _, m in ipairs(group.members or {}) do
    out[#out + 1] = { owner = m.owner, mon = m.id, deaths = m.deaths }
  end
  return out
end

--- Move a mon to the link group of `group` (route key) or to no group ("none").
function C.set_group(a)
  return spec({ kind = "set_group", user = a.user, mon = a.mon, group = a.group })
end

--- Hand-added mon. state = team|box|dead. Replaces "missed"/open on the route.
function C.add(a)
  return spec({ kind = "add", user = a.user, route = a.route, species = a.species, form = a.form,
                nickname = a.nickname, level = a.level, state = a.state or "box", shiny = a.shiny })
end

function C.mark_missed(a) return spec({ kind = "mark_missed", user = a.user, route = a.route }) end

function C.mark_dead(a) return spec({ kind = "mark_dead", user = a.user, mon = a.mon, reason = a.reason }) end

--- Mark (or unmark with gift = false) a mon as a gift: no link group.
function C.set_gift(a)
  local g = a.gift
  if g == nil then g = true end
  return spec({ kind = "set_gift", user = a.user, mon = a.mon, gift = g })
end

--- Revert the correction event with seq `target`.
function C.revert(a) return spec({ kind = "revert", target = a.target, reason = a.reason }) end

--- Effective corrections of a list of run events: valid ones only, in seq order, without the reverted
--- ones (a reverted revert cancels nothing). Returns the list `{ seq, author, p }` and the seqs of
--- invalid correction events.
function C.effective(events)
  local list = {}
  for _, ev in ipairs(events or {}) do
    if type(ev) == "table" and math.type(ev.seq) == "integer" and ev.type == C.TYPE then list[#list + 1] = ev end
  end
  table.sort(list, function(a, b) return a.seq < b.seq end)
  local corr, invalid = {}, {}
  for _, ev in ipairs(list) do
    local p = type(ev.payload) == "table" and ev.payload or {}
    if C.validate(p) then corr[#corr + 1] = { seq = ev.seq, author = ev.user_id, p = p }
    else invalid[#invalid + 1] = ev.seq end
  end
  local reverted = {}
  for i = #corr, 1, -1 do
    local c = corr[i]
    if c.p.kind == "revert" and not reverted[c.seq] and c.p.target < c.seq then reverted[c.p.target] = true end
  end
  local out = {}
  for _, c in ipairs(corr) do
    if c.p.kind ~= "revert" and not reverted[c.seq] then out[#out + 1] = c end
  end
  return out, invalid
end

--- Route overrides of one player: what the effective corrections (`C.effective`) do to the routes of
--- the player's own state `st`. Used by the view and by detection, so both agree. Returns
--- `overrides`, `excluded`:
---   overrides[route] = { kind = "reopen"|"missed"|"taken", seq = correction seq, mon? (taken: "add-<seq>") }
---   excluded[mon id] = the correction `{ seq, p }` that excluded it   (mons that "doesn't count" removed)
--- A route entry of the state with `rs` (reset seq) >= override seq was created after the correction
--- and is valid; older entries are shadowed by the override. Corrections apply to what happened
--- before them, never to later facts. "reopen": the route is open again (doesn't count); "missed":
--- marked missed; "taken": a hand-added mon holds the route. A route whose counted mon still counts
--- is not changed by mark_missed / add (the mon holds the slot).
function C.route_overrides(effective, user, st)
  local routes = type(st) == "table" and type(st.routes) == "table" and st.routes or {}
  local ov, excluded, taken = {}, {}, {}
  -- the mon that counts on `route` at the time of the correction `at` (entries stamped `rs` >= at were
  -- created after it and do not exist yet)
  local function holder(route, at)
    local o, e = ov[route], routes[route]
    if e and (e.rs or 0) >= at then e = nil end
    if o and (not e or (e.rs or 0) < o.seq) then
      return (o.kind == "taken" and not excluded[o.mon]) and o.mon or nil
    end
    if e and e.status == "caught" and e.mon and not excluded[e.mon] then return e.mon end
    return nil
  end
  for _, c in ipairs(effective or {}) do
    local p = c.p
    if p.user == user then
      if p.kind == "doesnt_count" then
        if p.mon then
          local route = taken[p.mon]
          if not route then
            for _, key in ipairs(util.keys(routes)) do
              if holder(key, c.seq) == p.mon then route = key; break end
            end
          end
          local holds = route and holder(route, c.seq) == p.mon
          excluded[p.mon] = c
          if holds then ov[route] = { kind = "reopen", seq = c.seq } end
        else
          local h = holder(p.route, c.seq)
          if h then excluded[h] = c end
          ov[p.route] = { kind = "reopen", seq = c.seq }
        end
      elseif p.kind == "mark_missed" then
        if not holder(p.route, c.seq) then ov[p.route] = { kind = "missed", seq = c.seq } end
      elseif p.kind == "add" then
        if not holder(p.route, c.seq) then
          local id = "add-" .. c.seq
          ov[p.route] = { kind = "taken", seq = c.seq, mon = id }
          taken[id] = p.route
        end
      end
    end
  end
  return ov, excluded
end

local function is_str(v, max) return type(v) == "string" and #v > 0 and #v <= (max or 64) end
local function is_route_ref(v) return type(v) == "string" and oras.is_key(v) end
local function opt(v, f) return v == nil or f(v) end
local function is_int(v) return math.type(v) == "integer" end

local checks = {
  doesnt_count = function(p)
    return is_str(p.user) and (p.route ~= nil or p.mon ~= nil) and opt(p.route, is_route_ref)
      and opt(p.mon, is_str) and opt(p.reason, function(r) return C.REASONS[r] == true end)
  end,
  undo_death = function(p)
    if not is_route_ref(p.group) or type(p.undone) ~= "table" or #p.undone == 0 then return false end
    for _, e in ipairs(p.undone) do
      if type(e) ~= "table" or not is_str(e.owner) or not is_str(e.mon) or not is_int(e.deaths) or e.deaths < 0 then
        return false
      end
    end
    return true
  end,
  set_group = function(p)
    return is_str(p.user) and is_str(p.mon) and (p.group == "none" or is_route_ref(p.group))
  end,
  add = function(p)
    return is_str(p.user) and is_route_ref(p.route) and is_int(p.species) and p.species > 0
      and C.ADD_STATES[p.state] == true and opt(p.level, is_int)
      and opt(p.nickname, function(n) return is_str(n, 48) end) and opt(p.form, is_int)
  end,
  mark_missed = function(p) return is_str(p.user) and is_route_ref(p.route) end,
  mark_dead = function(p) return is_str(p.user) and is_str(p.mon) end,
  set_gift = function(p) return is_str(p.user) and is_str(p.mon) and type(p.gift) == "boolean" end,
  revert = function(p) return is_int(p.target) and p.target > 0 end,
}

--- Validate a correction payload. Returns true, or false plus a reason string.
function C.validate(payload)
  if type(payload) ~= "table" then return false, "payload is not a table" end
  local check = checks[payload.kind]
  if not check then return false, "unknown kind" end
  if payload.reason ~= nil and type(payload.reason) ~= "string" then return false, "bad reason" end
  if type(payload.reason) == "string" and #payload.reason > 280 then return false, "reason too long" end
  if not check(payload) then return false, "invalid fields for " .. payload.kind end
  if util.json_size(payload) > C.MAX_PAYLOAD then return false, "payload larger than 4 KiB" end
  return true
end

--- Validate a spec returned by a builder (type, source and payload).
function C.validate_spec(s)
  if type(s) ~= "table" or s.type ~= C.TYPE or s.source ~= "manual" then return false, "not a correction spec" end
  return C.validate(s.payload)
end

return C

end
__mod["model.detect"] = function(...)
-- Detection: diff(previous own state, core snapshot, cfg) -> new own state + facts.
-- Pure; never touches fb. Everything the core cannot report (place, battle, hp, encounters)
-- degrades to "unknown": nothing is invented, the UI/user supplies it through manual input.
local util = require("model.util")
local rules = require("model.rules")
local state = require("model.state")
local oras = require("data.oras")

local D = {}

-- Snapshot (what the caller passes; model/snapshot.lua builds it from pokemon.core):
--   team     list of generic records, or nil = unknown
--   boxes    list of boxes (each a list of records) or a flat list of records, or nil = unknown
--   location { zone = number?, location = number? (location name id), name = string? }   or nil
--   battle   { active = bool, wild = bool, horde = bool?, foes = {records}, own = {records}? }  or nil
--   encounters pokemon.core v0.3: list (oldest first) of { seq, species, form?, shiny?, horde?, location? };
--              entries with seq > state.enc_seq are new. Without seq (older shape): all entries are new.
--   badges   number | { count = n } | list of booleans
-- Facts (kind): place, catch, evolve, death, moved, encounter, missed. See docs/architecture.md.

local function default_family(species) return species end

local function collect(snap)
  local list, map = {}, {}
  local team_known = type(snap.team) == "table"
  local boxes_known = type(snap.boxes) == "table"
  local function add(rec, where)
    if type(rec) ~= "table" or type(rec.species) ~= "number" then return end
    local pid = util.hex8(rec.personality)
    if not pid or map[pid] then return end
    local c = { pid = pid, rec = rec, where = where }
    map[pid] = c
    list[#list + 1] = c
  end
  if team_known then for _, rec in ipairs(snap.team) do add(rec, "team") end end
  if boxes_known then
    for _, box in ipairs(snap.boxes) do
      if type(box) == "table" and box.personality ~= nil then
        add(box, "box")
      elseif type(box) == "table" then
        for _, rec in ipairs(box) do add(rec, "box") end
      end
    end
  end
  return list, map, team_known, boxes_known
end

local function badge_count(b)
  if math.type(b) == "integer" then return b end
  if type(b) ~= "table" then return nil end
  if math.type(b.count) == "integer" then return b.count end
  local n = 0
  for _, v in ipairs(b) do if v == true then n = n + 1 end end
  return n
end

local function battle_info(snap)
  local b = snap.battle
  if type(b) ~= "table" or type(b.active) ~= "boolean" then return { known = false } end
  -- b.own (hp of the own battlers) is deliberately not used: it can be stale while a battle ends
  -- and caused premature deaths; a death needs the party record itself (see the death rule in diff).
  return { known = true, active = b.active, wild = b.wild == true, horde = b.horde == true,
           foes = type(b.foes) == "table" and b.foes or (type(b.foe) == "table" and { b.foe } or {}) }
end

-- Is a line (family) already owned by a tracked mon that counts for the dupes clause?
local function owns_line(st, species, family, opts)
  if species == nil then return false end
  local fam = family(species)
  local excluded = opts and opts.excluded or {}
  for pid, m in pairs(st.mons) do
    if not excluded[pid] and m.why ~= "dupe" and m.why ~= "extra" and m.where ~= "gone" and family(m.species) == fam then
      return true
    end
  end
  return false
end

local function zone_id(z)
  if math.type(z) == "float" and z == math.floor(z) then z = math.tointeger(z) end
  if math.type(z) == "integer" then return z end
  return nil
end

-- Display name of a species: the record's own text, else the name already stored in the state, else
-- the resolver; remembered in the state.
local function note_species(st, opts, species, hint)
  if math.type(species) ~= "integer" then return hint end
  local name = (type(hint) == "string" and hint ~= "") and hint or nil
  if not name then
    local known = st.names and st.names.sp and st.names.sp[tostring(species)]
    if known then return known end
    if opts.names and opts.names.species then name = opts.names.species(species) end
  end
  if name then state.note_name(st, "sp", species, name) end
  return name
end

-- Identity of a place for change detection: the route key, else the location id, else the name.
local function place_identity(p)
  if p.key then return p.key end
  if p.loc ~= nil then return "loc:" .. p.loc end
  return p.name
end

--- Place from the reported location. With a location name id (pokemon-core v0.3) and the encounter
--- areas, the place is the area `loc:<id>`; a location without encounter slots (town) has no key
--- ("no encounters here"). Without a location id the zone table decides (fallback; the UI asks for
--- unmapped zones). A manual place wins for as long as its anchor (location, else zone) stays the
--- same; when it changes, detection decides again.
local function update_place(st, loc, facts, opts)
  if type(loc) ~= "table" then return end
  local zone, lid = zone_id(loc.zone), zone_id(loc.location)
  local areas = opts.areas
  local by_area = lid ~= nil and areas ~= nil
  if lid ~= nil and areas == nil and not opts.areas_unsupported then return end -- areas still loading
  if not by_area then lid = nil end
  if not by_area and not zone then return end
  local old = st.place or { manual = false }
  if old.manual then
    local same
    if old.loc ~= nil then same = lid ~= nil and old.loc == lid
    else same = old.zone == nil or old.zone == zone end
    if same then
      old.zone = zone or old.zone
      if lid ~= nil then old.loc = lid end
      st.place = old
      return
    end
  end
  local new
  if by_area then
    local key = areas.set[lid] and oras.area_key(lid) or nil
    local name = (areas.names and areas.names[lid]) or loc.name or st.names.loc[tostring(lid)]
    new = { key = key, name = name, zone = zone, loc = lid, manual = false }
    if name then state.note_name(st, "loc", lid, name) end
  else
    local mapped = (opts.zones or oras.ZONES)[zone]
    if mapped ~= nil then
      new = { key = mapped or nil, name = loc.name, zone = zone, manual = false }
    else
      new = { name = loc.name, zone = zone, manual = false }
    end
    -- a zone nobody mapped and nobody named is stored (the UI asks which place this is) but never logged
  end
  -- a location without key and name (name text still loading) is transient too
  if by_area and new.key == nil and new.name == nil then return end
  local same = place_identity(new) == place_identity(old)
  if same and new.name == nil then new.name = old.name end
  if new.key ~= old.key or new.name ~= old.name or new.zone ~= old.zone or new.loc ~= old.loc or old.manual then
    st.place = new
    if not same and (new.key or new.name) then
      facts[#facts + 1] = { kind = "place", key = new.key, name = new.name, zone = new.zone, loc = new.loc,
                            manual = false, previous = old.key }
    end
  end
end

--- Set the place by hand. `input` is a route key ("route-104", "starter", "place:<text>") or free
--- text typed by the user (becomes "place:<text>"); nil/"" clears the place. `name` is optional
--- display text, `zone` / `loc` the zone and location id the player is in right now (nil when the
--- core reports none): the manual place wins until that anchor changes. Returns the new state and
--- a place fact (nil when nothing changed).
function D.set_place(prev, input, name, zone, loc)
  local st = state.ensure(util.copy(prev))
  local old = st.place or { manual = false }
  local key
  if input ~= nil and input ~= "" then
    key = oras.is_key(input) and input or oras.custom_key(input)
  end
  zone = zone_id(zone) or (old.manual and old.zone) or nil
  loc = zone_id(loc) or (old.manual and old.loc) or nil
  st.place = { key = key, name = name, zone = zone, loc = loc, manual = true }
  if key == old.key and name == old.name and old.manual then return st, nil end
  return st, { kind = "place", key = key, name = name, manual = true, previous = old.key }
end

-- Pairs-differ-primary-type clause: the creature's primary type is already taken by a partner's
-- creature on that route. Needs opts.types(species, form) and opts.partner_types(route).
local function type_clash(cfg, opts, route, species, form)
  if not cfg.rules.pairs_differ_primary_type or not route or not opts.types or not opts.partner_types then
    return false, nil
  end
  local ty = opts.types(species, form)
  if ty == nil then return false, nil end
  local taken = opts.partner_types(route)
  return type(taken) == "table" and taken[ty] == true, ty
end

-- The route a wild encounter belongs to: a manual place, else the area of the encounter's location
-- (core v0.3), else the current place.
local function encounter_route(st, e, opts)
  if st.place.manual and st.place.key then return st.place.key end
  local lid = zone_id(e.location)
  if lid ~= nil and opts.areas and opts.areas.set[lid] then return oras.area_key(lid) end
  return st.place.key
end

-- The route entry as detection sees it: the stored one, unless a correction newer than the entry
-- shadows it (opts.overrides, see corrections.route_overrides). Returns entry|nil and the override
-- seq (stamped as `rs` on entries created now, so the view and later polls treat them as valid).
local function live_entry(st, opts, key)
  local e = key and st.routes[key] or nil
  local ov = key and opts.overrides and opts.overrides[key] or nil
  if not ov then return e, nil end
  if e and (e.rs or 0) >= ov.seq then return e, ov.seq end -- created after the correction
  if ov.kind == "reopen" then return nil, ov.seq end
  if ov.kind == "missed" then
    local sp = e and e.status ~= "caught" and e.species or nil
    return { status = "missed", species = sp }, ov.seq
  end
  return { status = "caught", mon = ov.mon, kind = "gift" }, ov.seq -- taken: a hand-added mon
end

local function new_entry(e, rs)
  e.rs = rs
  return e
end

local function handle_encounter(st, cfg, pk, foe, horde, facts, family, opts)
  local fact = { kind = "encounter", route = pk, species = foe.species, form = foe.form,
                 shiny = foe.shiny == true, horde = horde, counts = false }
  fact.species_name = note_species(st, opts, foe.species, foe.species_name)
  local r = cfg.rules
  local existing, rs = live_entry(st, opts, pk)
  local clash = type_clash(cfg, opts, pk, foe.species, foe.form)
  if horde and not r.hordes_count then
    fact.why = "horde"
  elseif pk == nil then
    fact.why = "no_place"
  elseif fact.shiny and r.shiny_clause then
    fact.why = "shiny"
  elseif r.dupes_clause and owns_line(st, foe.species, family, opts) then
    fact.why = "dupe"
  elseif clash then
    fact.why = "type"
  elseif existing and r.first_encounter_only then
    fact.why = "used"
  else
    fact.counts = true
    if not existing then
      st.routes[pk] = new_entry({ status = "encounter", species = foe.species, kind = horde and "horde" or "wild" }, rs)
    end
  end
  facts[#facts + 1] = fact
end

local function handle_catch(st, cfg, c, pk, starter, facts, family, opts)
  local rec, r = c.rec, cfg.rules
  local dupe = r.dupes_clause and owns_line(st, rec.species, family, opts) -- before the mon is added
  local clash, ty = type_clash(cfg, opts, pk, rec.species, rec.form)
  local mon = {
    species = rec.species, form = rec.form, nickname = util.clean_text(rec.nickname, 24),
    level = rec.level, shiny = rec.shiny == true or nil, route = pk, where = c.where,
    hp = type(rec.hp) == "number" and rec.hp or nil,
    mhp = type(rec.max_hp) == "number" and rec.max_hp or nil, ty = ty,
  }
  if r.pairs_differ_primary_type and ty == nil and opts.types then mon.ty = opts.types(rec.species, rec.form) end
  if rec.nicknamed == false then mon.nicknamed = false end
  st.mons[c.pid] = mon
  local fact = { kind = "catch", mon = c.pid, species = rec.species, form = rec.form,
                 nickname = mon.nickname, level = rec.level, shiny = rec.shiny == true,
                 route = pk, where = c.where, counts = false, starter = starter or nil }
  fact.species_name = note_species(st, opts, rec.species, rec.species_name)
  local existing, rs = live_entry(st, opts, pk)
  if rec.egg then
    mon.gift, mon.why = true, "gift"
    fact.gift, fact.why = true, "gift"
  elseif pk == nil then
    fact.why = "no_place"
  elseif mon.shiny and r.shiny_clause then
    mon.why, fact.why = "shiny", "shiny"
  elseif dupe then
    mon.why, fact.why = "dupe", "dupe"
  elseif clash and not starter then
    mon.why, fact.why = "type", "type"
  else
    local entry = { status = "caught", mon = c.pid, species = rec.species,
                    kind = starter and "starter" or "wild" }
    if not existing or existing.status == "encounter" then
      st.routes[pk], fact.counts = new_entry(entry, rs), true
    elseif existing.status == "missed" and existing.species == rec.species then
      st.routes[pk], fact.counts = new_entry(entry, rs), true -- the catch arrived after the battle was closed
    elseif not r.first_encounter_only then
      mon.why, fact.why = "additional", "additional"
    else
      mon.why, fact.why = "extra", "extra"
    end
  end
  facts[#facts + 1] = fact
end

-- The route with the one pending encounter (a battle that has not ended in a catch or a miss), or nil.
local function pending_route(st, opts)
  local found
  for _, key in ipairs(util.keys(st.routes)) do
    local e = live_entry(st, opts, key)
    if e and e.status == "encounter" then
      if found then return nil end
      found = key
    end
  end
  return found
end

local function newest_seq(list)
  local max = 0
  for _, e in ipairs(list) do if e.seq > max then max = e.seq end end
  return max
end

D.PENDING_MS = 60000 -- how long an ended wild battle may stay undecided (caught or missed)

local function has_encounter(st, opts)
  for _, key in ipairs(util.keys(st.routes)) do
    local e = live_entry(st, opts, key)
    if e and e.status == "encounter" then return true end
  end
  return false
end

-- Close the pending encounter(s): routes still at "encounter" are missed.
local function expire_pending(st, facts, opts)
  st.pend = nil
  for _, key in ipairs(util.keys(st.routes)) do
    local e = live_entry(st, opts, key)
    if e and e.status == "encounter" then
      e = st.routes[key]
      e.status = "missed"
      facts[#facts + 1] = { kind = "missed", route = key, species = e.species }
    end
  end
end

-- Copy a list of ids into st[field] (limited); only when it changed.
local function sync_ids(st, field, src, max)
  if type(src) ~= "table" then return end
  local n = math.min(#src, max)
  local same = type(st[field]) == "table" and #st[field] == n
  if same then for i, id in ipairs(st[field]) do if src[i] ~= id then same = false; break end end end
  if not same then
    st[field] = {}
    for i = 1, n do st[field][i] = src[i] end
  end
end

--- diff(prev, snap, cfg, opts) -> new_state, facts
---   prev  own state (nil = fresh); never modified
---   snap  see the snapshot description above
---   cfg   result of rules.parse (or flat rule flags)
---   opts  { family = function(species) -> family id (default: species itself),
---           zones = zone -> route key table (fallback without a location id, default data.oras.ZONES),
---           areas = { set = { [location id] = true }, order = { location id, ... }, names = { [id] = name } }
---                   (pokemon-core areas(); nil while not ready),
---           areas_unsupported = bool (the core has no areas(): the zone table is the fallback),
---           names = { species = function(id) -> name|nil },   display names read from the game
---           types = function(species, form) -> primary type id|nil,
---           partner_types = function(route key) -> { [type id] = true } of the partners' creatures there,
---           first = "auto"|"baseline"|"starter" (what the first complete snapshot means),
---           game = { id, language } }
--- Tracking starts with the first snapshot where team and boxes are both known: then either
--- everything present is baseline, or (first = "starter", or "auto" with exactly one mon in the
--- team and no box mon) that mon is the starter caught on route "starter".
function D.diff(prev, snap, cfg, opts)
  opts = opts or {}
  cfg = rules.normalize(cfg)
  local st = state.ensure(util.copy(prev))
  snap = type(snap) == "table" and snap or {}
  local facts = {}
  local family = opts.family or default_family
  if type(opts.game) == "table" then
    st.game.id = st.game.id or opts.game.id
    st.game.language = st.game.language or opts.game.language
  end
  if opts.areas then
    sync_ids(st, "areas", opts.areas.order, state.MAX_AREAS)
    sync_ids(st, "places", opts.areas.places, state.MAX_PLACES)
  end

  local loc_now = type(snap.location) == "table" and snap.location or {}
  update_place(st, snap.location, facts, opts)
  local b = badge_count(snap.badges)
  if b then
    -- one badge fact per new badge once tracking runs (a first snapshot with badges owned is baseline)
    if st.started and b > st.badges then
      for i = st.badges + 1, math.min(b, 8) do facts[#facts + 1] = { kind = "badge", index = i, count = i } end
    end
    st.badges = b
  end

  local list, map, team_known, boxes_known = collect(snap)
  local bat = battle_info(snap)
  local catch_place
  local settled = not (bat.known and bat.active) and not st.inb -- no battle now, none ended just now
  local now = type(opts.now) == "number" and opts.now or nil

  -- encounters() with seq: only entries newer than the last handled one count
  local enc = {}
  local seq_mode = false
  if type(snap.encounters) == "table" then
    local first = snap.encounters[1]
    seq_mode = first == nil or (type(first) == "table" and math.type(first.seq) == "integer")
    if seq_mode then
      for _, e in ipairs(snap.encounters) do
        if type(e) == "table" and math.type(e.seq) == "integer" then enc[#enc + 1] = e end
      end
      table.sort(enc, function(x, y) return x.seq < y.seq end)
    end
  end

  if not st.started then
    if not (team_known and boxes_known) then return st, facts end
    local first = opts.first or "auto"
    local starter = first == "starter"
      or (first == "auto" and #list == 1 and list[1].where == "team" and not list[1].rec.egg)
    st.started = true
    if seq_mode then st.enc_seq = newest_seq(enc) end -- encounters before the tracking started are old
    if not starter then
      for _, c in ipairs(list) do st.baseline[c.pid] = true end
      st.inb = bat.known and bat.active or false
      return st, facts
    end
    catch_place = oras.STARTER
  end

  -- known mons: updates, moves, evolution, deaths, disappearance
  for _, pid in ipairs(util.keys(st.mons)) do
    local m, c = st.mons[pid], map[pid]
    if c then
      local rec = c.rec
      m.miss = nil
      if m.species ~= rec.species then
        facts[#facts + 1] = { kind = "evolve", mon = pid, from = m.species, to = rec.species,
                              nickname = m.nickname, route = m.route,
                              species_name = note_species(st, opts, rec.species, rec.species_name) }
        m.species = rec.species
        if m.ty ~= nil and opts.types then m.ty = opts.types(rec.species, rec.form) or m.ty end
      end
      m.form = rec.form
      note_species(st, opts, rec.species, rec.species_name) -- team rows show names, never "#id"
      m.level = rec.level or m.level
      m.nickname = util.clean_text(rec.nickname, 24) or m.nickname
      if rec.nicknamed == false then m.nicknamed = false elseif rec.nicknamed == true then m.nicknamed = nil end
      if rec.shiny == true then m.shiny = true end
      if m.where ~= c.where then
        facts[#facts + 1] = { kind = "moved", mon = pid, from = m.where, to = c.where }
        m.where = c.where
      end
      -- fainted: the party record itself shows hp 0 (with a plausible max hp) while no battle is running
      -- and none ended since the previous snapshot. The battle's own-battler data is never used (stale
      -- while a battle ends). While unsettled the last known hp stays, so the death is still counted.
      local team_hp = type(rec.hp) == "number" and rec.hp or nil
      if team_hp and team_hp <= 0 then
        local valid = rec.max_hp == nil or (type(rec.max_hp) == "number" and rec.max_hp > 0)
        if valid and settled then
          if m.hp and m.hp > 0 then
            m.deaths = (m.deaths or 0) + 1
            facts[#facts + 1] = { kind = "death", mon = pid, species = m.species, nickname = m.nickname,
                                  route = m.route, deaths = m.deaths,
                                  species_name = note_species(st, opts, m.species, rec.species_name) }
          end
          m.hp = 0
        end
      elseif team_hp then
        m.hp = team_hp
      end
      m.fz = nil
      if type(rec.max_hp) == "number" then m.mhp = rec.max_hp end
    elseif team_known and boxes_known and m.where ~= "gone" then
      m.miss = (m.miss or 0) + 1 -- gone only after two snapshots in a row (no transient states)
      if m.miss >= 2 then
        facts[#facts + 1] = { kind = "moved", mon = pid, from = m.where, to = "gone" }
        m.where, m.miss = "gone", nil
      end
    end
  end

  -- new mons: a catch lands on the pending encounter's route, else on the current place
  for _, c in ipairs(list) do
    if not st.baseline[c.pid] and not st.mons[c.pid] then
      handle_catch(st, cfg, c, catch_place or pending_route(st, opts) or st.place.key, catch_place ~= nil, facts, family, opts)
    end
  end

  -- team order (tracked mons only)
  if team_known then
    st.order = {}
    for _, c in ipairs(list) do
      if c.where == "team" and st.mons[c.pid] then st.order[#st.order + 1] = c.pid end
    end
  end

  -- encounters and missed routes
  if seq_mode then
    if st.enc_seq == nil then
      st.enc_seq = newest_seq(enc)
    else
      for _, e in ipairs(enc) do
        if e.seq > st.enc_seq then
          st.enc_seq = e.seq
          if st.pend then expire_pending(st, facts, opts) end
          handle_encounter(st, cfg, encounter_route(st, e, opts), e, e.horde == true, facts, family, opts)
        end
      end
    end
  end
  if bat.known then
    if not seq_mode and bat.active and not st.inb and bat.wild then
      if st.pend then expire_pending(st, facts, opts) end
      handle_encounter(st, cfg, st.place.key, bat.foes[1] or {}, bat.horde, facts, family, opts)
    elseif not bat.active and st.inb then
      -- the battle ended: caught, missed or fled is not known yet (the catch shows up in the party or
      -- the boxes only after the Pokedex page and the nickname dialog), so the encounter stays pending
      if has_encounter(st, opts) then
        st.pend = { since = now, zone = st.inb_zone, loc = st.inb_loc }
      end
    end
    if bat.active then
      st.inb_zone, st.inb_loc = zone_id(loc_now.zone) or st.inb_zone, zone_id(loc_now.location) or st.inb_loc
    else
      st.inb_zone, st.inb_loc = nil, nil
    end
    st.inb = bat.active
  elseif not seq_mode and type(snap.encounters) == "table" then
    for _, e in ipairs(snap.encounters) do
      if type(e) == "table" then
        handle_encounter(st, cfg, st.place.key, e, e.horde == true, facts, family, opts)
      end
    end
  end

  -- a pending encounter ends as caught (see above), or as missed when the player moved on, the next
  -- wild battle started or the timeout passed
  if st.pend then
    if not has_encounter(st, opts) then
      st.pend = nil
    else
      local p = st.pend
      local moved = (p.loc ~= nil and zone_id(loc_now.location) ~= nil and p.loc ~= zone_id(loc_now.location))
        or (p.zone ~= nil and p.loc == nil and zone_id(loc_now.zone) ~= nil and p.zone ~= zone_id(loc_now.zone))
      if p.since == nil and now then p.since = now end
      if moved or (now and p.since and now - p.since >= D.PENDING_MS) then expire_pending(st, facts, opts) end
    end
  end

  return st, facts
end

return D

end
__mod["model.events"] = function(...)
-- Payload builders for the automatic run events. Posting (fb.run.event) is done by the caller.
-- Builders return a spec { type =, payload =, source = "automatic" }; `text` (at most 280
-- characters, translated, with names read from the game) is added by the caller.
local util = require("model.util")

local E = {}

E.TYPES = {
  catch = "soullink.catch",
  death = "soullink.death",
  encounter = "soullink.encounter",
  place = "soullink.place",
  badge = "soullink.badge",
  correction = "soullink.correction",
}
E.MAX_PAYLOAD = 4096

local function put(t, k, v) if v ~= nil then t[k] = v end end

--- Build the event spec for a detection fact, or nil for facts without an event
--- (evolve, moved). `user` is the user id of the own participant.
---   catch     payload { user, mon, species, species_name?, form?, nickname?, level?, shiny?, route?, counts, why?, gift?, starter?, where }
---   death     payload { user, mon, species, species_name?, nickname?, route?, deaths }
---   encounter payload { user, outcome = "seen"|"missed", route?, species?, species_name?, form?, shiny?, horde?, counts, why? }
---   place     payload { user, route?, name?, manual }
---   badge     payload { user, index, count } (badge number 1..8; no names)
function E.from_fact(fact, user)
  local k = fact.kind
  local p = { user = user }
  if k == "catch" then
    p.mon, p.species, p.counts, p.where = fact.mon, fact.species, fact.counts, fact.where
    put(p, "form", fact.form); put(p, "nickname", fact.nickname); put(p, "level", fact.level)
    put(p, "route", fact.route); put(p, "why", fact.why); put(p, "species_name", fact.species_name)
    if fact.shiny then p.shiny = true end
    if fact.gift then p.gift = true end
    if fact.starter then p.starter = true end
    return { type = E.TYPES.catch, payload = p, source = "automatic" }
  elseif k == "death" then
    p.mon, p.species, p.deaths = fact.mon, fact.species, fact.deaths
    put(p, "nickname", fact.nickname); put(p, "route", fact.route); put(p, "species_name", fact.species_name)
    return { type = E.TYPES.death, payload = p, source = "automatic" }
  elseif k == "encounter" or k == "missed" then
    p.outcome = k == "missed" and "missed" or "seen"
    if k == "missed" then p.counts = false else p.counts = fact.counts end
    put(p, "route", fact.route); put(p, "species", fact.species)
    if k == "encounter" then
      put(p, "form", fact.form); put(p, "why", fact.why); put(p, "species_name", fact.species_name)
      if fact.shiny then p.shiny = true end
      if fact.horde then p.horde = true end
    end
    return { type = E.TYPES.encounter, payload = p, source = "automatic" }
  elseif k == "badge" then
    p.index, p.count = fact.index, fact.count
    return { type = E.TYPES.badge, payload = p, source = "automatic" }
  elseif k == "place" then
    put(p, "route", fact.key); put(p, "name", fact.name)
    p.manual = fact.manual == true
    return { type = E.TYPES.place, payload = p, source = "automatic" }
  end
  return nil
end

--- All specs for a list of facts, in order.
function E.from_facts(facts, user)
  local out = {}
  for _, f in ipairs(facts) do
    local s = E.from_fact(f, user)
    if s then out[#out + 1] = s end
  end
  return out
end

--- True when the payload fits the platform limit (4 KiB).
function E.fits(payload) return util.json_size(payload) <= E.MAX_PAYLOAD end

return E

end
__mod["model.gym"] = function(...)
-- Gym leader battle detection for the save snapshot "before Gym N". Pure; never touches fb.
-- pokemon.core marks no boss or gym battles, so a gym leader is recognised by what it does report:
-- a trainer battle (battle.kind == "trainer") in which a foe has reached the level cap of the next gym
-- (oras.level_cap(badges), the leader's strongest creature). Gym trainers before the leader stay below
-- the cap. The cap table is a local-verification hint (data/oras.lua), so this is a heuristic.
local M = {}

M.MAX_ATTEMPTS = 5 -- tries per gym and battle when fb.save.snapshot refuses (rate limit)

--- Number (1..8) of the gym whose leader fights now, or nil.
--- `battle` is the core's battle() table, `badges` the badges owned, `level_cap` the table lookup.
function M.gym_number(battle, badges, level_cap)
  if type(battle) ~= "table" or battle.active ~= true or battle.kind ~= "trainer" then return nil end
  if math.type(badges) ~= "integer" or badges < 0 or badges > 7 then return nil end
  local cap = level_cap(badges)
  if math.type(cap) ~= "integer" then return nil end
  local top = 0
  for _, foe in ipairs(type(battle.foes) == "table" and battle.foes or {}) do
    if type(foe) == "table" and math.type(foe.level) == "integer" and foe.level > top then top = foe.level end
  end
  if top >= cap then return badges + 1 end
  return nil
end

return M

end
__mod["model.rules"] = function(...)
-- Run rules: defaults and parsing of the run settings.
-- Settings live in the run settings under the plugin id:
--   run.settings["uzume.soullink"] = { mode = "soullink", rules = { dupes_clause = false, ... } }
local R = {}

R.PLUGIN_ID = "uzume.soullink"
R.MODES = { nuzlocke = true, soullink = true }

--- Default rule switches (all are booleans).
R.DEFAULTS = {
  first_encounter_only = true,
  dupes_clause = true,
  shiny_clause = true,
  hordes_count = false,
  pairs_differ_primary_type = false,
  only_linked_in_team = false,
  nickname_required = true,
  level_caps = true,
}

--- Rule keys in a fixed order (for UI lists).
R.ORDER = {
  "first_encounter_only", "dupes_clause", "shiny_clause", "hordes_count",
  "pairs_differ_primary_type", "only_linked_in_team", "nickname_required", "level_caps",
}

--- Fresh copy of the default rules.
function R.defaults()
  local t = {}
  for k, v in pairs(R.DEFAULTS) do t[k] = v end
  return t
end

--- Number of participants with status "joined" (a missing status counts as joined).
function R.joined_count(run)
  local n = 0
  for _, p in ipairs(type(run) == "table" and run.participants or {}) do
    if type(p) == "table" and (p.status == nil or p.status == "joined") then n = n + 1 end
  end
  return n
end

--- Parse the rules of a run (`fb.run.current()` result, may be nil).
--- Returns cfg = { mode = "nuzlocke"|"soullink", mode_set = bool, rules = {<flag> = bool} }.
--- Unknown keys are ignored, wrong types fall back to the defaults. Without a valid mode:
--- "soullink" with two or more joined participants, otherwise "nuzlocke".
function R.parse(run)
  local mine
  if type(run) == "table" and type(run.settings) == "table" then
    mine = run.settings[R.PLUGIN_ID]
  end
  if type(mine) ~= "table" then mine = {} end
  local cfg = { rules = R.defaults(), mode_set = false }
  if type(mine.mode) == "string" and R.MODES[mine.mode] then
    cfg.mode, cfg.mode_set = mine.mode, true
  else
    cfg.mode = R.joined_count(run) >= 2 and "soullink" or "nuzlocke"
  end
  if type(mine.rules) == "table" then
    for k, default in pairs(R.DEFAULTS) do
      local v = mine.rules[k]
      if type(v) == type(default) then cfg.rules[k] = v end
    end
  end
  return cfg
end

--- Accepts a cfg from parse(), a flat table of rule flags or nil; returns a complete cfg.
function R.normalize(x)
  if type(x) == "table" and type(x.rules) == "table" and R.MODES[x.mode] then
    local cfg = { mode = x.mode, mode_set = x.mode_set == true, rules = R.defaults() }
    for k, default in pairs(R.DEFAULTS) do
      if type(x.rules[k]) == type(default) then cfg.rules[k] = x.rules[k] end
    end
    return cfg
  end
  local cfg = { mode = "nuzlocke", mode_set = false, rules = R.defaults() }
  if type(x) == "table" then
    if type(x.mode) == "string" and R.MODES[x.mode] then cfg.mode, cfg.mode_set = x.mode, true end
    local flat = type(x.rules) == "table" and x.rules or x
    for k, default in pairs(R.DEFAULTS) do
      if type(flat[k]) == type(default) then cfg.rules[k] = flat[k] end
    end
  end
  return cfg
end

--- Settings table to store in the run settings for `cfg` (what a run creator writes).
function R.to_settings(cfg)
  cfg = R.normalize(cfg)
  local rules = {}
  for k, v in pairs(cfg.rules) do rules[k] = v end
  return { [R.PLUGIN_ID] = { mode = cfg.mode, rules = rules } }
end

return R

end
__mod["model.snapshot"] = function(...)
-- Builds the detection snapshot from the `pokemon.core` interface.
-- Every method may be missing (nil, "unsupported") or not ready (nil, "not_ready"); a missing
-- part stays nil in the snapshot ("unknown"), which detect.diff handles without inventing data.
-- Shapes follow pokemon.core v0.3 (location {zone, location, name}, battle {active, kind, horde, foes, own},
-- encounters [{seq, species, form, shiny, horde, zone, location}], badges {count, flags}).
local P = {}

P.INTERFACE = "pokemon.core"

--- collect(call) -> snapshot, issues
---   call(fn, ...) returns what pokemon.core's `fn` returns (see from_core). Errors are caught.
---   issues = { team = reason?, boxes = reason?, location = ..., battle = ..., encounters = ..., badges = ... }
--- opts.unsupported: table kept by the caller; a part the core answers with "unsupported" is recorded
--- there and not asked again.
--- opts.skip_boxes: do not read the boxes, use opts.boxes (the last complete read) instead.
--- Box numbers run 1..box_count() (assumption; the core documents box(n) without a base: open).
function P.collect(call, opts)
  opts = opts or {}
  local snap, issues = {}, {}
  local function ask(fn, ...)
    local ok, a, b = pcall(call, fn, ...)
    if not ok then return nil, "error" end
    return a, b
  end
  local function part(name, fn, ...)
    if opts.unsupported and opts.unsupported[name] then issues[name] = "unsupported"; return end
    local v, why = ask(fn, ...)
    if why == "unsupported" and opts.unsupported then opts.unsupported[name] = true end
    if type(v) == "table" or (name == "badges" and type(v) == "number") then
      snap[name] = v
    else
      issues[name] = why or "unavailable"
    end
  end

  part("team", "team")
  local n, why
  if opts.skip_boxes then
    snap.boxes = opts.boxes
    if not opts.boxes then issues.boxes = "not_ready" end
    n = -1
  else
    n, why = ask("box_count")
  end
  if n == -1 then
    -- boxes taken from the cache above
  elseif math.type(n) == "integer" and n >= 0 then
    local boxes, complete = {}, true
    for i = 1, n do
      local box = ask("box", i)
      if type(box) == "table" then boxes[i] = box else complete = false; issues.boxes = "not_ready"; break end
    end
    if complete then snap.boxes = boxes end
  else
    issues.boxes = why or "unavailable"
  end
  part("location", "location")
  part("battle", "battle")
  -- core v0.3: kind = "wild" | "trainer" | nil; the detection reads `wild`
  if type(snap.battle) == "table" and snap.battle.wild == nil then
    local b = {}
    for k, v in pairs(snap.battle) do b[k] = v end
    b.wild = b.kind == "wild"
    snap.battle = b
  end
  part("encounters", "encounters")
  part("badges", "badges")
  return snap, issues
end

--- Snapshot from the live core: fb.call("pokemon.core", fn, ...).
function P.from_core(fb, opts)
  return P.collect(function(fn, ...) return fb.call(P.INTERFACE, fn, ...) end, opts)
end

return P

end
__mod["model.state"] = function(...)
-- Own state: one object per participant, written with fb.run.setState (limit 64 KiB).
local util = require("model.util")

local S = {}

S.VERSION = 1
--- Soft limit well below the 64 KiB platform limit; guard() compacts above it.
S.MAX_BYTES = 48 * 1024
S.MAX_NAMES = { sp = 400, loc = 200 }  -- entries per name table
S.NAME_LEN = { sp = 24, loc = 32 }     -- characters per name
S.MAX_AREAS = 400
S.MAX_PLACES = 600

--- Fresh state. `game` = { id = ..., language = ... } (both optional).
---
--- Schema (v = 1), all keys strings, JSON-able:
---   v, started (bool: baseline taken), inb (bool: wild battle was active at the last diff)
---   game   = { id, language }
---   place  = { key?, name?, zone?, manual }   key = route key or nil (no place / not a route)
---   baseline = { ["<hex8 personality>"] = true }   mons present before tracking, ignored forever
---   mons   = { ["<hex8>"] = { species, form?, nickname?, nicknamed? (false only), level, shiny? (true only),
---              route?, where = "team"|"box"|"gone", deaths? (absent = 0), hp?, gift? (true only),
---              why? = "extra"|"dupe"|"shiny"|"additional"|"gift", miss? } }
---   routes = { [route key] = { status = "encounter"|"caught"|"missed", mon?, species?, kind? } }
---   order  = { "<hex8>", ... }   tracked mons in team order
---   badges = number
---   names  = { sp = { ["<species id>"] = name }, loc = { ["<location id>"] = name } }   display names read from
---            the game when a catch / encounter / place was recorded (short, one entry per id), so other
---            players and the server show names without a running game
---   areas  = { <location id>, ... }   encounter areas in game order (pokemon-core areas()), for ordering
---   places = { <location id>, ... }   every place of the game in game order (pokemon-core locations(), else
---            the areas), for the place select; areas is the subset with encounter slots
---   pend   = { since?, zone?, loc? }   a wild battle ended and its encounter is still undecided: it becomes
---            caught when the mon shows up, missed when the player moves on, the next wild battle starts or
---            60 s pass (model.detect)
---   enc_seq = n   last handled pokemon-core encounters() seq
---   mons[..].ty = n   primary type id (only with the rule pairs_differ_primary_type)
function S.new(game)
  local g = {}
  if type(game) == "table" then
    g.id = game.id
    g.language = game.language
  end
  return S.ensure({
    v = S.VERSION, started = false, inb = false,
    game = g, place = { manual = false },
    baseline = {}, mons = {}, routes = {}, order = {}, badges = 0,
  })
end

--- Complete a state received from the server (nil or older shape) so the model can use it.
function S.ensure(st)
  if type(st) ~= "table" then return S.new() end
  st.v = st.v or S.VERSION
  st.game = st.game or {}
  st.place = st.place or { manual = false }
  st.baseline = st.baseline or {}
  st.mons = st.mons or {}
  st.routes = st.routes or {}
  st.order = st.order or {}
  st.badges = st.badges or 0
  st.names = type(st.names) == "table" and st.names or {}
  st.names.sp = type(st.names.sp) == "table" and st.names.sp or {}
  st.names.loc = type(st.names.loc) == "table" and st.names.loc or {}
  return st
end

--- Remember a display name read from the game: kind "sp" (species id) or "loc" (location id).
--- Short, deduplicated per id, limited in count. Returns true when the table changed.
function S.note_name(st, kind, id, name)
  if math.type(id) == "float" then id = math.tointeger(id) end
  if math.type(id) ~= "integer" or type(name) ~= "string" then return false end
  name = util.clean_text(name, S.NAME_LEN[kind])
  if not name then return false end
  S.ensure(st)
  local t, k = st.names[kind], tostring(id)
  if t[k] == name then return false end
  if t[k] == nil then
    local n = 0
    for _ in pairs(t) do n = n + 1 end
    if n >= S.MAX_NAMES[kind] then return false end
  end
  t[k] = name
  return true
end

--- Death count of a tracked mon (absent = 0).
function S.deaths(mon) return mon and mon.deaths or 0 end

--- Size in bytes of the JSON encoding of `st`.
function S.size(st) return util.json_size(st) end

--- Drop what can be dropped safely when the state is large: mons that are gone and own no route
--- entry, then shorten nicknames. Returns the (same) state. Baseline entries are never dropped.
function S.compact(st)
  local referenced = {}
  for _, r in pairs(st.routes) do if r.mon then referenced[r.mon] = true end end
  for pid, m in pairs(st.mons) do
    if m.where == "gone" and not referenced[pid] and (m.deaths or 0) == 0 then st.mons[pid] = nil end
  end
  if S.size(st) > S.MAX_BYTES then
    -- names nothing refers to
    local sp, loc = {}, {}
    for _, m in pairs(st.mons) do sp[tostring(m.species)] = true end
    for key, r in pairs(st.routes) do
      sp[tostring(r.species or "")] = true
      local id = key:match("^loc:(%d+)$")
      if id then loc[id] = true end
    end
    local pid = st.place and st.place.loc
    if pid then loc[tostring(pid)] = true end
    for k in pairs(st.names.sp) do if not sp[k] then st.names.sp[k] = nil end end
    for k in pairs(st.names.loc) do if not loc[k] then st.names.loc[k] = nil end end
  end
  if S.size(st) > S.MAX_BYTES then
    for _, m in pairs(st.mons) do
      if m.nickname then m.nickname = util.clean_text(m.nickname, 12) end
    end
  end
  return st
end

--- Size guard: returns ok, bytes. Compacts when above MAX_BYTES; ok is false when it still is.
function S.guard(st)
  local n = S.size(st)
  if n <= S.MAX_BYTES then return true, n end
  S.compact(st)
  n = S.size(st)
  return n <= S.MAX_BYTES, n
end

return S

end
__mod["model.util"] = function(...)
-- Small pure helpers shared by the model modules.
local U = {}

--- Deep copy of plain data (tables, strings, numbers, booleans).
function U.copy(v)
  if type(v) ~= "table" then return v end
  local c = {}
  for k, x in pairs(v) do c[k] = U.copy(x) end
  return c
end

--- Sorted list of the keys of `t` (strings or numbers; mixed keys sort by string form).
function U.keys(t)
  local out = {}
  for k in pairs(t or {}) do out[#out + 1] = k end
  table.sort(out, function(a, b)
    if type(a) == type(b) and (type(a) == "number" or type(a) == "string") then return a < b end
    return tostring(a) < tostring(b)
  end)
  return out
end

--- Personality value -> 8-hex-digit lowercase string (the key of a Pokemon in the own state).
--- Returns nil when `n` is not an integer value.
function U.hex8(n)
  if math.type(n) == "float" then n = math.tointeger(n) end
  if math.type(n) ~= "integer" then return nil end
  return string.format("%08x", n & 0xffffffff)
end

local ESC = { ['"'] = '\\"', ["\\"] = "\\\\", ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t" }

local function enc_string(s)
  return '"' .. s:gsub('[%c"\\]', function(c)
    return ESC[c] or string.format("\\u%04x", c:byte())
  end) .. '"'
end

local function is_array(t)
  local n = 0
  for _ in pairs(t) do n = n + 1 end
  if n == 0 then return false end
  for i = 1, n do if t[i] == nil then return false end end
  return true
end

--- Deterministic JSON encoding (sorted object keys). Used to measure state and payload sizes.
--- Raises on functions and non-finite numbers.
function U.encode(v)
  local tv = type(v)
  if tv == "nil" then return "null" end
  if tv == "boolean" then return tostring(v) end
  if tv == "number" then
    if v ~= v or v == math.huge or v == -math.huge then error("non-finite number") end
    if math.type(v) == "integer" then return tostring(v) end
    return string.format("%.14g", v)
  end
  if tv == "string" then return enc_string(v) end
  if tv ~= "table" then error("cannot encode " .. tv) end
  local out = {}
  if is_array(v) then
    for i = 1, #v do out[i] = U.encode(v[i]) end
    return "[" .. table.concat(out, ",") .. "]"
  end
  for _, k in ipairs(U.keys(v)) do
    out[#out + 1] = enc_string(tostring(k)) .. ":" .. U.encode(v[k])
  end
  return "{" .. table.concat(out, ",") .. "}"
end

--- Size in bytes of the JSON encoding.
function U.json_size(v) return #U.encode(v) end

--- Trim and collapse whitespace; nil for empty.
function U.clean_text(s, max)
  if type(s) ~= "string" then return nil end
  s = s:gsub("%c", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
  if s == "" then return nil end
  if max and utf8.len(s) and utf8.len(s) > max then
    s = s:sub(1, (utf8.offset(s, max + 1) or (#s + 1)) - 1)
  elseif max and #s > max and not utf8.len(s) then
    s = s:sub(1, max)
  end
  return s
end

return U

end
__mod["model.view"] = function(...)
-- Derived run view: everything the UI shows, computed from the participants' own states and the
-- run events. Pure and deterministic: the same inputs give the same table (no clocks, no pairs()
-- order dependence). Nothing is stored; link groups, deaths and numbers are recomputed.
local util = require("model.util")
local rules = require("model.rules")
local state = require("model.state")
local corrections = require("model.corrections")
local events_mod = require("model.events")
local oras = require("data.oras")

local V = {}

local INF = math.huge

local function joined(p) return p.status == nil or p.status == "joined" end
local function mkey(owner, id) return owner .. "\0" .. id end

local function collect_events(events)
  local list = {}
  for _, ev in ipairs(events or {}) do
    if type(ev) == "table" and math.type(ev.seq) == "integer" then list[#list + 1] = ev end
  end
  table.sort(list, function(a, b) return a.seq < b.seq end)
  local catch_seq, death_seq = {}, {}
  for _, ev in ipairs(list) do
    local p = type(ev.payload) == "table" and ev.payload or {}
    local user = ev.user_id or p.user
    if ev.type == events_mod.TYPES.catch and user and type(p.mon) == "string" then
      local k = mkey(user, p.mon)
      if not catch_seq[k] then catch_seq[k] = ev.seq end
    elseif ev.type == events_mod.TYPES.death and user and type(p.mon) == "string" then
      local k = mkey(user, p.mon)
      death_seq[k] = death_seq[k] or {}
      if not death_seq[k][p.deaths or 0] then death_seq[k][p.deaths or 0] = ev.seq end
    end
  end
  local effective, invalid = corrections.effective(list)
  return catch_seq, death_seq, effective, invalid
end

local function new_vmon(owner, id, m)
  return {
    id = id, owner = owner, species = m.species, form = m.form, nickname = m.nickname, ty = m.ty,
    nicknamed = m.nicknamed, level = m.level, shiny = m.shiny == true, own_route = m.route,
    where = m.where or "box", hp = m.hp, mhp = m.mhp, base_gift = m.gift == true, why = m.why,
    deaths = m.deaths or 0, manual = 0, undone = 0, virtual = false,
  }
end

local function eff_deaths(vm) return vm.deaths + vm.manual end
local function own_dead(vm) return eff_deaths(vm) > vm.undone end
local function is_gift(vm)
  if vm.gift_override ~= nil then return vm.gift_override end
  return vm.base_gift or vm.entry_kind == "gift"
end

-- Build per-player working data and apply the effective corrections in seq order.
local function build_players(players, states, effective, catch_seq, death_seq)
  local pv = {}
  for _, pl in ipairs(players) do
    local st = state.ensure(util.copy(states[pl.id]))
    local w = { st = st, mons = {}, ids = {}, routes = util.copy(st.routes), overrides = {} }
    for _, pid in ipairs(util.keys(st.mons)) do
      w.mons[pid] = new_vmon(pl.id, pid, st.mons[pid])
      w.ids[#w.ids + 1] = pid
    end
    for _, route in ipairs(util.keys(w.routes)) do
      local e = w.routes[route]
      local vm = e.status == "caught" and e.mon and w.mons[e.mon]
      if vm then vm.counted_route, vm.entry_kind = route, e.kind end
    end
    w.overrides, w.excluded = corrections.route_overrides(effective, pl.id, st)
    pv[pl.id] = w
  end

  for _, c in ipairs(effective) do
    local p, seq = c.p, c.seq
    local w = p.user and pv[p.user]
    local k = p.kind
    if k == "set_group" and w and w.mons[p.mon] then
      local vm = w.mons[p.mon]
      vm.group_override = p.group ~= "none" and p.group or false
      vm.slot_seq = seq
    elseif k == "add" and w then
      local id = "add-" .. seq
      local vm = new_vmon(p.user, id, { species = p.species, form = p.form, nickname = p.nickname,
        level = p.level, shiny = p.shiny, route = p.route, where = p.state == "team" and "team" or "box",
        deaths = p.state == "dead" and 1 or 0 })
      vm.virtual, vm.slot_seq, vm.add_route = true, seq, p.route
      w.mons[id] = vm
      w.ids[#w.ids + 1] = id
      catch_seq[mkey(p.user, id)] = seq
      if p.state == "dead" then
        death_seq[mkey(p.user, id)] = { [1] = seq }
      end
    elseif k == "mark_dead" and w and w.mons[p.mon] then
      local vm = w.mons[p.mon]
      vm.manual = vm.manual + 1
      local dk = mkey(p.user, p.mon)
      death_seq[dk] = death_seq[dk] or {}
      death_seq[dk][eff_deaths(vm)] = seq
    elseif k == "set_gift" and w and w.mons[p.mon] then
      w.mons[p.mon].gift_override = p.gift
    elseif k == "undo_death" then
      for _, e in ipairs(p.undone) do
        local ow = pv[e.owner]
        local vm = ow and ow.mons[e.mon]
        if vm and e.deaths > vm.undone then vm.undone = e.deaths end
      end
    end
  end
  -- mons that "doesn't count" removed (decided together with the route overrides, see corrections.route_overrides)
  for _, pl in ipairs(players) do
    local w = pv[pl.id]
    for id, c in pairs(w.excluded) do
      local vm = w.mons[id]
      if vm then vm.excluded, vm.why = true, c.p.reason or "manual" end
    end
  end
  return pv
end

-- Claim route slots (route x player -> mon). Counted mons first, then moved mons, then hand-added.
local function assign_slots(players, pv)
  for _, pl in ipairs(players) do
    local w = pv[pl.id]
    w.slots = {}
    local function claim(vm, route)
      if w.slots[route] then return false end
      w.slots[route], vm.slot = vm, route
      return true
    end
    for _, id in ipairs(w.ids) do
      local vm = w.mons[id]
      if not vm.virtual and not vm.excluded and vm.group_override == nil and vm.counted_route then
        claim(vm, vm.counted_route)
      end
    end
    for _, id in ipairs(w.ids) do
      local vm = w.mons[id]
      if not vm.virtual and not vm.excluded and vm.group_override ~= nil then
        if vm.group_override == false then
          if vm.counted_route and claim(vm, vm.counted_route) then vm.unlinked = true end
        elseif not claim(vm, vm.group_override) then
          vm.group_conflict = true
        end
      end
    end
    for _, id in ipairs(w.ids) do
      local vm = w.mons[id]
      if vm.virtual and not vm.excluded then
        if not claim(vm, vm.add_route) then vm.why = vm.why or "extra" end
      end
    end
  end
end

local function cell_state(w, route)
  local vm = w.slots[route]
  if vm then return "caught", vm end
  local e, ov = w.routes[route], w.overrides[route]
  if ov and (not e or (e.rs or 0) < ov.seq) then
    -- a correction newer than the stored entry: the entry is shadowed (see corrections.route_overrides)
    return ov.kind == "missed" and "missed" or "open"
  end
  if e then
    if e.status == "missed" then return "missed" end
    if e.status == "encounter" then return "encounter", nil, e end
  end
  return "open"
end

--- view(run, states, events, cfg) -> table
---   run     fb.run.current() result (participants, settings)
---   states  user_id -> own state of this plugin (fb.run.states())
---   events  run events (fb.run.events), ascending by seq; other event types are ignored
---   cfg     rules.parse() result; nil = parse from `run`
--- See docs/architecture.md for the result fields.
--- Zone table merged over all players: static `data.oras.ZONES` first, then the states' learned
--- `zones` (zone id as string -> route key | false). The own state (run.me) wins over the others,
--- the others are taken in user id order. Returns zone (integer) -> route key | false.
function V.merge_zones(run, states)
  local out = {}
  for z, v in pairs(oras.ZONES) do out[z] = v end
  local ids = {}
  for id in pairs(states or {}) do if id ~= run.me then ids[#ids + 1] = id end end
  table.sort(ids)
  table.insert(ids, 1, run.me)
  local seen = {}
  for _, id in ipairs(ids) do
    local zs = states and states[id] and states[id].zones
    if type(zs) == "table" then
      for k, v in pairs(zs) do
        local z = math.tointeger(tonumber(k))
        local ok = v == false or (type(v) == "string" and v ~= oras.STARTER and oras.is_key(v))
        if z and ok and oras.ZONES[z] == nil and not seen[z] then out[z], seen[z] = v, true end
      end
    end
  end
  return out
end

local function ids_me_first(run, states)
  local ids = {}
  for id in pairs(states or {}) do if id ~= run.me then ids[#ids + 1] = id end end
  table.sort(ids)
  table.insert(ids, 1, run.me or "")
  return ids
end

--- Display names stored in the participants' states (own first; the first name per id wins):
--- { sp = { ["<species id>"] = name }, loc = { ["<location id>"] = name } }.
function V.merge_names(run, states)
  local out = { sp = {}, loc = {} }
  for _, id in ipairs(ids_me_first(run, states)) do
    local nm = states and states[id] and states[id].names
    if type(nm) == "table" then
      for kind, dst in pairs(out) do
        if type(nm[kind]) == "table" then
          for k, v in pairs(nm[kind]) do
            if type(v) == "string" and v ~= "" and dst[k] == nil then dst[k] = v end
          end
        end
      end
    end
  end
  return out
end

--- Encounter areas in game order (location ids): the own list, then ids only others know.
function V.merge_areas(run, states)
  local out, seen = {}, {}
  for _, id in ipairs(ids_me_first(run, states)) do
    local a = states and states[id] and states[id].areas
    if type(a) == "table" then
      for _, lid in ipairs(a) do
        if math.type(lid) == "integer" and not seen[lid] then seen[lid] = true; out[#out + 1] = lid end
      end
    end
  end
  return out
end

--- Every place of the game in game order (location ids): the own list, then ids only others know;
--- states from before v0.4.1 only know the encounter areas.
function V.merge_places(run, states)
  local out, seen = {}, {}
  for _, id in ipairs(ids_me_first(run, states)) do
    local st = states and states[id]
    local a = type(st) == "table" and (type(st.places) == "table" and st.places or st.areas) or nil
    if type(a) == "table" then
      for _, lid in ipairs(a) do
        if math.type(lid) == "integer" and not seen[lid] then seen[lid] = true; out[#out + 1] = lid end
      end
    end
  end
  return out
end

--- The run's randomizer fact from `fb.run.current().randomizer` (Uzume 0.21), or nil: absent, malformed or an
--- unknown mode. Only mode, preset id and label are kept; seeds and settings are never exposed or shown.
local RANDOMIZER_MODES = { each = true, same = true }
function V.randomizer(run)
  local r = type(run) == "table" and run.randomizer or nil
  if type(r) ~= "table" or not RANDOMIZER_MODES[r.mode] then return nil end
  local label = type(r.preset_label) == "string" and r.preset_label:match("^%s*(.-)%s*$") or ""
  if #label > 40 then label = label:sub(1, 40) end
  return { mode = r.mode, preset_id = type(r.preset_id) == "string" and r.preset_id or nil,
           preset_label = label ~= "" and label or nil }
end

function V.view(run, states, events, cfg)
  run, states = run or {}, states or {}
  cfg = cfg and rules.normalize(cfg) or rules.parse(run)
  local soul = cfg.mode == "soullink"

  local players = {}
  for _, p in ipairs(run.participants or {}) do
    if type(p) == "table" and p.user_id and joined(p) then
      players[#players + 1] = { id = p.user_id, name = p.name or p.user_name or p.user_id,
                                color = p.color, game_id = p.game_id, own_variant = p.variant_kind == "own" or nil }
    end
  end
  if #players == 0 then
    for _, uid in ipairs(util.keys(states)) do players[#players + 1] = { id = uid, name = uid } end
  end
  local pindex = {}
  for i, pl in ipairs(players) do pindex[pl.id] = i end

  local names = V.merge_names(run, states)
  local areas = V.merge_areas(run, states)
  local places = V.merge_places(run, states)
  local order = {}
  for i, lid in ipairs(places) do order[oras.area_key(lid)] = i end
  local function sname(species) return names.sp[tostring(species)] end

  local catch_seq, death_seq, effective, invalid = collect_events(events)
  local pv = build_players(players, states, effective, catch_seq, death_seq)
  assign_slots(players, pv)

  -- routes with any activity, plus the current places
  local route_set = {}
  for _, pl in ipairs(players) do
    local w = pv[pl.id]
    for r in pairs(w.slots) do route_set[r] = true end
    for r in pairs(w.routes) do route_set[r] = true end
    for r, o in pairs(w.overrides) do if o.kind == "missed" then route_set[r] = true end end
    if w.st.place.key then route_set[w.st.place.key] = true end
  end
  local route_keys = util.keys(route_set)
  table.sort(route_keys, function(a, b) return oras.compare(a, b, order) end)

  -- groups
  local groups, group_of = {}, {}
  if soul then
    for _, r in ipairs(route_keys) do
      local members, missed, gift, nolink = {}, false, false, false
      for _, pl in ipairs(players) do
        local w = pv[pl.id]
        local vm = w.slots[r]
        if vm then
          members[#members + 1] = vm
          gift = gift or is_gift(vm)
          nolink = nolink or vm.unlinked == true
        elseif (cell_state(w, r)) == "missed" then
          missed = true
        end
      end
      if #members > 0 then
        local g = { route = r, members = {}, count = #members, complete = #members == #players }
        local any_dead = false
        for _, vm in ipairs(members) do if own_dead(vm) then any_dead = true end end
        if gift then g.state = "gift"
        elseif nolink then g.state = "nolink"
        elseif missed then g.state = "broken"
        elseif any_dead then g.state = "dead"
        elseif g.complete then g.state = "linked"
        else g.state = "open" end
        g.propagates = g.state == "linked" or g.state == "dead" or g.state == "open"
        g.mons = members
        groups[#groups + 1] = g
        group_of[r] = g
      end
    end
  end

  -- deaths (own and propagated), dead on arrival, completion order, numbers
  local function seq_of_catch(vm)
    local s = math.max(catch_seq[mkey(vm.owner, vm.id)] or 0, vm.slot_seq or 0)
    return s > 0 and s or nil
  end
  for _, g in ipairs(groups) do
    local died, completed, lacking = INF, 0, false
    for _, vm in ipairs(g.mons) do
      if own_dead(vm) then
        local s = (death_seq[mkey(vm.owner, vm.id)] or {})[eff_deaths(vm)]
        if s and s < died then died = s end
      end
      local s = seq_of_catch(vm)
      if s then completed = math.max(completed, s) else lacking = true end
    end
    g.died_seq = died < INF and died or nil
    g.completed_seq = (not lacking and completed > 0) and completed or nil
    for _, vm in ipairs(g.mons) do
      if g.propagates and g.state == "dead" then
        vm.dead = true
        vm.cause = own_dead(vm) and "own" or "linked"
        if vm.cause == "linked" and g.died_seq then
          local s = seq_of_catch(vm)
          vm.doa = s ~= nil and s > g.died_seq or nil
        end
      end
      vm.group_state = g.state
    end
  end
  local numbered = {}
  for _, g in ipairs(groups) do
    if g.complete and (g.state == "linked" or g.state == "dead") then numbered[#numbered + 1] = g end
  end
  table.sort(numbered, function(a, b)
    local sa, sb = a.completed_seq or INF, b.completed_seq or INF
    if sa ~= sb then return sa < sb end
    return oras.compare(a.route, b.route, order)
  end)
  for i, g in ipairs(numbered) do g.number = i end

  -- mon views, players
  local out_players, graveyard, hints = {}, {}, {}
  local stats = { deaths = 0, groups_dead = 0, groups_linked = 0, routes_done = 0, routes_total = 0,
                  badges_max = 0, alive = 0 }
  local function mon_view(vm)
    if not vm.dead and own_dead(vm) then vm.dead, vm.cause = true, "own" end
    local g = vm.slot and group_of[vm.slot]
    return {
      id = vm.id, owner = vm.owner, species = vm.species, species_name = sname(vm.species), form = vm.form,
      nickname = vm.nickname, ty = vm.ty,
      nicknamed = vm.nicknamed, level = vm.level, shiny = vm.shiny, hp = vm.hp, mhp = vm.mhp,
      route = vm.slot or vm.own_route, where = vm.where, dead = vm.dead == true, cause = vm.cause,
      doa = vm.doa == true, deaths = eff_deaths(vm), gift = is_gift(vm), why = vm.why,
      excluded = vm.excluded == true, virtual = vm.virtual, counted = vm.slot ~= nil,
      group = (g and g.propagates) and g.route or nil, group_state = vm.group_state,
      group_number = (g and g.propagates) and g.number or nil,
    }
  end

  for i, pl in ipairs(players) do
    local w = pv[pl.id]
    local team, box, seen = {}, 0, {}
    local views = {}
    for _, id in ipairs(w.ids) do views[id] = mon_view(w.mons[id]) end
    local function add_team(id)
      local mv = views[id]
      if mv and mv.where == "team" and not seen[id] then seen[id] = true; team[#team + 1] = mv end
    end
    for _, id in ipairs(w.st.order) do add_team(id) end
    for _, id in ipairs(w.ids) do add_team(id) end
    local alive, dead = 0, 0
    for _, id in ipairs(w.ids) do
      local mv = views[id]
      if mv.where == "box" then box = box + 1 end
      if mv.dead then
        dead = dead + 1
        graveyard[#graveyard + 1] = {
          owner = pl.id, mon = id, species = mv.species, species_name = mv.species_name, form = mv.form,
          nickname = mv.nickname, level = mv.level,
          route = mv.route, group = mv.group, group_number = mv.group_number, cause = mv.cause,
          doa = mv.doa, deaths = mv.deaths, shiny = mv.shiny,
          seq = mv.cause == "own" and (death_seq[mkey(pl.id, id)] or {})[mv.deaths]
            or (mv.group and group_of[mv.group].died_seq) or nil,
          player_index = i,
        }
      elseif mv.where ~= "gone" then
        alive = alive + 1
      end
    end
    stats.alive = stats.alive + alive
    local place = w.st.place
    local place_view = { key = place.key, name = place.name, zone = place.zone, loc = place.loc,
                         manual = place.manual == true }
    local badges = w.st.badges or 0
    if badges > stats.badges_max then stats.badges_max = badges end
    out_players[i] = {
      id = pl.id, name = pl.name, color = pl.color, game_id = pl.game_id, own_variant = pl.own_variant, place = place_view,
      team = team, box_count = box, alive = alive, dead = dead, badges = badges,
      level_cap = cfg.rules.level_caps and oras.level_cap(badges) or nil, mons = views, ids = w.ids,
    }
  end
  stats.deaths = #graveyard
  table.sort(graveyard, function(a, b)
    local sa, sb = a.seq or INF, b.seq or INF
    if sa ~= sb then return sa < sb end
    if a.player_index ~= b.player_index then return a.player_index < b.player_index end
    return a.mon < b.mon
  end)
  for _, g in ipairs(groups) do
    if g.state == "dead" then stats.groups_dead = stats.groups_dead + 1 end
    if g.state == "linked" then stats.groups_linked = stats.groups_linked + 1 end
  end

  -- rows (route x player)
  local rows = {}
  for _, r in ipairs(route_keys) do
    local cells, done = {}, #players > 0
    for _, pl in ipairs(players) do
      local w = pv[pl.id]
      local st_, vm, e = cell_state(w, r)
      local cell = { state = st_ }
      if vm then
        local mv = out_players[pindex[pl.id]].mons[vm.id]
        cell.mon, cell.species, cell.nickname, cell.gift = vm.id, mv.species, mv.nickname, mv.gift
        cell.species_name = mv.species_name
        if mv.dead then cell.state, cell.cause = "dead", mv.cause end
      elseif e then
        cell.species = e.species
        cell.species_name = sname(e.species)
      end
      if st_ == "open" or st_ == "encounter" then done = false end
      cells[pl.id] = cell
    end
    local g = group_of[r]
    rows[#rows + 1] = { route = r, order = oras.order_index(r, order), cells = cells, group = g and {
      route = g.route, state = g.state, number = g.number, complete = g.complete, count = g.count,
    } or nil, done = done }
    if done then stats.routes_done = stats.routes_done + 1 end
  end
  -- starter + every area of the game + free places and legacy routes that have activity
  stats.routes_total = 1 + #areas
  local area_set = {}
  for _, lid in ipairs(areas) do area_set[oras.area_key(lid)] = true end
  for _, r in ipairs(route_keys) do
    if r:sub(1, 6) == "place:" or oras.route_number(r) or (oras.area_id(r) and not area_set[r]) then
      stats.routes_total = stats.routes_total + 1
    end
  end

  -- place status per player (location card)
  local row_of = {}
  for _, row in ipairs(rows) do row_of[row.route] = row end
  for i, pl in ipairs(players) do
    local p = out_players[i].place
    local status
    if not p.key then
      status = (p.zone ~= nil or p.name ~= nil) and "no_route" or "unknown"
    else
      status = row_of[p.key] and row_of[p.key].cells[pl.id].state or "open"
      if status == "dead" then status = "caught" end
    end
    p.status = status
  end

  -- group views for the UI (members carry what undo_death needs)
  local group_views = {}
  for _, g in ipairs(groups) do
    local members = {}
    for _, vm in ipairs(g.mons) do
      members[#members + 1] = { owner = vm.owner, id = vm.id, species = vm.species, species_name = sname(vm.species),
        nickname = vm.nickname, deaths = eff_deaths(vm), dead = vm.dead == true, cause = vm.cause,
        doa = vm.doa == true }
    end
    local gv = { route = g.route, state = g.state, number = g.number, complete = g.complete,
                 count = g.count, members = members, died_seq = g.died_seq, completed_seq = g.completed_seq }
    group_views[#group_views + 1] = gv
    if row_of[g.route] and row_of[g.route].group then row_of[g.route].group = gv end
  end
  table.sort(group_views, function(a, b)
    local na, nb = a.number or INF, b.number or INF
    if na ~= nb then return na < nb end
    return oras.compare(a.route, b.route, order)
  end)

  -- hints
  local r = cfg.rules
  for i, pl in ipairs(players) do
    local op = out_players[i]
    for _, id in ipairs(op.ids) do
      local mv = op.mons[id]
      local alive = not mv.dead and mv.where ~= "gone" and not mv.excluded and not mv.virtual
      if alive and r.nickname_required and mv.counted and not mv.gift
         and (mv.nickname == nil or mv.nickname == "" or mv.nicknamed == false) then
        hints[#hints + 1] = { code = "nickname_missing", user = pl.id, mon = id, route = mv.route, player_index = i }
      end
      if alive and r.level_caps and mv.where == "team" and op.level_cap and mv.level and mv.level > op.level_cap then
        hints[#hints + 1] = { code = "level_cap", user = pl.id, mon = id, level = mv.level,
                              cap = op.level_cap, player_index = i }
      end
      if alive and soul and r.only_linked_in_team and mv.where == "team" then
        local g = mv.group and group_of[mv.group]
        if not g or (g.state ~= "linked" and g.state ~= "open") then
          hints[#hints + 1] = { code = "unlinked_in_team", user = pl.id, mon = id, route = mv.route, player_index = i }
        elseif g.state == "linked" then
          for _, pm in ipairs(g.mons) do
            if pm.owner ~= pl.id and pm.where ~= "team" then
              hints[#hints + 1] = { code = "partner_not_in_team", user = pl.id, mon = id, route = mv.route,
                                    partner = pm.owner, partner_mon = pm.id, player_index = i }
            end
          end
        end
      end
    end
  end

  -- hints: same primary type inside a link group (rule pairs_differ_primary_type, never blocking)
  if soul and r.pairs_differ_primary_type then
    for _, g in ipairs(groups) do
      if g.propagates then
        local count = {}
        for _, vm in ipairs(g.mons) do if vm.ty ~= nil then count[vm.ty] = (count[vm.ty] or 0) + 1 end end
        for _, vm in ipairs(g.mons) do
          if vm.ty ~= nil and count[vm.ty] > 1 and not own_dead(vm) then
            hints[#hints + 1] = { code = "type_clash", user = vm.owner, mon = vm.id, route = g.route,
                                  player_index = pindex[vm.owner] }
          end
        end
      end
    end
  end

  return {
    names = names, areas = areas, places = places, order = order,
    mode = cfg.mode, rules = cfg.rules, players = out_players, rows = rows, groups = group_views,
    graveyard = graveyard, stats = stats, hints = hints, invalid_corrections = invalid,
    zones = V.merge_zones(run, states), randomizer = V.randomizer(run),
  }
end

return V

end
__mod["ui.board"] = function(...)
-- Run board (design 5gh): compact read-only tree for fb.run.setBoard.
local common = require("ui.common")

local M = {}

M.MAX_ROUTE_ROWS = 60
M.MAX_GRAVE_ROWS = 40

function M.build(ctx)
  local tr, view, run = ctx.tr, ctx.view, ctx.run
  local players = {}
  for i, p in ipairs(view.players) do
    players[#players + 1] = { id = "bp" .. i, title = p.name,
      sub = tr("board_player_sub", { place = common.place_label(p.place, tr, view), alive = p.alive, dead = p.dead, badges = p.badges })
        .. (p.own_variant and (" · " .. tr("rand_own_variant")) or ""),
      tone = nil }
  end
  local columns = { tr("col_route") }
  for _, p in ipairs(view.players) do columns[#columns + 1] = p.name end
  columns[#columns + 1] = tr("col_group")
  local rows = {}
  for _, r in ipairs(view.rows) do
    if #rows < M.MAX_ROUTE_ROWS then
      local cells = { common.route_label(ctx, r.route) }
      for _, p in ipairs(view.players) do cells[#cells + 1] = common.cell_text(r.cells[p.id], tr) end
      cells[#cells + 1] = (r.group and r.group.number) and tr("group_n", { n = r.group.number }) or common.group_state_text(r.group, tr)
      rows[#rows + 1] = { cells = cells }
    end
  end
  local grave = {}
  for i, g in ipairs(view.graveyard) do
    if i <= M.MAX_GRAVE_ROWS then
      grave[#grave + 1] = { id = "bg" .. i, title = "✕ " .. common.mon_name(g),
        sub = tr("grave_sub", { route = g.route and common.route_label(ctx, g.route) or "?", player = common.name_of(view, g.owner) }), tone = "neutral" }
    end
  end
  local kids = {
    { type = "row", id = "b-head", gap = 8, align = "center", children = {
      { type = "text", id = "b-name", text = run.name or "", style = "title" },
      { type = "badge", id = "b-mode", text = common.mode_text(view, tr), tone = "info" },
      { type = "stat", id = "b-deaths", label = tr("stat_deaths"), value = tostring(view.stats.deaths) },
      { type = "stat", id = "b-routes", label = tr("stat_routes"), value = view.stats.routes_done .. " / " .. view.stats.routes_total },
    } },
    { type = "section", id = "b-players", title = tr("board_players"), children = { { type = "list", id = "b-plist", rows = players } } },
  }
  local rand = common.randomizer_text(view, tr)
  if rand then table.insert(kids, 2, { type = "text", id = "b-randomizer", style = "meta", text = rand }) end
  if #rows > 0 then
    kids[#kids + 1] = { type = "section", id = "b-routes-s", title = tr("board_routes", { n = #view.rows }),
      children = { { type = "table", id = "b-routes-table", columns = columns, rows = rows } } }
  end
  if #grave > 0 then
    kids[#kids + 1] = { type = "section", id = "b-grave-s", title = tr("grave_title", { n = #view.graveyard }),
      children = { { type = "list", id = "b-grave", rows = grave } } }
  end
  return { type = "column", id = "board", gap = 12, children = kids }
end

return M

end
__mod["ui.common"] = function(...)
-- Shared helpers for the UI builders. Builders are pure: they take a context
--   ctx = { view, run, me, ui, tr, readonly, now, events }
-- and return fb.ui block trees. Only tones, sizes and player numbers are used, never colors.
local oras = require("data.oras")
local util = require("model.util")

local C = {}

--- Species name read from the game (stored in the run state), else "#<species id>".
function C.species_label(m)
  if m and type(m.species_name) == "string" and m.species_name ~= "" then return m.species_name end
  return "#" .. tostring(m and m.species or "?")
end

--- Display name of a mon: its nickname, else the species name.
function C.mon_name(m)
  if m and type(m.nickname) == "string" and m.nickname ~= "" then return m.nickname end
  return C.species_label(m)
end

--- Label of a route / area key: live name from the game (ctx.area_name), else the stored name,
--- else "Area <id>" / "Route <n>" / the typed text.
function C.route_label(ctx, key)
  local id = oras.area_id(key)
  if id and ctx.area_name then
    local nm = ctx.area_name(id)
    if nm then return nm end
  end
  return oras.label(key, ctx.tr, ctx.view and ctx.view.names)
end

--- Text cut to `n` characters (HUD and tile strip have small size limits).
function C.short(text, n)
  return util.clean_text(text, n) or ""
end

C.MAX_OPTIONS = 100

--- Value of the place select that stands for a player's current place: the route key, else the
--- location (a town has no route key but is still an option), else nil.
function C.place_value(place)
  if type(place) ~= "table" then return nil end
  if place.key then return place.key end
  if place.loc ~= nil then return oras.area_key(place.loc) end
  return nil
end

--- The view entry of player `id`, or nil.
function C.player(view, id)
  for _, p in ipairs(view and view.players or {}) do if p.id == id then return p end end
  return nil
end

C.GROUP_SIZE = 90

--- Places a position can be set for, as groups of at most GROUP_SIZE route options (a select holds at most
--- 100): every place of the game (towns and caves too, view.places), the encounter areas, places used in the
--- run, the players' current places and `selected`; no starter. With up to 100 places there is one group.
--- Otherwise the first group holds the selected key, the places used in the run and the current places, filled
--- up in game order; the others follow in game order. Each group is sorted in game order and carries
--- `first`/`last`, the ordinals of its places in that sequence ("Places 1-90").
--- Returns { { opts = { {value, label} }, first, last }, ... } (one empty group when nothing is known).
function C.place_groups(ctx, selected)
  local view = ctx.view
  local prio, rest, seen = {}, {}, {}
  local function add(list, key)
    if key and oras.is_route(key) and not seen[key] then seen[key] = true; list[#list + 1] = key end
  end
  local known = {}
  for _, id in ipairs(view.places or {}) do known[oras.area_key(id) or false] = true end
  for _, id in ipairs(view.areas or {}) do known[oras.area_key(id) or false] = true end
  for _, r in ipairs(view.rows or {}) do add(prio, r.route) end
  for _, p in ipairs(view.players or {}) do add(prio, C.place_value(p.place)) end
  -- the selected key only joins the first group when the game does not list it (groups stay stable)
  if selected and not known[selected] then add(prio, selected) end
  for _, id in ipairs(view.places or view.areas or {}) do add(rest, oras.area_key(id)) end
  for _, id in ipairs(view.areas or {}) do add(rest, oras.area_key(id)) end
  local function cmp(x, y) return oras.compare(x, y, view.order) end
  local seq = {}
  if #prio + #rest <= C.MAX_OPTIONS then
    for _, k in ipairs(prio) do seq[#seq + 1] = k end
    for _, k in ipairs(rest) do seq[#seq + 1] = k end
    table.sort(seq, cmp)
  else
    table.sort(prio, cmp)
    for _, k in ipairs(prio) do seq[#seq + 1] = k end
    for _, k in ipairs(rest) do seq[#seq + 1] = k end
  end
  local size = #seq <= C.MAX_OPTIONS and math.max(#seq, 1) or math.max(C.GROUP_SIZE, #prio + 1)
  local groups = {}
  for i = 1, math.max(#seq, 1), size do
    local keys = {}
    for j = i, math.min(i + size - 1, #seq) do keys[#keys + 1] = seq[j] end
    table.sort(keys, cmp)
    local opts = {}
    for _, k in ipairs(keys) do opts[#opts + 1] = { value = k, label = C.route_label(ctx, k) } end
    groups[#groups + 1] = { opts = opts, first = i, last = math.min(i + size - 1, #seq) }
  end
  return groups
end

--- Index of the group that holds `key`, else `want` (when valid), else 1.
function C.group_of(groups, key, want)
  for i, g in ipairs(groups) do
    for _, o in ipairs(g.opts) do if o.value == key then return i end end
  end
  return (want and groups[want]) and want or 1
end

--- Options of the active group (see place_groups); the plain list when everything fits one select.
function C.place_options(ctx, selected, want)
  local groups = C.place_groups(ctx, selected)
  return groups[C.group_of(groups, selected, want)].opts
end

--- Lines "key=value key=value ..." of a flat diagnostics table (pokemon-core diagnostics()): every key is
--- shown, grouped by the text before the first "_" (a key without "_" is its own group), one line per
--- group, groups and keys sorted, strings cut to 40 characters. Empty list for nil or an empty table.
function C.diag_lines(d)
  if type(d) ~= "table" then return {} end
  local keys = {}
  for k in pairs(d) do if type(k) == "string" then keys[#keys + 1] = k end end
  table.sort(keys)
  local order, groups = {}, {}
  for _, k in ipairs(keys) do
    local g = k:match("^([^_]*)_") or k
    if not groups[g] then groups[g] = {}; order[#order + 1] = g end
    local v = d[k]
    if type(v) == "string" then v = util.clean_text(v, 40) or "" end
    local list = groups[g]
    list[#list + 1] = k .. "=" .. tostring(v)
  end
  table.sort(order)
  local lines = {}
  for _, g in ipairs(order) do lines[#lines + 1] = table.concat(groups[g], " ") end
  return lines
end

--- The "Game data" block is closed until the player opens it with the chip (state kept in ui.diag_open).
function C.diag_open(ui) return ui ~= nil and ui.diag_open == true end

--- "Game data" block (diagnostics of the core, one wrapped line per key group and a hint), or nil without
--- diagnostics. `id` makes the block ids unique when it appears twice.
function C.diag_block(ctx, id)
  local lines = C.diag_lines(ctx.diag)
  if #lines == 0 then return nil end
  local kids = { { type = "text", id = id .. "-title", text = ctx.tr("diag_title"), style = "eyebrow" } }
  for i, l in ipairs(lines) do kids[#kids + 1] = { type = "text", id = id .. "-" .. i, text = l, style = "meta", wrap = true } end
  local ic = ctx.icheck
  if type(ic) == "table" and type(ic.items) == "table" and #ic.items > 0 then
    kids[#kids + 1] = { type = "text", id = id .. "-ic-title", text = ctx.tr("icheck_title"), style = "eyebrow" }
    local cols = {}
    for i, it in ipairs(ic.items) do
      cols[i] = { type = "column", id = id .. "-ic-" .. it.label, gap = 2, children = {
        { type = "image", id = id .. "-ic-img-" .. it.label, src = it.src, size = "m", state = "alive", label = it.label },
        { type = "text", id = id .. "-ic-lbl-" .. it.label, text = it.label, style = "title" },
        { type = "text", id = id .. "-ic-desc-" .. it.label, text = it.desc, style = "meta", wrap = true } } }
    end
    kids[#kids + 1] = { type = "row", id = id .. "-ic-row", gap = 8, children = cols }
    kids[#kids + 1] = { type = "text", id = id .. "-ic-hint", text = ctx.tr("icheck_hint"), style = "meta" }
  end
  kids[#kids + 1] = { type = "text", id = id .. "-hint", text = ctx.tr("diag_hint"), style = "meta" }
  return { type = "column", id = id, gap = 4, children = kids }
end

--- Options for a route select (at most 100): optional "no group" entry, the starter, then the places of
--- the game (view.places: encounter areas, towns, caves ... from the game, in game order), keys with
--- activity that are not game places (free places, legacy routes) and the selected key, in game order.
--- When there are too many, the selected key and the keys with activity are kept first and the
--- rest of the game's places fill the remaining room in game order.
function C.route_options(ctx, none_label, selected)
  local view = ctx.view
  local head, seen = {}, {}
  if none_label then head[#head + 1] = { value = "none", label = none_label }; seen.none = true end
  seen[oras.STARTER] = true
  head[#head + 1] = { value = oras.STARTER, label = C.route_label(ctx, oras.STARTER) }
  local first, rest = {}, {}
  local function add(list, key)
    if key and not seen[key] then
      seen[key] = true
      list[#list + 1] = key
    end
  end
  add(first, selected)
  for _, r in ipairs(view.rows) do add(first, r.route) end
  for _, id in ipairs(view.places or view.areas or {}) do add(rest, oras.area_key(id)) end
  local room = math.max(C.MAX_OPTIONS - #head, 0)
  local keys = {}
  for i = 1, math.min(#first, room) do keys[#keys + 1] = first[i] end
  for i = 1, math.min(#rest, math.max(room - #keys, 0)) do keys[#keys + 1] = rest[i] end
  table.sort(keys, function(a, b) return oras.compare(a, b, view.order) end)
  local out = {}
  for _, o in ipairs(head) do out[#out + 1] = o end
  for _, k in ipairs(keys) do out[#out + 1] = { value = k, label = C.route_label(ctx, k) } end
  return out
end

--- `cache:` src of the creature icon (pokemon-core icon, fetched lazily by the controller), or nil.
function C.icon(ctx, species, form)
  if type(ctx.icon) ~= "function" then return nil end
  return ctx.icon(species, form)
end

--- `image` block for a mon (alive or dead state), or nil while there is no icon.
function C.icon_block(ctx, id, m, owner, size)
  local src = C.icon(ctx, m.species, m.form)
  if not src then return nil end
  return { type = "image", id = id, src = src, size = size or "s", state = m.dead and "dead" or "alive",
           owner = owner, label = C.mon_name(m) }
end

--- Player number 1..8 (identity color): participant color 0..7 + 1, else the list position.
function C.color(p, i)
  if math.type(p.color) == "integer" and p.color >= 0 and p.color <= 7 then return p.color + 1 end
  return math.min(math.max(i or 1, 1), 8)
end

function C.initial(name)
  name = tostring(name or "?")
  local n = utf8.offset(name, 2) or (#name + 1)
  local s = name:sub(1, n - 1):upper()
  return s ~= "" and s or "?"
end

function C.index_of(view, id)
  for i, p in ipairs(view.players) do if p.id == id then return i, p end end
  return nil
end

function C.player(view, id)
  local _, p = C.index_of(view, id)
  return p
end

function C.name_of(view, id)
  local p = C.player(view, id)
  return p and p.name or tostring(id)
end

function C.groups(view)
  local map = {}
  for _, g in ipairs(view.groups) do map[g.route] = g end
  return map
end

function C.row_of(view, route)
  for _, r in ipairs(view.rows) do if r.route == route then return r end end
  return nil
end

--- Place text: name read from the game if the core reported it, else the route label.
--- `view` (optional) supplies the stored area names.
function C.place_label(place, tr, view)
  if place.name and place.name ~= "" then return place.name end
  if place.key then return oras.label(place.key, tr, view and view.names) end
  return tr("place_none")
end

local LOC_STATUS = { open = "open", encounter = "encounter", caught = "caught", missed = "missed" }
--- Status for the `location` block.
function C.loc_status(status) return LOC_STATUS[status] or "none" end

local TONE = { open = "neutral", encounter = "info", caught = "ok", missed = "neutral" }
function C.status_tone(status) return TONE[status] or "neutral" end

--- Short text of a cell of the routes matrix.
function C.cell_text(cell, tr)
  if cell.state == "open" then return tr("cell_open") end
  if cell.state == "encounter" then return tr("cell_encounter", { mon = C.species_label(cell) }) end
  if cell.state == "missed" then return tr("cell_missed") end
  local name = C.mon_name(cell)
  if cell.state == "dead" then return "✕ " .. name end
  return name
end

function C.group_state_text(g, tr)
  if not g then return tr("group_none") end
  return tr("group_state_" .. g.state)
end

--- Progress of HP as 0..1, or nil when unknown.
function C.hp_ratio(m)
  if type(m.hp) ~= "number" or type(m.mhp) ~= "number" or m.mhp <= 0 then return nil end
  return math.max(0, math.min(1, m.hp / m.mhp))
end

--- The own player entry of the view (or nil).
function C.me(ctx) return C.player(ctx.view, ctx.me) end

--- Whether writes are accepted: run starting/active and not the read-only run view.
function C.writable(run)
  return run and not run.view and (run.status == "starting" or run.status == "active") or false
end

function C.empty(tr, title_key, text_key)
  return { type = "empty", id = "empty", title = tr(title_key), text = tr(text_key) }
end

--- Default keys of the hotkeys the manifest declares (ui.hotkeys); the UI shows a hint only for these ids.
--- The key is a suggestion the player can change in Controllers, so hints say "default" in the docs only.
C.HOTKEYS = { ["toggle-hud"] = "Ctrl+H", ["doesnt-count"] = "Ctrl+D", ["open-run"] = "Ctrl+R" }

--- "YYYY-MM-DDTHH:MM..." (event time, UTC) as translated "MM-DD HH:MM UTC" text, or nil when unknown.
function C.when(tr, t)
  if type(t) ~= "string" then return nil end
  local y, mo, d, h, mi = t:match("^(%d%d%d%d)-(%d%d)-(%d%d)[T ](%d%d):(%d%d)")
  if not y then return nil end
  return tr("when_utc", { m = mo, d = d, time = h .. ":" .. mi })
end

--- Event of the context's event list by sequence number, or nil.
function C.event_by_seq(ctx, seq)
  if seq == nil then return nil end
  for _, ev in ipairs(ctx.events or {}) do if ev.seq == seq then return ev end end
  return nil
end

function C.mode_text(view, tr) return tr("mode_" .. view.mode) end

--- "Randomized · each person their own world · Nuzlocke friendly"; nil when the run has no randomizer.
function C.randomizer_text(view, tr)
  local r = view.randomizer
  if not r then return nil end
  local parts = { tr("rand_on"), tr("rand_mode_" .. r.mode) }
  if r.preset_label then parts[#parts + 1] = r.preset_label end
  return table.concat(parts, " · ")
end

--- Number of alive mons of all players that are not gone.
function C.alive_of(p) return p.alive end

--- Short list of the other players' names in the run.
function C.others_names(view, me)
  local names = {}
  for _, p in ipairs(view.players) do if p.id ~= me then names[#names + 1] = p.name end end
  return table.concat(names, ", ")
end

return C

end
__mod["ui.corrections"] = function(...)
-- Inline section for the manual corrections 5f-1 .. 5f-5 (+ mark dead, gift, revert).
-- The state of the open form is ctx.ui.corr = { kind, user, route?, mon?, group?, reason?, species?,
-- nickname?, level?, state?, gift?, target?, note?, error? }; fields change through the actions
-- "cf:<field>", "corr_submit" posts the event, "corr_cancel" closes the form.
local common = require("ui.common")
local corrections = require("model.corrections")

local M = {}

--- Build the corrections payload spec from the form; returns spec or nil, error key.
function M.to_spec(corr)
  local k = corr.kind
  local spec
  if k == "doesnt_count" then
    spec = corrections.doesnt_count({ user = corr.user, route = corr.route, mon = corr.mon, reason = corr.reason or "wrong" })
  elseif k == "undo_death" then
    spec = corrections.undo_death({ group = corr.group, reason = corr.note, undone = corr.undone })
  elseif k == "set_group" then
    spec = corrections.set_group({ user = corr.user, mon = corr.mon, group = corr.group })
  elseif k == "add" then
    spec = corrections.add({ user = corr.user, route = corr.route, species = corr.species, nickname = corr.nickname,
      level = corr.level, state = corr.state or "box" })
  elseif k == "mark_missed" then
    spec = corrections.mark_missed({ user = corr.user, route = corr.route })
  elseif k == "mark_dead" then
    spec = corrections.mark_dead({ user = corr.user, mon = corr.mon, reason = corr.note })
  elseif k == "set_gift" then
    spec = corrections.set_gift({ user = corr.user, mon = corr.mon, gift = corr.gift ~= false })
  elseif k == "revert" then
    spec = corrections.revert({ target = corr.target, reason = corr.note })
  else
    return nil, "c_err_invalid"
  end
  if not corrections.validate_spec(spec) then return nil, "c_err_invalid" end
  return spec
end

local function buttons(ctx, corr)
  local tr = ctx.tr
  local danger = corr.kind == "undo_death" or corr.kind == "mark_dead"
  local submit = {
    type = "button", id = "corr-submit", label = tr("c_submit_" .. corr.kind), action = "corr_submit",
    variant = danger and "danger" or "primary",
  }
  if danger or corr.kind == "mark_missed" or corr.kind == "revert" then
    submit.confirm = { title = tr("c_confirm_title_" .. corr.kind), text = tr("c_confirm_text_" .. corr.kind),
      confirm_label = tr("c_submit_" .. corr.kind), danger = danger }
  end
  -- board order (5f-1): the action first, then Cancel
  return { type = "row", id = "corr-buttons", gap = 8, children = {
    submit,
    { type = "button", id = "corr-cancel", label = tr("cancel"), action = "corr_cancel", variant = "secondary" },
  } }
end

--- A mon of the own player (the forms act on the own team and box), or nil.
local function own_mon(ctx, corr)
  local p = common.player(ctx.view, corr.user or ctx.me)
  return p and corr.mon and p.mons[corr.mon] or nil
end

--- "Logged as manual with your name; <others> see it and can undo it" (the rule of 5f: nobody's change is silent).
local function who_sees(ctx, others)
  local key = (others ~= "") and "c_who" or "c_who_alone"
  return { type = "text", id = "c-who", text = ctx.tr(key, { others = others }), style = "meta" }
end

--- Returns the section block, or nil when no form is open.
function M.section(ctx)
  local corr = ctx.ui.corr
  if not corr then return nil end
  local tr, view = ctx.tr, ctx.view
  local kids = {}
  local function add(b) kids[#kids + 1] = b end
  local k = corr.kind
  local route_label = corr.route and common.route_label(ctx, corr.route) or ""
  local others = common.others_names(view, ctx.me)

  local title = tr("c_title_" .. k)
  if k == "doesnt_count" then
    -- the creature line (icon, "Wild <species> · <route>") when the encounter is known
    local row = corr.route and common.row_of(view, corr.route)
    local cell = row and row.cells[corr.user or ctx.me]
    if cell and cell.species then
      local line = { type = "text", id = "c-mon", style = "meta",
        text = tr("c_dc_mon", { mon = common.species_label(cell), route = route_label }) }
      local icon = common.icon_block(ctx, "c-mon-i", { species = cell.species, species_name = cell.species_name }, nil, "s")
      add(icon and { type = "row", id = "c-mon-row", gap = 8, align = "center", children = { icon, line } } or line)
    end
    add({ type = "text", id = "c-text", text = tr("c_dc_text", { route = route_label, others = others }), style = "meta" })
    add({ type = "segmented", id = "c-reason", action = "cf:reason", selected = corr.reason or "wrong", options = {
      { value = "dupe", label = tr("reason_dupe") }, { value = "shiny", label = tr("reason_shiny") },
      { value = "wrong", label = tr("reason_wrong") } } })
  elseif k == "undo_death" then
    if corr.number then title = tr("c_title_undo_death_n", { n = corr.number }) end
    local icons = {}
    for i, m in ipairs(corr.members or {}) do
      local ic = common.icon_block(ctx, "c-mi" .. i, { species = m.species, species_name = m.species_name, form = m.form,
        nickname = m.nickname, dead = true }, nil, "s")
      if ic then icons[#icons + 1] = ic end
    end
    if #icons > 0 then add({ type = "row", id = "c-icons", gap = 4, children = icons }) end
    for i, m in ipairs(corr.members or {}) do
      add({ type = "text", id = "c-m" .. i, text = tr("c_undo_member", { player = common.name_of(view, m.owner),
        mon = common.mon_name(m) }), style = "body" })
    end
    add({ type = "text", id = "c-text", text = tr("c_undo_text", { n = corr.number or "?" }), style = "meta" })
    add({ type = "textfield", id = "c-note", action = "cf:note", text = corr.note or "", placeholder = tr("c_reason_placeholder") })
  elseif k == "set_group" then
    local m = own_mon(ctx, corr)
    local mon = m and common.mon_name(m) or "?"
    if m then
      local species = common.species_label(m)
      add({ type = "text", id = "c-mon", style = "heading",
        text = (mon ~= species) and tr("c_group_mon", { mon = mon, species = species }) or mon })
    end
    add({ type = "text", id = "c-text", text = tr("c_group_text", { mon = mon }), style = "meta" })
    local opts = common.route_options(ctx, tr("c_group_none"), corr.group)
    add({ type = "select", id = "c-group", action = "cf:group", options = opts, selected = corr.group or "none" })
    add(who_sees(ctx, others))
  elseif k == "add" then
    local row = corr.route and common.row_of(view, corr.route)
    local cell = row and row.cells[corr.user or ctx.me]
    add({ type = "text", id = "c-text", style = "meta",
      text = tr((cell and cell.state == "missed") and "c_add_text_missed" or "c_add_text", { route = route_label }) })
    local opts = common.route_options(ctx, nil, corr.route)
    add({ type = "select", id = "c-route", action = "cf:route", options = opts,
      selected = corr.route or (opts[1] and opts[1].value) })
    add({ type = "textfield", id = "c-species", action = "cf:species", text = corr.species and tostring(corr.species) or "",
      placeholder = tr("c_species_placeholder") })
    add({ type = "textfield", id = "c-nick", action = "cf:nickname", text = corr.nickname or "", placeholder = tr("c_nick_placeholder") })
    add({ type = "textfield", id = "c-level", action = "cf:level", text = corr.level and tostring(corr.level) or "",
      placeholder = tr("c_level_placeholder") })
    add({ type = "segmented", id = "c-state", action = "cf:state", selected = corr.state or "box", options = {
      { value = "box", label = tr("state_box") }, { value = "team", label = tr("state_team") },
      { value = "dead", label = tr("state_dead") } } })
    add(who_sees(ctx, others))
  elseif k == "mark_missed" then
    title = tr("c_title_mark_missed_route", { route = route_label })
    add({ type = "text", id = "c-text", text = tr("c_missed_text", { route = route_label, others = others }), style = "meta" })
    add(who_sees(ctx, others))
  elseif k == "mark_dead" then
    add({ type = "text", id = "c-text", text = tr("c_dead_text"), style = "meta" })
    add({ type = "textfield", id = "c-note", action = "cf:note", text = corr.note or "", placeholder = tr("c_reason_placeholder") })
    add(who_sees(ctx, others))
  elseif k == "set_gift" then
    add({ type = "toggle", id = "c-gift", action = "cf:gift", label = tr("c_gift_label"), checked = corr.gift ~= false })
    add(who_sees(ctx, others))
  elseif k == "revert" then
    add({ type = "text", id = "c-text", text = tr("c_revert_text", { seq = corr.target or "?" }), style = "meta" })
    add({ type = "textfield", id = "c-note", action = "cf:note", text = corr.note or "", placeholder = tr("c_reason_placeholder") })
  end
  if corr.error then
    add({ type = "text", id = "c-error", text = tr(corr.error), tone = "warning" })
  end
  add({ type = "text", id = "c-hint", text = tr("c_enter_hint"), style = "meta" })
  add(buttons(ctx, corr))
  return { type = "section", id = "corr", title = title, children = kids }
end

return M

end
__mod["ui.hud"] = function(...)
-- HUD widget (design 5b-2 / 5c): compact "SL · <place>" + status badge; expanded with the other players.
-- The host draws the plugin icon and the HUD frame, so there is no badge or frame of our own.
local common = require("ui.common")

local M = {}

function M.empty(tr)
  return { type = "text", id = "hud-empty", text = tr("hud_empty"), style = "meta" }
end

--- ctx.ui.hud_expanded / ctx.hud_death (text, set for ~3 s after a linked death).
function M.build(ctx)
  local tr, view = ctx.tr, ctx.view
  local me = common.me(ctx)
  if not me then return M.empty(tr) end
  local status = me.place.status
  local compact = { type = "row", id = "hud-row", gap = 8, align = "center", children = {
    { type = "text", id = "hud-place", style = "body",
      text = tr("hud_place", { place = common.short(common.place_label(me.place, tr, view), 24) }) },
    { type = "badge", id = "hud-status", text = tr("hud_status_" .. status), tone = common.status_tone(status) },
  } }
  local kids = { compact }
  if ctx.hud_death then
    kids[#kids + 1] = { type = "text", id = "hud-death", text = ctx.hud_death, style = "meta" }
  end
  if ctx.ui.hud_expanded or ctx.hud_death then
    local key = me.place.key
    local row = key and common.row_of(view, key)
    for i, p in ipairs(view.players) do
      if p.id ~= me.id then
        local cell = row and row.cells[p.id] or { state = "open" }
        kids[#kids + 1] = { type = "row", id = "hud-p" .. i, gap = 8, align = "center", children = {
          { type = "avatar", id = "hud-av" .. i, initial = common.initial(p.name), color = common.color(p, i), size = "s" },
          { type = "text", id = "hud-pt" .. i, text = tr("hud_other", { player = p.name, state = common.cell_text(cell, tr) }),
            style = "meta" },
        } }
      end
    end
  end
  return { type = "card", id = "hud", action = "hud_toggle", children = kids }
end

return M

end
__mod["ui.panel"] = function(...)
-- In-game panel (design 5b), built for about 300 px: run header, location card, encounter hint,
-- own team with link partners, graveyard (collapsed), footer. No tabs, no map, no stats, no filters:
-- everything else lives on the run screen (ui.screen, opened with fb.ui.open("screen")).
-- Pure builder: panel.build(ctx) -> block. ctx.can_open is false when the platform has no
-- fb.ui.open; the panel then says so instead of showing the buttons that open the screen.
local common = require("ui.common")
local corr_ui = require("ui.corrections")
local oras = require("data.oras")

local M = {}

M.MAX_PARTNERS = 2   -- partner icons per team row
M.MAX_GRAVE_ROWS = 10

function M.empty(tr)
  return { type = "column", gap = 12, children = {
    common.empty(tr, "empty_title", "empty_panel"),
  } }
end

local function header(ctx)
  local tr, run = ctx.tr, ctx.run
  local row = { { type = "text", id = "h-name", text = run.name or "", style = "heading" } }
  if ctx.can_open then
    row[#row + 1] = { type = "button", id = "h-open", label = tr("open_run_link"), action = "open_run", variant = "quiet" }
  end
  -- the host draws the "DRAWN BY SOULLINK" marker, so there is no eyebrow of our own
  local kids = {}
  if not common.writable(run) then
    kids[#kids + 1] = { type = "badge", id = "h-ro", text = tr("run_readonly_" .. tostring(run.status)), tone = "warning" }
  end
  if ctx.view and ctx.view.randomizer then
    row[#row + 1] = { type = "badge", id = "h-rand", text = ctx.tr("rand_chip"), tone = "info" }
  end
  if ctx.demo then
    row[#row + 1] = { type = "badge", id = "h-demo", text = ctx.tr("demo_chip"), tone = "warning" }
  end
  kids[#kids + 1] = { type = "row", id = "h-row", gap = 8, align = "center", children = row }
  return { type = "column", id = "header", gap = 4, children = kids }
end

local function others_on_place(ctx, me)
  local tr, view = ctx.tr, ctx.view
  local rows = {}
  local key = me.place.key
  if not key then return rows end
  local row = common.row_of(view, key)
  for i, p in ipairs(view.players) do
    if p.id ~= me.id and p.place.key == key then
      local cell = row and row.cells[p.id] or { state = "open" }
      rows[#rows + 1] = { type = "row", id = "o-" .. i, gap = 8, align = "center", children = {
        { type = "avatar", id = "o-av" .. i, initial = common.initial(p.name), color = common.color(p, i), size = "s" },
        { type = "text", id = "o-t" .. i, text = tr("other_on_place", { player = p.name, state = common.cell_text(cell, tr) }),
          style = "meta" },
      } }
    end
  end
  return rows
end

local function location(ctx, me)
  local tr = ctx.tr
  local status = me.place.status
  local sub_key = ({ open = "loc_open", encounter = "loc_encounter", caught = "loc_caught", missed = "loc_missed",
    no_route = "loc_no_route", unknown = "loc_unknown" })[status] or "loc_unknown"
  local row = me.place.key and common.row_of(ctx.view, me.place.key)
  local cell = row and row.cells[me.id]
  local sub
  if status == "caught" and cell then
    sub = common.cell_text(cell, tr)
  else
    sub = tr(sub_key)
  end
  local kids = others_on_place(ctx, me)
  return { type = "location", id = "loc", title = common.place_label(me.place, tr, ctx.view), sub = sub,
    status = common.loc_status(status), children = kids }
end

--- The core reports a zone (but no location) that no player has mapped to a place yet.
local function needs_zone(ctx, me)
  local z = me.place.zone
  return z ~= nil and me.place.loc == nil and me.place.key == nil and not me.place.manual and ctx.view.zones[z] == nil
end

local function picker_blocks(ctx, me)
  local tr = ctx.tr
  local selected = common.place_value(me.place)
  return {
    { type = "select", id = "place-select", options = common.route_options(ctx, nil, selected), selected = selected,
      action = "place_select" },
    { type = "textfield", id = "place-text", action = "place_text", placeholder = tr("place_other"), text = "" },
  }
end

--- Manual place: only when the core cannot report the location, collapsed behind "Set place".
--- Unmapped zone without a location id: the card that asks which place this is (fallback).
local function place_picker(ctx, me)
  local tr = ctx.tr
  if ctx.readonly then return nil end
  if needs_zone(ctx, me) then
    local kids = picker_blocks(ctx, me)
    kids[#kids + 1] = { type = "button", id = "zone-none", label = tr("zone_not_route"), action = "zone_none", variant = "quiet" }
    return { type = "card", id = "zone-new", title = tr("zone_new_title"), children = {
      { type = "text", id = "zone-new-text", text = tr("zone_new_text"), style = "meta" },
      { type = "column", id = "place-picker", gap = 4, children = kids } } }
  end
  if ctx.location_ok then return nil end
  local open = ctx.ui.place_open == true
  local kids = { { type = "button", id = "place-toggle", label = tr(open and "place_hide" or "place_set"),
    action = "place_toggle", variant = "quiet" } }
  if open then
    kids[#kids + 1] = { type = "column", id = "place-picker", gap = 4, children = picker_blocks(ctx, me) }
  end
  return { type = "column", id = "place-set", gap = 4, children = kids }
end

local function encounter_hint(ctx, me)
  local tr = ctx.tr
  if me.place.status ~= "encounter" or ctx.readonly then return nil end
  local row = common.row_of(ctx.view, me.place.key)
  local cell = row and row.cells[me.id] or {}
  local text = { type = "column", id = "enc-col", gap = 0, children = {
    { type = "text", id = "enc-text", text = tr("enc_text", { mon = common.species_label(cell) }), style = "body" },
    { type = "text", id = "enc-meta", text = tr("enc_meta"), style = "meta" },
  } }
  local icon = cell.species and common.icon_block(ctx, "enc-i", { species = cell.species, species_name = cell.species_name }, nil, "s")
  local head = text
  if icon then head = { type = "row", id = "enc-row", gap = 8, align = "center", children = { icon, text } } end
  local act = { { type = "button", id = "enc-no", label = tr("doesnt_count"), action = "dc_open", variant = "quiet" } }
  local key = common.HOTKEYS["doesnt-count"]
  if key then act[#act + 1] = { type = "text", id = "enc-key", text = key, style = "meta" } end
  return { type = "card", id = "enc", eyebrow = tr("enc_eyebrow"), children = {
    head,
    { type = "row", id = "enc-acts", gap = 8, align = "center", children = act },
  } }
end

local function partners(ctx, me, i, m, groups)
  local g = m.group and groups[m.group]
  if not g or g.count <= 1 then return nil end
  local kids, shown, more = {}, 0, 0
  for j, pm in ipairs(g.members) do
    if pm.owner ~= me.id then
      if shown < M.MAX_PARTNERS then
        shown = shown + 1
        local idx, pl = common.index_of(ctx.view, pm.owner)
        local color = common.color(pl or {}, idx)
        local icon = common.icon_block(ctx, "m-p" .. i .. "-" .. j, pm, color, "s")
        kids[#kids + 1] = icon or { type = "avatar", id = "m-p" .. i .. "-" .. j,
          initial = common.initial(pl and pl.name), color = color, size = "s" }
      else
        more = more + 1
      end
    end
  end
  if more > 0 then
    kids[#kids + 1] = { type = "text", id = "m-pm" .. i, text = "+" .. more, style = "meta" }
  end
  local row = { type = "row", id = "m-pr" .. i, gap = 4, align = "center", children = kids }
  return { type = "column", id = "m-pc" .. i, gap = 2, children = {
    { type = "text", id = "m-pl" .. i, text = ctx.tr("linked_with"), style = "eyebrow" }, row } }
end

local function team(ctx, me)
  local tr = ctx.tr
  local groups = common.groups(ctx.view)
  local owner = common.color(me, common.index_of(ctx.view, me.id))
  local kids = {}
  for i, m in ipairs(me.team) do
    local title = (m.dead and "✕ " or "") .. common.mon_name(m) .. (m.level and (" · " .. tr("level_short", { n = m.level })) or "")
    local texts = { { type = "text", id = "m-t" .. i, text = title, style = "body", tone = m.dead and "neutral" or nil } }
    local has_nick = type(m.nickname) == "string" and m.nickname ~= ""
    if has_nick then
      texts[#texts + 1] = { type = "text", id = "m-s" .. i, text = common.species_label(m), style = "meta" }
    end
    local head = { type = "column", id = "m-c" .. i, gap = 0, children = texts }
    local icon = common.icon_block(ctx, "m-i" .. i, m, owner, "s")
    if icon then head = { type = "row", id = "m-h" .. i, gap = 8, align = "center", children = { icon, head } } end
    local c = { head }
    local ratio = (not m.dead) and common.hp_ratio(m)
    if ratio then
      c[#c + 1] = { type = "bar", id = "m-hp" .. i, value = ratio, label = tr("hp_label", { hp = m.hp, max = m.mhp }) }
    end
    local pr = partners(ctx, me, i, m, groups)
    if pr then c[#c + 1] = pr end
    kids[#kids + 1] = { type = "column", id = "mon" .. i, gap = 4, children = c }
  end
  if #kids == 0 then kids[1] = { type = "text", id = "team-empty", text = tr("team_empty"), style = "meta" } end
  return { type = "section", id = "team", title = tr("team_title", { n = #me.team }), children = kids }
end

local function graveyard(ctx)
  local tr, view = ctx.tr, ctx.view
  local open = ctx.ui.grave_open
  local kids = { { type = "chip", id = "grave-chip", text = tr(open and "grave_hide" or "grave_show"),
    action = "grave_toggle", selected = open and true or false } }
  if open then
    local rows = {}
    for i, g in ipairs(view.graveyard) do
      if i > M.MAX_GRAVE_ROWS then break end
      rows[i] = { id = "g" .. i, title = "✕ " .. common.mon_name(g), image = common.icon(ctx, g.species, g.form),
        sub = tr("grave_sub", { route = g.route and common.route_label(ctx, g.route) or "?", player = common.name_of(view, g.owner) }),
        tone = "neutral" }
    end
    if #rows > 0 then kids[#kids + 1] = { type = "list", id = "grave-list", rows = rows } end
  end
  return { type = "column", id = "grave", gap = 4, children = kids }
end

local function footer(ctx, me)
  local tr = ctx.tr
  -- "Graveyard 3 · Badges 4 / 8 · next cap Lv 24": the badge total is the game's (8 for the supported games)
  local text = tr("panel_footer", { grave = #ctx.view.graveyard, n = me.badges, total = oras.BADGES })
  if me.level_cap then text = text .. " · " .. tr("next_cap_short", { n = me.level_cap }) end
  local kids = { { type = "text", id = "badges", text = text, style = "meta" } }
  if ctx.badges_manual and not ctx.readonly then
    local opts = {}
    for n = 0, 8 do opts[#opts + 1] = { value = n, label = tostring(n) } end
    kids[#kids + 1] = { type = "select", id = "badges-select", options = opts, selected = me.badges, action = "badges_select" }
  end
  if not ctx.can_open then
    kids[#kids + 1] = { type = "text", id = "f-update", text = tr("update_to_open"), style = "meta" }
  end
  return { type = "column", id = "footer", gap = 8, children = kids }
end

--- ctx.view / ctx.run required.
function M.build(ctx)
  local me = common.me(ctx)
  if not me then
    return { type = "column", gap = 12, children = { header(ctx), common.empty(ctx.tr, "no_player_title", "no_player_text") } }
  end
  local kids = { header(ctx), location(ctx, me) }
  local picker = place_picker(ctx, me)
  if picker then kids[#kids + 1] = picker end
  local hint = encounter_hint(ctx, me)
  if hint then kids[#kids + 1] = hint end
  -- the "Doesn't count" form (5f-1) is opened from here; every other correction lives on the run screen
  if ctx.ui.corr and ctx.ui.corr.kind == "doesnt_count" then
    local corr = corr_ui.section(ctx)
    if corr then kids[#kids + 1] = corr end
  end
  kids[#kids + 1] = team(ctx, me)
  kids[#kids + 1] = graveyard(ctx)
  kids[#kids + 1] = footer(ctx, me)
  return { type = "column", id = "panel", gap = 12, children = kids }
end

return M

end
__mod["ui.screen"] = function(...)
-- Run screen (design 5e), shown in the `screen` slot (and, read only, in the `run` slot of the Runs page):
-- frame with tabs Map | Routes | Team & box | Graveyard | Event log. All manual corrections (5f) live here.
-- The Map tab shows the stored map (app.maps: taken from the game picture or chosen among the images of the
-- game files); until then the Routes tab comes first and the Map tab offers both sources.
local common = require("ui.common")
local corr_ui = require("ui.corrections")
local oras = require("data.oras")

local M = {}

M.LOG_LIMIT = 100

function M.empty(tr)
  return { type = "column", gap = 12, children = { common.empty(tr, "empty_title", "empty_screen") } }
end

--- The Map tab exists with an image, and in a live run (to take the map); not in the shell run view without one.
function M.has_map(ctx) return ctx ~= nil and ctx.map ~= nil and (ctx.map.state == "ready" or ctx.map.live == true) end

local RULE_ORDER = { "first_encounter_only", "dupes_clause", "shiny_clause", "hordes_count",
  "pairs_differ_primary_type", "only_linked_in_team", "nickname_required", "level_caps" }

local function rules_on(view)
  local n = 0
  for _, k in ipairs(RULE_ORDER) do if view.rules[k] then n = n + 1 end end
  return n
end

local function rules_list(ctx)
  local tr, view = ctx.tr, ctx.view
  local rows = { { id = "ru-mode", title = tr("rs_mode"), sub = common.mode_text(view, tr) } }
  for _, k in ipairs(RULE_ORDER) do
    rows[#rows + 1] = { id = "ru-" .. k, title = tr("rs_" .. k), sub = tr(view.rules[k] and "rule_on" or "rule_off") }
  end
  return { type = "list", id = "rules-list", rows = rows }
end

--- One eyebrow line "Deaths 7 · Routes 9 / 31 · Badges 4" (5e); the host run page already names the run, and
--- the host draws the "Drawn by SoulLink" marker. A read-only run says so with a badge.
local function header(ctx)
  local tr, view, run = ctx.tr, ctx.view, ctx.run
  local s = view.stats
  local kids = { { type = "text", id = "head-summary", style = "eyebrow",
    text = tr("run_summary", { deaths = s.deaths, done = s.routes_done, total = s.routes_total, badges = s.badges_max }) } }
  local rand = common.randomizer_text(view, tr)
  if rand then kids[#kids + 1] = { type = "text", id = "head-randomizer", style = "meta", text = rand } end
  if not common.writable(run) then
    kids[#kids + 1] = { type = "badge", id = "head-status", text = tr("run_status_" .. tostring(run.status)) .. " · " .. common.mode_text(view, tr),
      tone = "warning" }
  end
  return { type = "column", id = "head", gap = 8, children = kids }
end

--- Rules summary and "Game data" (diagnostics), below the tabs: out of the main flow, still one chip away.
--- Game data stays closed until the player opens it with its chip.
local function settings_foot(ctx)
  local tr, view = ctx.tr, ctx.view
  local rules_open = ctx.ui.rules_open == true
  local kids = {
    { type = "row", id = "head-rules", gap = 8, align = "center", children = {
      { type = "text", id = "rules-summary", style = "meta",
        text = tr("rules_summary", { n = rules_on(view), total = #RULE_ORDER }) },
      { type = "chip", id = "rules-chip", text = tr(rules_open and "rules_hide" or "rules_show"),
        action = "rules_toggle", selected = rules_open },
    } },
  }
  if rules_open then kids[#kids + 1] = { type = "scroll", id = "rules-scroll", max_height = "s", children = { rules_list(ctx) } } end
  if ctx.diag ~= nil then
    local open = common.diag_open(ctx.ui)
    kids[#kids + 1] = { type = "row", id = "head-diag", gap = 8, align = "center", children = {
      { type = "chip", id = "diag-chip", text = tr(open and "diag_hide" or "diag_show"), action = "diag_toggle", selected = open } } }
    local blk = open and common.diag_block(ctx, "diag")
    if blk then kids[#kids + 1] = blk end
  end
  return { type = "column", id = "foot", gap = 8, children = kids }
end

local function find_mine(ctx, route)
  local me = common.me(ctx)
  if not me then return nil end
  for _, id in ipairs(me.ids) do
    local m = me.mons[id]
    if m.route == route and m.counted then return m end
  end
  return nil
end

local function route_detail(ctx)
  local tr, view = ctx.tr, ctx.view
  local route = ctx.ui.selected_route
  local row = route and common.row_of(view, route)
  if not row then return nil end
  local g = row.group
  local kids = { { type = "text", id = "rd-status", text = common.group_state_text(g, tr) .. (g and g.number and (" · " .. tr("group_n", { n = g.number })) or ""),
    style = "meta" } }
  local icons = {}
  for i, p in ipairs(view.players) do
    local cell = row.cells[p.id]
    local ic = cell and cell.species and common.icon_block(ctx, "rd-i" .. i, { species = cell.species, nickname = cell.nickname,
      dead = cell.state == "dead" }, common.color(p, i), "m")
    if ic then icons[#icons + 1] = ic end
  end
  if #icons > 0 then kids[#kids + 1] = { type = "row", id = "rd-icons", gap = 8, children = icons } end
  if not ctx.readonly then
    local acts = {
      { type = "button", id = "rd-missed", label = tr("mark_missed"), action = "missed_open", value = route, variant = "quiet" },
      { type = "button", id = "rd-dc", label = tr("doesnt_count"), action = "dc_open", value = route, variant = "quiet" },
    }
    if g and g.state == "dead" then
      acts[#acts + 1] = { type = "button", id = "rd-undo", label = tr("undo_death"), action = "undo_open", value = route, variant = "quiet" }
    end
    local mine = find_mine(ctx, route)
    if mine then
      acts[#acts + 1] = { type = "button", id = "rd-group", label = tr("change_group"), action = "group_open", value = mine.id, variant = "quiet" }
    end
    kids[#kids + 1] = { type = "row", id = "rd-acts", gap = 8, children = acts }
  end
  return { type = "section", id = "route-detail", title = common.route_label(ctx, route), children = kids }
end

local function routes_page(ctx)
  local tr, view = ctx.tr, ctx.view
  local filter = ctx.ui.routes_filter or "all"
  local n_open, n_done = 0, 0
  for _, r in ipairs(view.rows) do if r.done then n_done = n_done + 1 else n_open = n_open + 1 end end
  local columns = { tr("col_route") }
  for _, p in ipairs(view.players) do columns[#columns + 1] = p.name end
  columns[#columns + 1] = tr("col_group")
  columns[#columns + 1] = tr("col_status")
  local rows = {}
  for _, r in ipairs(view.rows) do
    if filter == "all" or (filter == "open" and not r.done) or (filter == "done" and r.done) then
      local cells = { common.route_label(ctx, r.route) }
      for _, p in ipairs(view.players) do cells[#cells + 1] = common.cell_text(r.cells[p.id], tr) end
      cells[#cells + 1] = (r.group and r.group.number) and tr("group_n", { n = r.group.number }) or "—"
      cells[#cells + 1] = common.group_state_text(r.group, tr)
      rows[#rows + 1] = { cells = cells, action = "route_select", value = r.route }
    end
  end
  local kids = {
    { type = "row", id = "rf", gap = 8, align = "center", children = {
      { type = "chip", id = "rf-all", text = tr("filter_all", { n = #view.rows }), action = "rf:all", selected = filter == "all" },
      { type = "chip", id = "rf-open", text = tr("filter_open", { n = n_open }), action = "rf:open", selected = filter == "open" },
      { type = "chip", id = "rf-done", text = tr("filter_done", { n = n_done }), action = "rf:done", selected = filter == "done" },
    } },
  }
  if not ctx.readonly then
    kids[#kids + 1] = { type = "button", id = "add-open", label = tr("add_by_hand"), action = "add_open", variant = "secondary" }
  end
  if #rows > 0 then
    kids[#kids + 1] = { type = "table", id = "routes-table", columns = columns, rows = rows }
  else
    kids[#kids + 1] = { type = "text", id = "routes-empty", text = tr("routes_empty"), style = "meta" }
  end
  if #(view.places or {}) == 0 and not common.diag_open(ctx.ui) then
    local blk = common.diag_block(ctx, "routes-diag")
    if blk then kids[#kids + 1] = blk end
  end
  local d = route_detail(ctx)
  if d then kids[#kids + 1] = d end
  return { type = "column", id = "page-routes", gap = 12, children = kids }
end

--- One team slot: creature image (when its icon is known), "nickname · Lv n", HP bar and, for the own team,
--- the correction buttons.
local function team_cell(ctx, p, i, j, m)
  local tr = ctx.tr
  local c = {}
  local icon = common.icon_block(ctx, "tm-i" .. i .. "-" .. j, m, common.color(p, i), "m")
  if icon then c[#c + 1] = icon end
  local title = (m.dead and "✕ " or "") .. common.mon_name(m) .. (m.level and (" · " .. tr("level_short", { n = m.level })) or "")
  c[#c + 1] = { type = "text", id = "tm" .. i .. "-" .. j, text = title, style = "body" }
  local ratio = (not m.dead) and common.hp_ratio(m)
  if ratio then c[#c + 1] = { type = "bar", id = "tm-hp" .. i .. "-" .. j, value = ratio, label = tr("hp_label", { hp = m.hp, max = m.mhp }) } end
  if p.id == ctx.me and not ctx.readonly then
    c[#c + 1] = { type = "column", id = "tm-a" .. j, gap = 4, align = "start", children = {
      { type = "button", id = "tm-g" .. j, label = tr("change_group"), action = "group_open", value = m.id, variant = "quiet" },
      { type = "button", id = "tm-gift" .. j, label = tr("mark_gift"), action = "gift_open", value = m.id, variant = "quiet" },
      (not m.dead) and { type = "button", id = "tm-d" .. j, label = tr("mark_dead"), action = "dead_open", value = m.id, variant = "quiet" } or nil,
    } }
  end
  return { type = "column", id = "tmc" .. i .. "-" .. j, gap = 4, children = c }
end

--- Box: a row of small images with the count in the eyebrow; a list with names while an icon is missing.
local function box_block(ctx, p, i)
  local tr = ctx.tr
  local mons = {}
  for _, id in ipairs(p.ids) do
    local m = p.mons[id]
    if m.where == "box" then mons[#mons + 1] = m end
  end
  local kids = { { type = "text", id = "box-count" .. i, text = tr("box_count", { n = p.box_count }), style = "eyebrow" } }
  local icons, all = {}, true
  for k, m in ipairs(mons) do
    local ic = common.icon_block(ctx, "box-i" .. i .. "-" .. k, m, common.color(p, i), "s")
    if ic then icons[#icons + 1] = ic else all = false end
  end
  if #mons > 0 and all then
    kids[#kids + 1] = { type = "grid", id = "box-grid" .. i, columns = 6, gap = 8, children = icons }
  elseif #mons > 0 then
    local rows = {}
    for _, m in ipairs(mons) do
      rows[#rows + 1] = { id = "b" .. m.id, title = (m.dead and "✕ " or "") .. common.mon_name(m), image = common.icon(ctx, m.species, m.form),
        sub = m.route and common.route_label(ctx, m.route) or nil, tone = m.dead and "neutral" or nil }
    end
    kids[#kids + 1] = { type = "list", id = "box-list" .. i, rows = rows }
  end
  return kids
end

--- Per person: avatar, name and current route, then TEAM (grid of slots) and BOX (5e-3).
local function team_page(ctx)
  local tr, view = ctx.tr, ctx.view
  local secs = {}
  for i, p in ipairs(view.players) do
    local who = {
      { type = "text", id = "pl-name" .. i, text = p.name, style = "heading" },
      { type = "text", id = "pl-place" .. i, text = common.place_label(p.place, tr, view), style = "eyebrow" } }
    if p.own_variant then who[#who + 1] = { type = "text", id = "pl-variant" .. i, text = tr("rand_own_variant"), style = "meta" } end
    local kids = {
      { type = "row", id = "pl-head" .. i, gap = 8, align = "center", children = {
        { type = "avatar", id = "pl-av" .. i, initial = common.initial(p.name), color = common.color(p, i), size = "m" },
        { type = "column", id = "pl-who" .. i, gap = 0, children = who },
      } },
      { type = "text", id = "team-label" .. i, text = tr("team_label"), style = "eyebrow" },
    }
    local cells = {}
    for j, m in ipairs(p.team) do cells[#cells + 1] = team_cell(ctx, p, i, j, m) end
    if #cells == 0 then
      kids[#kids + 1] = { type = "text", id = "tm-empty" .. i, text = tr("team_empty"), style = "meta" }
    else
      local own = p.id == ctx.me and not ctx.readonly
      kids[#kids + 1] = { type = "grid", id = "team-grid" .. i, columns = own and 3 or 6, gap = 12, children = cells }
    end
    for _, b in ipairs(box_block(ctx, p, i)) do kids[#kids + 1] = b end
    secs[#secs + 1] = { type = "column", id = "pl" .. i, gap = 8, children = kids }
  end
  return { type = "column", id = "page-team", gap = 20, children = secs }
end

--- Deaths of one link group sit together (they share the time), other deaths stand alone. Every cluster is a
--- list of rows: image, "nickname", "species · Lv · owner · route · cause", time; "Undo…" for a link group.
local function grave_clusters(view)
  local clusters, by_group = {}, {}
  for _, g in ipairs(view.graveyard) do
    local c = g.group and by_group[g.group]
    if not c then
      c = { group = g.group, number = g.group_number, items = {} }
      clusters[#clusters + 1] = c
      if g.group then by_group[g.group] = c end
    end
    c.items[#c.items + 1] = g
  end
  return clusters
end

local function graveyard_page(ctx)
  local tr, view = ctx.tr, ctx.view
  if #view.graveyard == 0 then
    return { type = "column", id = "page-grave", gap = 12, children = { { type = "text", id = "grave-empty", text = tr("grave_empty"), style = "meta" } } }
  end
  local kids = {}
  local n = 0
  for ci, c in ipairs(grave_clusters(view)) do
    local rows, when = {}, nil
    for _, g in ipairs(c.items) do
      n = n + 1
      local ev = common.event_by_seq(ctx, g.seq)
      local at = ev and common.when(tr, ev.time)
      when = when or at
      local cause = g.doa and tr("cause_doa") or tr("cause_" .. tostring(g.cause))
      local mon = { common.species_label(g) .. (g.level and (" · " .. tr("level_short", { n = g.level })) or ""),
        common.name_of(view, g.owner), g.route and common.route_label(ctx, g.route) or "—", cause }
      rows[#rows + 1] = { id = "g" .. n, title = "✕ " .. common.mon_name(g), sub = table.concat(mon, " · "), meta = at,
        image = common.icon(ctx, g.species, g.form), tone = "neutral",
        action = g.group and "undo_open" or nil, value = g.group }
    end
    local head = {}
    if c.group and (c.number or #c.items > 1) then
      head[#head + 1] = { type = "text", id = "grave-h" .. ci, style = "eyebrow",
        text = c.number and tr("grave_group", { n = c.number, count = #c.items }) or tr("grave_group_nonum", { count = #c.items }) }
    end
    if c.group and not ctx.readonly then
      head[#head + 1] = { type = "button", id = "grave-undo" .. ci, label = tr("undo_ellipsis"), action = "undo_open",
        value = c.group, variant = "quiet" }
    end
    local col = {}
    if #head > 0 then col[#col + 1] = { type = "row", id = "grave-hr" .. ci, gap = 8, align = "center", children = head } end
    col[#col + 1] = { type = "list", id = "grave-list" .. (ci == 1 and "" or ci), rows = rows }
    kids[#kids + 1] = { type = "column", id = "grave-c" .. ci, gap = 4, children = col }
  end
  kids[#kids + 1] = { type = "text", id = "grave-hint", text = tr("grave_hint"), style = "meta" }
  return { type = "column", id = "page-grave", gap = 12, children = kids }
end

local function event_text(ctx, ev)
  -- automatic events are worded again from their ids, so names that were not known when the event
  -- was posted ("#265") show once the game text is available
  local live = ctx.event_text and ctx.event_text(ev)
  if live then return live end
  if type(ev.text) == "string" and ev.text ~= "" then return ev.text end
  return ctx.tr("log_type_" .. tostring(ev.type):gsub("[^%w]", "_"))
end

local function log_page(ctx)
  local tr, view = ctx.tr, ctx.view
  local filter = ctx.ui.log_filter or "all"
  local person = ctx.ui.log_person
  if person ~= nil and not common.player(view, person) then person = nil end
  local rows, manual = {}, 0
  local evs = ctx.events or {}
  for i = #evs, 1, -1 do
    local ev = evs[i]
    if ev.source ~= "hub" then
      if ev.source == "manual" then manual = manual + 1 end
      if (filter == "all" or ev.source == filter) and (person == nil or ev.user_id == person) and #rows < M.LOG_LIMIT then
        rows[#rows + 1] = {
          id = "e" .. ev.seq, title = event_text(ctx, ev),
          sub = tr("log_sub", { player = common.name_of(view, ev.user_id), source = tr("source_" .. tostring(ev.source)) }),
          meta = common.when(tr, ev.time) or ("#" .. ev.seq), tone = ev.source == "manual" and "warning" or nil,
          action = (ev.type == "soullink.correction" and not ctx.readonly) and "revert_open" or nil,
          value = ev.seq,
        }
      end
    end
  end
  local bar = {
    { type = "chip", id = "lf-all", text = tr("log_all"), action = "lf:all", selected = filter == "all" },
    { type = "chip", id = "lf-auto", text = tr("log_automatic"), action = "lf:automatic", selected = filter == "automatic" },
    { type = "chip", id = "lf-manual", text = tr("log_manual", { n = manual }), action = "lf:manual", selected = filter == "manual" },
  }
  if #view.players > 1 then
    local opts = { { value = "all", label = tr("log_everyone") } }
    for _, p in ipairs(view.players) do opts[#opts + 1] = { value = p.id, label = p.name } end
    bar[#bar + 1] = { type = "select", id = "lf-person", options = opts, selected = person or "all", action = "log_person" }
  end
  local kids = { { type = "row", id = "lf", gap = 8, align = "center", children = bar } }
  if #rows > 0 then kids[#kids + 1] = { type = "list", id = "log-list", rows = rows }
  else kids[#kids + 1] = { type = "text", id = "log-empty", text = tr("log_empty"), style = "meta" } end
  return { type = "column", id = "page-log", gap = 12, children = kids }
end

local STEPS = { 2, 10, 40 }

local function calibration(ctx, m)
  local tr, c = ctx.tr, ctx.ui.calib
  local groups = common.place_groups(ctx, c.route)
  local gi = common.group_of(groups, c.route, c.group)
  local opts = groups[gi].opts
  local steps = {}
  for _, n in ipairs(STEPS) do steps[#steps + 1] = { value = n, label = tr("calib_px", { n = n }) } end
  local kids = {
    { type = "text", id = "calib-hint", text = tr("calib_hint"), style = "meta" },
    { type = "select", id = "calib-route", options = #opts > 0 and opts or { { value = "", label = tr("calib_no_places") } },
      selected = c.route or "", action = "calib_route" },
    { type = "segmented", id = "calib-step", options = steps, selected = c.step or 10, action = "calib_step" },
  }
  if #groups > 1 then
    local gopts = {}
    for i, g in ipairs(groups) do gopts[i] = { value = i, label = tr("calib_group", { a = g.first, b = g.last }) } end
    table.insert(kids, 2, { type = (#groups <= 3) and "segmented" or "select", id = "calib-group", options = gopts,
      selected = gi, action = "calib_group" })
  end
  if c.x then
    kids[#kids + 1] = { type = "text", id = "calib-pos", text = tr("calib_pos", { x = c.x, y = c.y }), style = "meta" }
    kids[#kids + 1] = { type = "row", id = "calib-arrows", gap = 8, children = {
      { type = "button", id = "calib-l", label = "←", action = "calib_move", value = "l", variant = "secondary" },
      { type = "button", id = "calib-u", label = "↑", action = "calib_move", value = "u", variant = "secondary" },
      { type = "button", id = "calib-r", label = "→", action = "calib_move", value = "r", variant = "secondary" },
      { type = "button", id = "calib-d", label = "↓", action = "calib_move", value = "d", variant = "secondary" },
    } }
    kids[#kids + 1] = { type = "button", id = "calib-set", label = tr("calib_set"), action = "calib_set", variant = "primary" }
  end
  if c.msg then kids[#kids + 1] = { type = "text", id = "calib-msg", text = tr("calib_msg_" .. c.msg), style = "meta" } end
  kids[#kids + 1] = { type = "row", id = "calib-acts", gap = 8, children = {
    { type = "button", id = "calib-export", label = tr("calib_export"), action = "calib_export", variant = "secondary" },
    { type = "button", id = "calib-done", label = tr("calib_done"), action = "calib_toggle", variant = "quiet" },
  } }
  return { type = "section", id = "calib", title = tr("calib_title"), children = kids }
end

local SIDE_KEYS = { t = "crop_top", b = "crop_bottom", l = "crop_left", r = "crop_right" }

--- Crop of the map: per side the percent of the captured screen that is cut off (-5 -1 +1 +5), presets, and
--- the button that takes the map again with this crop (the stored picture is cropped at the capture).
local function crop_section(ctx, m)
  local tr = ctx.tr
  local e = m.edit or { t = 0, b = 0, l = 0, r = 0 }
  local kids = { { type = "text", id = "crop-hint", text = tr("crop_hint"), style = "meta" } }
  for _, side in ipairs({ "t", "b", "l", "r" }) do
    local btns = { { type = "text", id = "crop-v" .. side, text = tr(SIDE_KEYS[side], { n = e[side] }), style = "body" } }
    for _, d in ipairs({ -5, -1, 1, 5 }) do
      btns[#btns + 1] = { type = "button", id = "crop-" .. side .. (d < 0 and "m" or "p") .. math.abs(d),
        label = (d > 0 and "+" or "−") .. math.abs(d), action = "crop_adj", value = side .. ":" .. d, variant = "secondary" }
    end
    kids[#kids + 1] = { type = "row", id = "crop-row-" .. side, gap = 6, align = "center", children = btns }
  end
  kids[#kids + 1] = { type = "row", id = "crop-presets", gap = 8, children = {
    { type = "button", id = "crop-none", label = tr("crop_none"), action = "crop_preset", value = "none", variant = "quiet" } } }
  if m.live and m.api then
    kids[#kids + 1] = { type = "button", id = "crop-apply", label = tr(m.state == "ready" and "crop_apply" or "map_take"),
      action = "map_capture", variant = "primary" }
  end
  if m.state == "ready" then kids[#kids + 1] = { type = "text", id = "crop-rescale", text = tr("crop_rescale"), style = "meta" } end
  return { type = "section", id = "crop", title = tr("crop_title"), children = kids }
end

local MAP_ERRORS = { busy = true, rate_limited = true, no_frame = true, unknown_screen = true, invalid_rect = true,
  too_large = true, unsupported = true, denied = true, failed = true }

--- Instruction, capture state and the error of the last try, then the capture button.
local function capture_block(ctx, m, retake)
  local tr = ctx.tr
  local kids = {}
  if not retake then
    kids[#kids + 1] = { type = "text", id = "map-hint", text = tr("map_hint"), style = "meta" }
  end
  if m.pending then
    kids[#kids + 1] = { type = "text", id = "map-wait", text = tr("map_waiting"), style = "meta" }
  elseif m.error then
    kids[#kids + 1] = { type = "text", id = "map-error", style = "meta",
      text = tr("map_err_" .. (MAP_ERRORS[m.error] and m.error or "failed")) }
  end
  return kids
end

--- Which source the Map tab shows: "screen" (take from the game picture) or "files" (candidates of the game
--- files). The player's choice, else the source of the stored map; only sources this app/core offers.
local function map_source(ctx, m)
  local screen_ok = m.api and m.live
  local files_ok = m.live and m.files and m.files.avail
  local want = ctx.ui.map_src or m.source
  if want == "files" and files_ok then return "files", screen_ok, files_ok end
  if screen_ok then return "screen", screen_ok, files_ok end
  return files_ok and "files" or "screen", screen_ok, files_ok
end

--- Source switch: only when both sources exist.
local function source_row(ctx, src, screen_ok, files_ok)
  if not (screen_ok and files_ok) then return nil end
  local tr = ctx.tr
  return { type = "row", id = "map-src", gap = 8, align = "center", children = {
    { type = "chip", id = "msrc-screen", text = tr("map_src_screen"), action = "map_src:screen", selected = src == "screen" },
    { type = "chip", id = "msrc-files", text = tr("map_src_files"), action = "map_src:files", selected = src == "files" } } }
end

--- Browse the images the core found in the game files: "n of N", preview, previous / next, "Use this map".
local function files_section(ctx, m)
  local tr, f = ctx.tr, m.files
  local kids = { { type = "text", id = "mf-hint", text = tr("map_files_hint"), style = "meta" } }
  if f.state ~= "done" then
    kids[#kids + 1] = { type = "text", id = "mf-wait", text = tr("map_files_searching"), style = "meta" }
  elseif f.n == 0 or not f.cand then
    kids[#kids + 1] = { type = "text", id = "mf-none", text = tr("map_files_none"), style = "meta" }
  else
    local c = f.cand
    local size = (c.w and c.h) and tr("map_files_size", { w = c.w, h = c.h }) or ""
    kids[#kids + 1] = { type = "text", id = "mf-pos", style = "body",
      text = tr("map_files_pos", { n = f.idx, total = f.n }) .. (size ~= "" and (" · " .. size) or "") }
    if c.src then
      kids[#kids + 1] = { type = "image", id = "mf-img", src = c.src, size = "l", label = tr("map_files_pos", { n = f.idx, total = f.n }) }
    else
      kids[#kids + 1] = { type = "text", id = "mf-load", style = "meta", text = tr(c.failed and "map_files_failed" or "map_files_loading") }
    end
    if c.suggested then kids[#kids + 1] = { type = "text", id = "mf-sug", text = tr("map_files_suggested"), style = "meta" } end
    if c.current then kids[#kids + 1] = { type = "text", id = "mf-cur", text = tr("map_files_current"), style = "meta" } end
    local row = {}
    if f.n > 1 then
      row[#row + 1] = { type = "button", id = "mf-prev", label = tr("map_files_prev"), action = "map_prev", variant = "secondary" }
      row[#row + 1] = { type = "button", id = "mf-next", label = tr("map_files_next"), action = "map_next", variant = "secondary" }
    end
    if c.src and not c.current then
      row[#row + 1] = { type = "button", id = "mf-use", label = tr("map_files_use"), action = "map_use", variant = "primary" }
    end
    if #row > 0 then kids[#kids + 1] = { type = "row", id = "mf-row", gap = 8, children = row } end
  end
  if f.error then
    kids[#kids + 1] = { type = "text", id = "mf-error", style = "meta",
      text = tr("map_err_" .. (MAP_ERRORS[f.error] and f.error or "failed")) }
  end
  return { type = "section", id = "mapfiles", title = tr("map_src_files"), children = kids }
end

--- Rows of the route card above the selected map point: one per person with the state on that route (5e-1).
local function route_popover(ctx, key)
  local view = ctx.view
  local row = common.row_of(view, key)
  if not row then return nil end
  local rows = {}
  for i, p in ipairs(view.players) do
    if #rows >= 16 then break end
    local cell = row.cells[p.id] or { state = "open" }
    local line = { owner = common.color(p, i), name = p.name, status = common.cell_text(cell, ctx.tr) }
    local src = cell.species and common.icon(ctx, cell.species, cell.form)
    if src then line.src = src end
    rows[#rows + 1] = line
  end
  return #rows > 0 and rows or nil
end

local function map_page(ctx)
  local view, m, tr = ctx.view, ctx.map, ctx.tr
  local src, screen_ok, files_ok = map_source(ctx, m)
  local switch = source_row(ctx, src, screen_ok, files_ok)
  if m.state ~= "ready" then
    -- no image yet: empty state (5e), then the chosen source; older app and no files: update hint
    if not screen_ok and not files_ok then
      return { type = "column", id = "page-map", gap = 12, children = {
        { type = "empty", id = "map-empty", title = tr("map_title"), text = tr(m.api and "map_empty_text" or "map_no_api") } } }
    end
    local kids = { { type = "empty", id = "map-empty", title = tr("map_title"), text = tr("map_empty_text") } }
    kids[#kids + 1] = switch
    if src == "files" then
      kids[#kids + 1] = files_section(ctx, m)
    else
      for _, b in ipairs(capture_block(ctx, m, false)) do kids[#kids + 1] = b end
      kids[#kids + 1] = { type = "row", id = "map-take-row", gap = 8, children = {
        { type = "button", id = "map-take", label = tr("map_take"), action = "map_capture", variant = "primary" },
        { type = "button", id = "map-crop", label = tr("crop_open"), action = "crop_toggle",
          variant = ctx.ui.crop_open and "primary" or "quiet" } } }
      if ctx.ui.crop_open then kids[#kids + 1] = crop_section(ctx, m) end
    end
    return { type = "column", id = "page-map", gap = 12, children = kids }
  end
  local players, routes, shown = {}, {}, {}
  for i, p in ipairs(view.players) do
    local c = p.place.key and m.coords[p.place.key]
    if c then
      players[#players + 1] = { id = p.id, initial = common.initial(p.name), color = common.color(p, i), x = c.x, y = c.y }
    end
  end
  local function route_marker(key)
    local c = m.coords[key]
    local r = common.row_of(view, key)
    local icons = {}
    if r then
      for i, p in ipairs(view.players) do
        local cell = r.cells[p.id]
        local src = cell and cell.species and common.icon(ctx, cell.species, nil)
        if src and #icons < 8 then icons[#icons + 1] = { src = src, owner = common.color(p, i) } end
      end
    end
    routes[#routes + 1] = { id = key, x = c.x, y = c.y, area = c.area, number = r and r.group and r.group.number or nil,
      done = r and r.done or false, icons = #icons > 0 and icons or nil }
  end
  for _, r in ipairs(view.rows) do
    if m.coords[r.route] then route_marker(r.route); shown[r.route] = true end
  end
  local extra = {}
  for key in pairs(m.coords) do if not shown[key] then extra[#extra + 1] = key end end
  table.sort(extra, function(a, b) return oras.compare(a, b, view.order) end)
  for _, key in ipairs(extra) do route_marker(key) end
  local calib = ctx.ui.calib
  if calib and calib.x then
    players[#players + 1] = { id = "cursor", initial = "+", color = 1, x = calib.x, y = calib.y }
  end
  local map = { type = "map", id = "map", players = players, routes = routes, filter = ctx.ui.map_filter or "all",
    me = ctx.me, legend = true, action = "map_select", image = m.src, image_w = m.w, image_h = m.h }
  if ctx.ui.selected_route then
    map.selected = ctx.ui.selected_route
    local pop = route_popover(ctx, ctx.ui.selected_route)
    if pop then map.popover = pop end
  end
  local acts = { { type = "button", id = "map-calib", label = tr("calib_open"), action = "calib_toggle",
    variant = calib and "primary" or "quiet" } }
  if screen_ok then
    acts[#acts + 1] = { type = "button", id = "map-retake", label = tr("map_retake"), action = "map_capture", variant = "quiet" }
    acts[#acts + 1] = { type = "button", id = "map-crop", label = tr("crop_open"), action = "crop_toggle",
      variant = ctx.ui.crop_open and "primary" or "quiet" }
  end
  acts[#acts + 1] = { type = "button", id = "map-remove", label = tr("map_remove"), action = "map_remove", variant = "quiet",
    confirm = { title = tr("map_remove_title"), text = tr("map_remove_text"), confirm_label = tr("map_remove") } }
  local kids = { { type = "text", id = "map-source", text = tr(src == "files" and "map_from_files" or "map_from_screen"), style = "eyebrow" },
    map, { type = "row", id = "map-acts", gap = 8, children = acts } }
  kids[#kids + 1] = switch
  if src == "files" then
    kids[#kids + 1] = files_section(ctx, m)
  else
    for _, b in ipairs(capture_block(ctx, m, true)) do kids[#kids + 1] = b end
  end
  if ctx.ui.crop_open and screen_ok then kids[#kids + 1] = crop_section(ctx, m) end
  if calib then kids[#kids + 1] = calibration(ctx, m) end
  return { type = "column", id = "page-map", gap = 12, children = kids }
end

--- Tab order for the current data: Map | Routes | Team & box | Graveyard | Event log. The Map tab
--- leads only with a confirmed image; while it is being set up it follows Routes; hidden when the
--- game has no map to offer.
function M.tab_ids(ctx)
  local ids = {}
  local ready = ctx ~= nil and ctx.map ~= nil and ctx.map.state == "ready"
  if ready then ids[#ids + 1] = "map" end
  ids[#ids + 1] = "routes"
  if M.has_map(ctx) and not ready then ids[#ids + 1] = "map" end
  for _, id in ipairs({ "team", "grave", "log" }) do ids[#ids + 1] = id end
  return ids
end

function M.build(ctx)
  local tr, view = ctx.tr, ctx.view
  local ids = M.tab_ids(ctx)
  local labels, pages = {}, {}
  for i, id in ipairs(ids) do
    labels[i] = tr("tab_" .. id)
    local builders = { map = map_page, routes = routes_page, team = team_page, grave = graveyard_page, log = log_page }
    pages[i] = builders[id](ctx)
  end
  -- the selection is kept by tab id: the list changes (the Map tab comes and goes), an index would then
  -- point at another tab; the first tab is selected until the player picks one
  local sel = 1
  for i, id in ipairs(ids) do if id == ctx.ui.screen_tab_id then sel = i end end
  local kids = {}
  kids[#kids + 1] = header(ctx)
  local corr = corr_ui.section(ctx)
  if corr then kids[#kids + 1] = corr end
  kids[#kids + 1] = { type = "tabs", id = "tabs", tabs = labels, selected = sel, action = "tab", children = pages }
  kids[#kids + 1] = settings_foot(ctx)
  return { type = "column", id = "screen", gap = 16, children = kids }
end

return M

end
__mod["ui.tile"] = function(...)
-- Strip on a friend's Multiview tile (design 5d): "SL <place> · <n> alive" (first text row).
local common = require("ui.common")

local M = {}

--- player = view player entry of the tile's owner; view supplies the stored place names.
function M.build(tr, player, view)
  return { type = "text", id = "tile", text = tr("tile_strip", { place = common.short(common.place_label(player.place, tr, view), 24), n = player.alive }),
    style = "meta" }
end

--- Match the host event `tiles` ({ id, player, user_id, game }) to view players: by `user_id` first
--- (empty string = unknown), by name (case-insensitive) as fallback. Returns { [tile id] = player }.
function M.match(tiles, view)
  local out = {}
  for _, t in ipairs(type(tiles) == "table" and tiles or {}) do
    if type(t) == "table" and type(t.id) == "string" and t.id:match("^[%w_.%-]+$") and #t.id <= 64 then
      local found
      if type(t.user_id) == "string" and t.user_id ~= "" then
        for _, p in ipairs(view.players) do
          if p.id == t.user_id then found = p; break end
        end
      end
      if not found and type(t.player) == "string" then
        for _, p in ipairs(view.players) do
          if tostring(p.name):lower() == t.player:lower() then found = p; break end
        end
      end
      out[t.id] = found
    end
  end
  return out
end

return M

end
require("main")
